function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function fmtDate(v){if(!v)return'—';const d=new Date(v.length===10?v+'T00:00:00':v);return isNaN(d)?esc(v):d.toLocaleDateString('vi-VN')}
function fmtDateTime(v){if(!v)return'—';const d=new Date(String(v).replace(' ','T'));return isNaN(d)?esc(v):d.toLocaleString('vi-VN',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})}
function toast(msg,kind=''){const t=$('#toast');t.textContent=msg;t.className='toast show '+kind;clearTimeout(t._timer);t._timer=setTimeout(()=>t.className='toast',2600)}
function nativeUrl(raw){const src=String(raw||'');if(!/NAHISOAndroid\//i.test(navigator.userAgent||''))return src;try{const u=new URL(src,location.href),here=new URL(location.href),norm=h=>String(h||'').toLowerCase().replace(/^www\./,'');if(norm(u.hostname)===norm(here.hostname)&&u.origin!==here.origin){u.protocol=here.protocol;u.host=here.host}return u.href}catch(_e){return src}}
function restBase(){let b=nativeUrl(cfg.restUrl||'/wp-json/nah-iso15189/v1/');return b.endsWith('/')?b:b+'/'}
function loginEndpoint(){return nativeUrl(cfg.loginUrl||restBase()+'auth/login')}
async function api(path,opt={}){
 const headers={'Accept':'application/json'};
 const method=String(opt.method||'GET').toUpperCase();
 let body=opt.body;
 if(opt.json!==undefined){headers['Content-Type']='application/json';body=JSON.stringify(opt.json)}
 if(state.boot?.user?.csrf)headers['X-NAH-CSRF']=state.boot.user.csrf;
 const dedupeKey=(method==='GET'&&!body&&!opt.noDedupe)?`${restBase()}${path}`:'';
 if(dedupeKey&&state.apiInflight.has(dedupeKey))return state.apiInflight.get(dedupeKey);
 const run=async()=>{
  const controller=(typeof AbortController!=='undefined'&&opt.timeoutMs)?new AbortController():null;
  const timer=controller?setTimeout(()=>controller.abort(),Math.max(1000,+opt.timeoutMs||15000)):null;
  let res;
  try{
   res=await fetch(restBase()+path,{method,headers:{...headers,...(opt.headers||{})},body,credentials:'same-origin',cache:opt.cache||'no-store',signal:controller?.signal});
  }catch(e){
   if(e?.name==='AbortError'){const err=new Error('Dữ liệu tải quá lâu. Vui lòng thử lại.');err.code='request_timeout';throw err}
   throw e;
  }finally{if(timer)clearTimeout(timer)}
  let data=null;try{data=await res.json()}catch(e){}
  if(!res.ok){const code=data?.code||'';const msg=data?.message||`Lỗi ${res.status}`;const err=new Error(msg);err.status=res.status;err.code=code;throw err}
  if(method!=='GET'){state.dashboardSnapshot=null;state.dashboardSnapshotAt=0}
  return data;
 };
 if(!dedupeKey)return run();
 const promise=run();state.apiInflight.set(dedupeKey,promise);
 try{return await promise}finally{if(state.apiInflight.get(dedupeKey)===promise)state.apiInflight.delete(dedupeKey)}
}
function updateClientVersionLabel(){const el=$('.login-version-line');if(!el)return;const kind=nativeClientKind(),version=nativeClientVersion(kind);el.textContent=kind&&version?`${kind==='android'?'Android':'Windows'} v${version} · Web v${cfg.version||''}`:`Web v${cfg.version||''}`;}
function nativeClientKind(){const ua=navigator.userAgent||'';if(/NAHISOAndroid\//i.test(ua))return'android';if(/(?:NAHISODesktop|NAHISONative|NAHLABDesktop)\//i.test(ua))return'desktop';return''}
function nativeClientVersion(kind){if(!kind)return'';const pattern=kind==='android'?/NAHISOAndroid\/([0-9]+(?:\.[0-9]+){1,3})/i:/(?:NAHISODesktop|NAHISONative|NAHLABDesktop)\/([0-9]+(?:\.[0-9]+){1,3})/i;return(navigator.userAgent||'').match(pattern)?.[1]||'';}
function compareNativeVersions(a,b){if(!/^\d+(?:\.\d+){1,3}$/.test(a)||!/^\d+(?:\.\d+){1,3}$/.test(b))return null;const x=a.split('.').map(Number),y=b.split('.').map(Number);for(let i=0;i<Math.max(x.length,y.length);i++){const m=x[i]||0,n=y[i]||0;if(m!==n)return m>n?1:-1}return 0;}
function trustedNativeUpdateUrl(raw){try{const u=new URL(String(raw||''));const host=u.hostname.toLowerCase();return u.protocol==='https:'&&['sachyhoc.com','www.sachyhoc.com'].includes(host)&&/\/updates\/[^/]+\.(?:apk|zip)$/i.test(u.pathname)?u.href:''}catch(_e){return''}}
let nativeUpdateBlocking=false;
function showNativeUpdateDialog({kind,current,latest,url,required,requiresReinstall,notes}){
 const stale=$('#nahNativeUpdateGate');if(stale)stale.remove();
 const overlay=document.createElement('div');overlay.id='nahNativeUpdateGate';overlay.className='nah-native-update-overlay';overlay.setAttribute('role','presentation');
 const label=kind==='android'?'Android':'Windows';const caution=requiresReinstall?'Trước khi gỡ bản cũ, hãy bảo đảm mọi thay đổi đã được đồng bộ lên máy chủ. Bản cập nhật này có thể yêu cầu cài đặt lại ứng dụng.':'';
 overlay.innerHTML=`<section class="nah-native-update-dialog" role="alertdialog" aria-modal="true" aria-labelledby="nahNativeUpdateTitle" aria-describedby="nahNativeUpdateDescription"><div class="nah-native-update-icon" aria-hidden="true">↑</div><h2 id="nahNativeUpdateTitle">${required?'Bạn cần cập nhật ứng dụng':'Đã có phiên bản ứng dụng mới'}</h2><p id="nahNativeUpdateDescription">Đã có phiên bản <strong>${esc(label)} v${esc(latest)}</strong> mới hơn phiên bản đang sử dụng <strong>v${esc(current)}</strong>. Bản cập nhật bổ sung dữ liệu, tính năng và các sửa lỗi để hệ thống hoạt động ổn định.</p>${caution?`<p class="nah-native-update-caution">${esc(caution)}</p>`:''}${notes?`<p class="nah-native-update-notes">${esc(notes)}</p>`:''}<div class="nah-native-update-actions"><a id="nahNativeUpdateDownload" class="btn primary" href="${esc(url)}" target="${kind==='android'?'_self':'_blank'}" rel="noopener noreferrer">Tải bản ${esc(label)} v${esc(latest)}</a>${required?'':'<button id="nahNativeUpdateLater" class="btn" type="button">Để sau</button>'}</div><p class="nah-native-update-help">Sau khi cài đặt bản mới, hãy mở lại ứng dụng để tiếp tục làm việc.</p></section>`;
 document.body.appendChild(overlay);nativeUpdateBlocking=!!required;
 if(kind==='desktop' && entryPointNativeUpdaterSupported()){
   const download=overlay.querySelector('#nahNativeUpdateDownload');
   if(download){download.href='nahiso-update://install';download.removeAttribute('target');download.textContent='Cập nhật tại chỗ (giữ dữ liệu)';download.addEventListener('click',e=>{e.preventDefault();window.open('nahiso-update://install','_blank','noopener')});}
 }
 overlay.querySelector('#nahNativeUpdateDownload')?.focus();
 if(!required){overlay.querySelector('#nahNativeUpdateLater')?.addEventListener('click',()=>{overlay.remove();nativeUpdateBlocking=false})}
 // Do not dismiss a mandatory update by tapping outside or pressing Escape.
 overlay.addEventListener('keydown',e=>{if(!required)return;if(e.key==='Escape'){e.preventDefault();e.stopPropagation()}if(e.key==='Tab'){e.preventDefault();overlay.querySelector('#nahNativeUpdateDownload')?.focus()}});
}
function entryPointNativeUpdaterSupported(){return nativeClientKind()==='desktop'&&compareNativeVersions(nativeClientVersion('desktop'),'1.3.26')!==-1}
async function checkNativeUpdateRequired(){
 const kind=nativeClientKind(),current=nativeClientVersion(kind);if(!kind||!current)return false;
 let controller=null,timer=null;try{
  if(typeof AbortController!=='undefined'){controller=new AbortController();timer=setTimeout(()=>controller.abort(),6500)}
  const r=await fetch(restBase()+'app/update-manifest?_ts='+Date.now(),{method:'GET',credentials:'same-origin',cache:'no-store',headers:{'Accept':'application/json'},signal:controller?.signal});if(!r.ok)return false;
  const m=await r.json(),entry=m?.platforms?.[kind],latest=String(entry?.version||''),url=trustedNativeUpdateUrl(entry?.downloadUrl);
  if(!entry?.available||entry.releaseReady!==true||!url||compareNativeVersions(current,latest)!==-1)return false;
  // A release still awaiting signing/device acceptance can notify, but must never lock out staff.
  const ready=entry.releaseReady===true&&entry.baselineStatus!=='new-signing-baseline-pending-device-qa';
  const required=entry.mandatory===true&&ready;
  showNativeUpdateDialog({kind,current,latest,url,required,requiresReinstall:!!entry.requiresReinstall,notes:String(entry.releaseNotes||'')});
  return required;
 }catch(_e){return false}finally{if(timer)clearTimeout(timer)}
}

async function nativeStartGuard(){const kind=nativeClientKind();if(!kind)return true;const key='nahIsoNativeStartGuardV7:'+kind;let seen=false;try{seen=sessionStorage.getItem(key)==='1'}catch(_e){}if(seen)return true;let res,payload=null;try{const url=restBase()+'auth/client-start?nah_client_start=1';res=await fetch(url,{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Accept':'application/json','Content-Type':'text/plain;charset=UTF-8'},body:'{}'});try{payload=await res.json()}catch(_e){}}catch(_e){throw new Error('Không thể kết nối máy chủ xác thực ứng dụng. Vui lòng kiểm tra kết nối mạng và thử lại.')}if(!res.ok||payload?.clientKind!==kind)throw new Error(payload?.message||'Không thể xác nhận phiên ứng dụng. Vui lòng thử lại.');if(kind==='desktop'){if(payload?.freshLoginRequired!==false||!['online-validated-device','persistent-device'].includes(payload?.sessionPolicy))throw new Error('Không thể xác lập phiên Desktop. Vui lòng kiểm tra kết nối mạng và mở lại ứng dụng.')}else if(kind==='android'){if(payload?.freshLoginRequired!==false||payload?.sessionPolicy!=='persistent')throw new Error('Không thể xác lập phiên Android cá nhân. Vui lòng mở lại ứng dụng.')}try{sessionStorage.setItem(key,'1')}catch(_e){}return true}
