function hideSubmenuTooltip(){const tip=$('#dockMenuContextText');if(tip)tip.textContent=currentDockGroups()[state.dockActive]?.tooltip||'Rê chuột vào chức năng để xem mô tả.';$$('#dockMenuBody [aria-describedby="dockMenuContext"]').forEach(b=>b.removeAttribute('aria-describedby'))}
function showSubmenuTooltip(button){if(!hoverRailEnabled())return;const description=button?.dataset.description,tip=$('#dockMenuContextText');if(!description||!tip)return;hideRailTooltip();tip.textContent=description;$$('#dockMenuBody [aria-describedby="dockMenuContext"]').forEach(b=>b.removeAttribute('aria-describedby'));button.setAttribute('aria-describedby','dockMenuContext')}
function showRailTooltip(button){if(!hoverRailEnabled())return;const key=button?.dataset.dock,g=currentDockGroups()[key];if(!g?.direct)return;let tip=$('#railTooltip');if(!tip){tip=document.createElement('div');tip.id='railTooltip';tip.className='rail-tooltip';tip.setAttribute('role','tooltip');tip.hidden=true;document.body.append(tip)}tip.textContent=g.label;const rect=button.getBoundingClientRect();tip.style.left=(rect.right+9)+'px';tip.style.top=Math.max(8,Math.min(rect.top+rect.height/2-17,innerHeight-46))+'px';tip.hidden=false}
function syncDockTabs(){const current=dockGroupForModule(state.module);$$('#nav [data-dock]').forEach(b=>{const selected=b.dataset.dock===current;b.classList.toggle('active',selected);b.classList.toggle('expanded',!$('#dockMenu').hidden&&state.dockActive===b.dataset.dock);if(selected)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');b.setAttribute('aria-expanded',String(!$('#dockMenu').hidden&&state.dockActive===b.dataset.dock))})}
function closeDockMenu(resetActive=false){clearDockHoverClose();hideRailTooltip();hideSubmenuTooltip();const layer=$('#dockMenu');if(!layer)return;layer.hidden=true;layer.setAttribute('aria-hidden','true');document.body.classList.remove('dock-menu-open');state.dockSubgroup='';if(resetActive){state.dockActive=null;syncDockTabs()}}
