function positionDockPanel(){if(innerWidth<768)return;const anchor=$('#nav [data-dock="'+state.dockActive+'"]'),panel=$('.dock-menu-panel');if(!anchor||!panel)return;const topbar=innerWidth>=1200?Number.parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--ui158-topbar'))||72:68;const maxHeight=innerHeight-topbar-20;const height=Math.min(panel.getBoundingClientRect().height,maxHeight);const rect=anchor.getBoundingClientRect();const top=Math.max(topbar+8,Math.min(rect.top+rect.height/2-height/2,innerHeight-height-10));panel.style.setProperty('--dock-flyout-top',top+'px')}
