const searchTypeLabels={record:'Nội dung',evidence:'Hồ sơ bằng chứng',external_document:'Tài liệu bên ngoài',handbook:'Sổ tay ISO 15189',learning:'Bài học ISO 15189',clause:'Yêu cầu ISO 15189',procedure:'Quy trình & công cụ',form:'Biểu mẫu & hồ sơ',source:'Tài liệu tham khảo / bài giảng',implementation:'Kế hoạch triển khai',competency:'Năng lực & ủy quyền',resource:'Thiết bị / hóa chất / vật tư',method_quality:'Chất lượng phương pháp'};
function closeGlobalSearch(){const p=$('#globalSearchPanel'),i=$('#globalSearch');if(p){p.hidden=true;p.innerHTML=''}if(i)i.setAttribute('aria-expanded','false')}
function searchResultIcon(item){const k=item.module&&iconPaths[item.module]?item.module:(item.type==='source'?'documents':item.type==='form'?'forms':item.type==='procedure'?'toolkit':'fallback');return iconSvg(k)}
function renderGlobalSearchPanel(payload,q){
 const panel=$('#globalSearchPanel'),input=$('#globalSearch'),clear=$('#globalSearchClear');if(!panel||!input)return;
 const items=payload?.results||[];state.searchItems=items;clear.hidden=!q;input.setAttribute('aria-expanded','true');panel.hidden=false;
 if(q.length<2){panel.innerHTML='<div class="global-search-hint"><strong>Tìm trong toàn bộ hệ thống quản lý chất lượng xét nghiệm</strong><span>Nhập ít nhất 2 ký tự để tìm quy trình, biểu mẫu, bài học, hướng dẫn, điều khoản ISO và công việc.</span></div>';return}
 if(!items.length){panel.innerHTML=`<div class="global-search-empty">Không tìm thấy nội dung phù hợp với <strong>${esc(q)}</strong>.</div>`;return}
 let last='';let html=`<div class="global-search-summary"><strong>${items.length} kết quả</strong><span>“${esc(q)}”</span></div>`;
 items.forEach((item,idx)=>{const group=searchTypeLabels[item.type]||'Kết quả';if(group!==last){html+=`<div class="global-search-group">${esc(group)}</div>`;last=group}html+=`<button class="global-search-result" type="button" data-search-index="${idx}" role="option"><span class="global-search-result-icon">${searchResultIcon(item)}</span><span class="global-search-result-copy"><strong>${esc(item.title||'Không tiêu đề')}</strong><small>${item.code?`<b>${esc(item.code)}</b> · `:''}${esc(item.subtitle||'')}</small>${item.snippet?`<em>${esc(item.snippet)}</em>`:''}</span><span class="global-search-open">›</span></button>`});
 panel.innerHTML=html;$$('[data-search-index]',panel).forEach(b=>b.onclick=()=>openGlobalSearchItem(state.searchItems[+b.dataset.searchIndex]));
}
async function runGlobalSearch(raw){const q=String(raw||'').trim();const seq=++state.searchSeq;const clear=$('#globalSearchClear');if(clear)clear.hidden=!q;if(q.length<2){renderGlobalSearchPanel({results:[]},q);return}const panel=$('#globalSearchPanel');if(panel){panel.hidden=false;panel.innerHTML='<div class="global-search-loading">Đang tìm trong Sổ tay, quy trình, biểu mẫu, bài học và hồ sơ…</div>'}try{const data=await api(`search?q=${encodeURIComponent(q)}`);if(seq!==state.searchSeq)return;renderGlobalSearchPanel(data,q)}catch(e){if(seq!==state.searchSeq)return;if(panel){panel.hidden=false;panel.innerHTML=`<div class="global-search-empty">${esc(e.message)}</div>`}}}
async function openGlobalSearchItem(item){if(!item)return;closeGlobalSearch();const input=$('#globalSearch');if(input)input.value='';
 if(item.type==='record'&&item.id){return openRecord(+item.id)}
 if(item.type==='evidence'&&item.id){state.ecTab='registry';await go('evidencehub');return openEvidenceRegistryItem(+item.id)}
 if(item.type==='external_document'&&item.id){state.ecTab='external';await go('evidencehub');const d=await api('evidence-control/external-documents');const x=(d.items||[]).find(v=>+v.id===+item.id);if(x)openExternalDocument(x,d.canManage);return}
 if(item.type==='handbook'){await go('handbook');const data=await api('knowledge/handbook');const ch=(data.chapters||[]).find(x=>x.slug===item.slug);if(ch)openDrawer(ch.title,'handbook',handbookChapterHtml(ch),{layout:'modal'});return}
 if(item.type==='learning'){await go('learning');const data=await api('knowledge/learning');const l=(data.lessons||[]).find(x=>x.slug===item.slug);if(l){openDrawer(l.title,'learning',lessonHtml(l),{layout:'modal'});wireLessonQuiz(l)}return}
 if(item.type==='clause'){await go('iso');state.query=item.code||item.title||'';await renderList('iso');return}
 if(item.type==='competency'){await go('competency');return}if(item.type==='resource'){await go('resources');return}if(item.type==='method_quality'){await go('methodquality');return}if(item.type==='process_assurance'){await go('processassurance');return}
 if(item.type==='procedure'||item.type==='form'||item.type==='source'){await go('toolkit');const si=$('#sourceSearch');if(si){si.value=item.code||item.title||'';si.dispatchEvent(new Event('input',{bubbles:true}));si.scrollIntoView({behavior:'smooth',block:'center'})}return}
 if(item.type==='implementation'){await go('implementation');return}
 if(item.module&&moduleMeta[item.module])await go(item.module);
}
function statusTabs(){return `<div class="tabs"><button class="tab ${!state.status?'active':''}" data-status="">Tất cả</button>${['new','open','in_progress','review','approved','done','closed'].map(s=>`<button class="tab ${state.status===s?'active':''}" data-status="${s}">${esc(statusLabels[s])}</button>`).join('')}</div>`}
const documentStateLabels={draft:'Soạn thảo',review:'Chờ rà soát',reviewed:'Đã rà soát',approved:'Đã phê duyệt',issued:'Đang ban hành',withdrawn:'Đã thu hồi',archived:'Phiên bản cũ'};
function documentStateClass(s){return ['draft','review','reviewed','approved','issued','withdrawn','archived'].includes(s)?s:'draft'}
function documentLifecycleSteps(state){const steps=[['draft','Soạn thảo'],['review','Rà soát'],['approved','Phê duyệt'],['issued','Ban hành'],['distribution','Phân phối'],['ack','Xác nhận đã đọc']];const order={draft:0,review:1,reviewed:2,approved:2,issued:3,withdrawn:3,archived:3};const idx=state==null?-1:(order[state]??0);return `<div class="doc-stepper">${steps.map((x,i)=>`<div class="doc-step ${i<=idx?'done':''} ${i===idx?'current':''}"><i>${i<idx?'✓':i+1}</i><span>${x[1]}</span></div>`).join('')}</div>`}
