function statusOptions(v,module=''){const keys=module==='docplan'?['new','in_progress','draft','review','changes_requested','approved','issued']:['new','draft','active','open','in_progress','review','approved','done','closed','monitoring'];return keys.map(k=>`<option value="${k}" ${v===k?'selected':''}>${esc(module==='docplan'?documentPlanStatusLabel(k):(statusLabels[k]||k))}</option>`).join('')}
function priorityOptions(v){return ['low','normal','high','critical'].map(k=>`<option value="${k}" ${v===k?'selected':''}>${esc(priorityLabels[k])}</option>`).join('')}
function ownerOptions(v){const a=state.boot.user;const current=(state.boot.users||[]).find(u=>u.ref===v);let users=[{ref:a.ref,name:a.name,roleLabel:a.roleLabel},...(current?[current]:[]),...(state.boot.assignableUsers||[])];const seen=new Set();users=users.filter(u=>u.ref&&!seen.has(u.ref)&&seen.add(u.ref));return `<option value="">Chưa phân công</option>`+users.map(u=>`<option value="${esc(u.ref)}" ${v===u.ref?'selected':''}>${esc(u.name)} — ${esc(u.roleLabel||'')}</option>`).join('')}
function syncDialogViewport(){const vv=window.visualViewport;const w=Math.max(280,Math.floor(vv?.width||window.innerWidth||1024)),h=Math.max(360,Math.floor(vv?.height||window.innerHeight||768));document.documentElement.style.setProperty('--dialog-vw',`${w}px`);document.documentElement.style.setProperty('--dialog-vh',`${h}px`);document.documentElement.style.setProperty('--app-vh',`${h}px`);document.documentElement.style.setProperty('--app-vw',`${w}px`);const d=$('#drawer');if(d)d.dataset.viewport=w<640?'mobile':w<1024?'tablet':'desktop'}
function openDrawer(title,module,html,opts={}){syncDialogViewport();const drawer=$('#drawer');drawer.dataset.layout='modal';drawer.classList.add('centered');$('#drawerTitle').textContent=title;$('#drawerModule').textContent=(moduleMeta[module]?.label||module||'Bản ghi').toUpperCase();$('#drawerBody').innerHTML=html;drawer.classList.add('open');drawer.setAttribute('aria-hidden','false')}
function closeDrawer(){const drawer=$('#drawer');drawer.classList.remove('open','centered');drawer.dataset.layout='';drawer.setAttribute('aria-hidden','true');state.current=null}
if(window.visualViewport)window.visualViewport.addEventListener('resize',syncDialogViewport);window.addEventListener('resize',syncDialogViewport);window.addEventListener('orientationchange',syncDialogViewport);
function recordInfoHtml(module,r={}){return `<form id="recordForm"><div class="form-grid"><div class="field"><label>Mã / số hiệu</label><input name="code" value="${esc(r.code||'')}"></div><div class="field"><label>Trạng thái</label><select name="status">${statusOptions(r.status||'new',module)}</select></div><div class="field full"><label>Tiêu đề *</label><input name="title" required value="${esc(r.title||'')}"></div><div class="field full"><label>Mô tả / yêu cầu / ghi chú</label><textarea name="description">${esc(r.description||'')}</textarea></div><div class="field"><label>Đầu mối phụ trách</label><select name="owner_ref">${ownerOptions(r.owner_ref||'')}</select></div><div class="field"><label>Mức ưu tiên</label><select name="priority">${priorityOptions(r.priority||'normal')}</select></div><div class="field"><label>Hạn hoàn thành</label><input type="date" name="due_date" value="${esc(r.due_date||'')}"></div><div class="field"><label>Tiến độ (%)</label><input type="number" min="0" max="100" name="progress" value="${esc(r.progress??0)}"></div>${moduleExtras(module,r.data||{})}</div><div class="form-actions"><button type="button" class="btn" data-close>Hủy</button>${r.id?'<button type="button" class="btn" id="printRecord">In A4</button><button type="button" class="btn" id="pdfRecord">PDF A4</button><button type="button" class="btn" id="docxRecord">DOCX A4</button>':''}<button class="btn primary" type="submit">${r.id?'Lưu thay đổi':'Tạo bản ghi'}</button></div></form>`}
function drawerTabs(r){if(r.module==='certprogress')return `<div class="drawer-tabs drawer-tabs-cert"><button class="drawer-tab ${state.drawerTab==='info'?'active':''}" data-dtab="info">Hạng mục</button>${!r.parent_id?`<button class="drawer-tab ${state.drawerTab==='checklist'?'active':''}" data-dtab="checklist">Danh mục cần hoàn thiện</button>`:''}<button class="drawer-tab ${state.drawerTab==='assign'?'active':''}" data-dtab="assign">Phân công <span class="meta">(${(r.assignments||[]).length})</span></button><button class="drawer-tab ${state.drawerTab==='progress'?'active':''}" data-dtab="progress">Cập nhật tiến độ</button><button class="drawer-tab ${state.drawerTab==='evidence'?'active':''}" data-dtab="evidence">Minh chứng <span class="meta">(${(r.evidence||[]).length})</span></button><button class="drawer-tab ${state.drawerTab==='chat'?'active':''}" data-dtab="chat">Trao đổi <span class="meta">(${(r.comments||[]).length})</span></button><button class="drawer-tab ${state.drawerTab==='history'?'active':''}" data-dtab="history">Lịch sử</button></div><div id="drawerTabBody"></div>`;if(r.module==='documents'||r.module==='forms')return documentTabs(r);if(r.module==='iso')return `<div class="drawer-tabs drawer-tabs-iso"><button class="drawer-tab ${state.drawerTab==='info'?'active':''}" data-dtab="info">Yêu cầu cần đáp ứng</button><button class="drawer-tab ${state.drawerTab==='guidance'?'active':''}" data-dtab="guidance">Cách thực hiện</button><button class="drawer-tab ${state.drawerTab==='handbook'?'active':''}" data-dtab="handbook">Học cách làm</button><button class="drawer-tab ${state.drawerTab==='assign'?'active':''}" data-dtab="assign">Việc cần làm <span class="meta">(${(r.assignments||[]).length})</span></button><button class="drawer-tab ${state.drawerTab==='progress'?'active':''}" data-dtab="progress">Cập nhật tiến độ</button><button class="drawer-tab ${state.drawerTab==='evidence'?'active':''}" data-dtab="evidence">Bằng chứng <span class="meta">(${(r.evidence||[]).length})</span></button><button class="drawer-tab ${state.drawerTab==='forms'?'active':''}" data-dtab="forms">Biểu mẫu</button><button class="drawer-tab ${state.drawerTab==='chat'?'active':''}" data-dtab="chat">Trao đổi <span class="meta">(${(r.comments||[]).length})</span></button><button class="drawer-tab ${state.drawerTab==='history'?'active':''}" data-dtab="history">Lịch sử cập nhật</button></div><div id="drawerTabBody"></div>`;if(['risks','audits','nc','capa','meetings'].includes(r.module))return `<div class="drawer-tabs drawer-tabs-qms"><button class="drawer-tab ${state.drawerTab==='info'?'active':''}" data-dtab="info">Thông tin</button><button class="drawer-tab ${state.drawerTab==='qms'?'active':''}" data-dtab="qms">Liên kết xử lý</button><button class="drawer-tab ${state.drawerTab==='assign'?'active':''}" data-dtab="assign">Phân công <span class="meta">(${(r.assignments||[]).length})</span></button><button class="drawer-tab ${state.drawerTab==='progress'?'active':''}" data-dtab="progress">Tiến độ</button><button class="drawer-tab ${state.drawerTab==='evidence'?'active':''}" data-dtab="evidence">Bằng chứng <span class="meta">(${(r.evidence||[]).length})</span></button><button class="drawer-tab ${state.drawerTab==='chat'?'active':''}" data-dtab="chat">Trao đổi <span class="meta">(${(r.comments||[]).length})</span></button><button class="drawer-tab ${state.drawerTab==='history'?'active':''}" data-dtab="history">Lịch sử</button></div><div id="drawerTabBody"></div>`;return `<div class="drawer-tabs"><button class="drawer-tab ${state.drawerTab==='info'?'active':''}" data-dtab="info">Thông tin</button><button class="drawer-tab ${state.drawerTab==='assign'?'active':''}" data-dtab="assign">Phân công <span class="meta">(${(r.assignments||[]).length})</span></button><button class="drawer-tab ${state.drawerTab==='progress'?'active':''}" data-dtab="progress">Cập nhật tiến độ</button><button class="drawer-tab ${state.drawerTab==='chat'?'active':''}" data-dtab="chat">Trao đổi <span class="meta">(${(r.comments||[]).length})</span></button><button class="drawer-tab ${state.drawerTab==='evidence'?'active':''}" data-dtab="evidence">Bằng chứng <span class="meta">(${(r.evidence||[]).length})</span></button></div><div id="drawerTabBody"></div>`}
function collectForm(module,form){const fd=new FormData(form),data={module};for(const [k,v] of fd.entries())data[k]=v;data.progress=+data.progress||0;data.data={};form.querySelectorAll('[data-extra]').forEach(i=>data.data[i.dataset.extra]=i.value);return data}
function isoClause(r){return String(r?.data?.clause||r?.code||'').replace(/^ISO-/i,'').trim()}
async function loadIsoContext(r){const clause=isoClause(r);if(!clause)return {requirement:{},handbook:[],procedures:[],records:[],sources:[],archives:[]};if(state.isoContextCache[clause])return state.isoContextCache[clause];const ctx=await api(`knowledge/context?clause=${encodeURIComponent(clause)}`,{cache:'no-store'});state.isoContextCache[clause]=ctx;r._context=ctx;return ctx}
function sourceLinkHtml(x){if(x.appUrl)return `<a class="source-link" href="${esc(x.appUrl)}" target="_blank" rel="noopener"><strong>${esc(x.name||x.title||'Tài liệu')}</strong><small>${esc(x.path||x.category||'')}</small></a>`;return `<div class="source-link static"><strong>${esc(x.name||x.title||x.path||'Tài liệu')}</strong><small>${esc(x.archive||x.category||'')}</small></div>`}
function activityHtml(r){const rows=(r.activity||[]).map(a=>{let d={};try{d=typeof a.detail==='object'&&a.detail?a.detail:JSON.parse(a.detail_json||'{}')}catch(e){}const extra=Object.entries(d||{}).filter(([,v])=>v!==''&&v!==null&&v!==undefined).map(([k,v])=>`${uiFieldLabel(k)}: ${Array.isArray(v)?v.join(', '):v}`).join(' · ');return `<div class="timeline-item"><i></i><div><strong>${esc(actionLabels[a.action]||a.action||'Cập nhật')}</strong><div class="meta">${esc(a.actor_name||a.actor_ref||'Hệ thống')} · ${fmtDateTime(a.created_at||'')}</div>${extra?`<div class="activity-detail">${esc(extra)}</div>`:''}</div></div>`}).join('')||'<div class="note">Chưa có lịch sử thao tác cho bản ghi này.</div>';return `<div class="section-title">Lịch sử truy vết</div><div class="timeline">${rows}</div>`}
function sourceReferenceCardsHtml(refs){const rows=(refs||[]).filter(x=>x&&/^https:\/\//i.test(x.url||''));if(!rows.length)return '';return `<div class="iso-reference-list">${rows.map(x=>`<a class="iso-reference-card" href="${esc(x.url)}" target="_blank" rel="noopener"><span>${esc(x.kind||'Tài liệu tham khảo')}</span><strong>${esc(x.title||'')}</strong><small>${esc(x.organization||'')}${x.year?` · ${esc(x.year)}`:''}</small>${x.access?`<em>${esc(x.access)}</em>`:''}</a>`).join('')}</div>`}
function isoRequirementSummaryHtml(req,refs=[]){if(!req||!Object.keys(req).length)return '<div class="note">Chưa có diễn giải riêng cho điều khoản này.</div>';const steps=(req.implementation||[]).map((x,i)=>`<li><span>${i+1}</span><div>${esc(x)}</div></li>`).join('');const evidence=(req.expected_evidence||[]).map(x=>`<li>${esc(x)}</li>`).join('');const notes=uniqueTextItems([...(req.practical_notes||[]),...(req.cautions||[])]).map(x=>`<li>${esc(x)}</li>`).join('');const sourceRows=(refs&&refs.length)?refs:(req.source_links||[]);const sourceBlock=sourceReferenceCardsHtml(sourceRows);return `<article class="iso-detail-stack"><section class="iso-requirement-panel iso-summary-hero"><div class="iso-source-kicker">HIỂU VÀ ÁP DỤNG YÊU CẦU · ${esc(req.clause||'')}</div><div class="iso-subhead">Yêu cầu cần đáp ứng</div><p class="iso-requirement-summary">${esc(req.requirement_summary||req.list_summary||'')}</p>${req.plain_language?`<div class="iso-summary-inline"><h4>Hiểu đơn giản</h4><div class="plain-language-box"><p>${esc(req.plain_language)}</p></div></div>`:''}${req.why_it_matters?`<div class="iso-summary-inline"><h4>Vì sao nội dung này quan trọng?</h4><p class="iso-purpose">${esc(req.why_it_matters)}</p></div>`:''}</section>${steps?`<section class="iso-section-card iso-section-card-steps"><div class="iso-card-head"><h4>Cách thực hiện trong thực tế</h4><span>Triển khai từng bước, rõ người làm và đầu ra cần có</span></div><ol class="iso-action-list">${steps}</ol></section>`:''}${req.example?`<section class="iso-section-card"><div class="iso-card-head"><h4>Ví dụ minh họa</h4><span>Tình huống gần với thực hành của khoa</span></div><div class="iso-practical-example">${esc(req.example)}</div></section>`:''}${evidence?`<section class="iso-section-card"><div class="iso-card-head"><h4>Hồ sơ và ghi nhận nên có</h4><span>Gợi ý bằng chứng để chứng minh mức đáp ứng</span></div><ul class="iso-evidence-list">${evidence}</ul></section>`:''}${notes?`<section class="iso-section-card iso-section-card-caution"><div class="iso-card-head"><h4>${semanticSvg('warning')}<span>Lưu ý và Thận trọng</span></h4><span>Những điểm dễ bỏ sót hoặc dễ hiểu chưa đúng</span></div><ul class="iso-practical-notes">${notes}</ul></section>`:''}${sourceBlock?`<section class="iso-section-card iso-section-card-sources"><div class="iso-card-head"><h4>Nguồn hướng dẫn và tham khảo</h4><span>Tài liệu dùng để đối chiếu yêu cầu và hỗ trợ triển khai thực hành</span></div>${sourceBlock}</section>`:''}<div class="iso-standard-note">${esc(req.normative_note||req.source_basis||'Diễn giải phục vụ triển khai; khi kết luận mức đáp ứng phải đối chiếu bản tiêu chuẩn được kiểm soát.')}</div></article>`}
function isoRequirementInfoHtml(r){const d=r.data||{};const req={clause:d.clause||isoClause(r),requirement_summary:d.requirement_summary||r.description||'',list_summary:r.description||'',purpose:d.purpose||'',why_it_matters:d.why_it_matters||d.purpose||'',implementation:d.implementation||[],example:d.example||'',practical_notes:d.practical_notes||[],expected_evidence:d.expected_evidence||[],source_links:d.source_links||[],source_basis:d.source_basis||''};const edit=`<section class="iso-section-card iso-section-card-manage"><form id="recordForm" class="iso-operational-form"><div class="iso-card-head"><h4>Quản lý triển khai</h4><span>Cập nhật trạng thái, đầu mối, thời hạn và ghi chú thực hiện tại NAH</span></div><div class="form-grid"><div class="field"><label>Trạng thái</label><select name="status">${statusOptions(r.status||'active','iso')}</select></div><div class="field"><label>Đầu mối phụ trách</label><select name="owner_ref">${ownerOptions(r.owner_ref||'')}</select></div><div class="field"><label>Mức ưu tiên</label><select name="priority">${priorityOptions(r.priority||'normal')}</select></div><div class="field"><label>Hạn hoàn thành</label><input type="date" name="due_date" value="${esc(r.due_date||'')}"></div><div class="field"><label>Tiến độ (%)</label><input type="number" min="0" max="100" name="progress" value="${esc(r.progress??0)}"></div><div class="field full"><label>Ghi chú triển khai tại NAH</label><textarea data-extra="deployment_note" placeholder="Ghi tình trạng thực hiện, điểm còn thiếu hoặc quyết định triển khai; không chép lại nội dung tiêu chuẩn.">${esc(d.deployment_note||'')}</textarea></div></div><div class="form-actions"><button type="button" class="btn" data-close>Đóng</button><button class="btn primary" type="submit">Lưu triển khai</button></div></form></section>`;return edit+isoRequirementSummaryHtml(req)}
function isoHandbookHtml(ctx){const req=isoRequirementSummaryHtml(ctx.requirement||{},ctx.references||[]);const rows=(ctx.handbook||[]).map(ch=>`<article class="context-card"><div class="clause-row">${(ch.clauses||[]).map(c=>`<span class="clause-chip">${esc(c)}</span>`).join('')}</div><h4>${esc(ch.title)}</h4><p>${esc(ch.summary||'')}</p><div class="context-columns"><div><strong>Ý chính cần nhớ</strong><ul>${(ch.principles||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div><strong>Gợi ý áp dụng tại đơn vị</strong><ul>${(ch.checklist||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></div></article>`).join('')||'<div class="note">Chưa có bài Sổ tay ánh xạ riêng cho điều khoản này.</div>';return `${req}<div class="section-title">Học cách thực hiện yêu cầu này</div>${rows}`}
function isoGuidanceHtml(ctx){const req=isoRequirementSummaryHtml(ctx.requirement||{},ctx.references||[]);const procs=(ctx.procedures||[]).map(x=>`<div class="mapping-row"><span class="code">${esc(x.code||'—')}</span><div><strong>${esc(x.title||'')}</strong><small>ISO: ${esc(x.iso||'—')} · QĐ 2429: ${esc(x.qd2429||'—')}</small></div></div>`).join('')||'<div class="note">Chưa có quy trình được ánh xạ cho điều khoản này. Có thể dùng phần hướng dẫn phía trên để xác định tài liệu cần xây dựng hoặc cập nhật.</div>';return `${req}<div class="section-title">Quy trình / hướng dẫn liên quan</div><div class="mapping-list">${procs}</div><div class="note iso-fast-note">Liên kết hồ sơ sống được quản lý ở Tài liệu/Bằng chứng; nội dung hướng dẫn và nguồn tham khảo của điều khoản được đóng gói trong ứng dụng để mở nhanh và ổn định.</div>`}
function clientClauseMatches(needle,candidate){needle=String(needle||'').trim();candidate=String(candidate||'').trim();if(!needle||!candidate)return false;if(candidate==='4-8')return /^[4-8](?:\.|$)/.test(needle);if(needle===candidate)return true;if(needle.startsWith(candidate+'.')||candidate.startsWith(needle+'.'))return true;return false}
function isoFormTemplateClauses(t){return t._iso_clauses||t.clauses||[]}
function isoFormFields(t){if((t.fields||[]).length)return t.fields;const src=(t.columns||[]).length?t.columns:(t.sections||[]);return src.map((label,i)=>({name:`field_${i+1}`,label:String(label||`Nội dung ${i+1}`),type:/ghi chú|nội dung|mô tả|kết quả|hành động|bằng chứng/i.test(String(label))?'textarea':'text',required:i===0}))}
function isoFormRecordMatchesClause(r,clause){return (r.data?.clauses||[]).some(c=>clientClauseMatches(clause,c))||clientClauseMatches(clause,r.data?.clause||'')}
function isoFormRecordEditorHtml(t,r={},sourceKind='iso',clause=''){const vals=r.data?.form_fields||{};const fields=isoFormFields(t).map(f=>`<div class="field ${f.type==='textarea'?'full':''}"><label>${esc(f.label||f.name)}${f.required?' *':''}</label>${qd2429FieldControl(f,vals[f.name])}</div>`).join('');const refs=isoFormTemplateClauses(t);return `<form id="isoFormRecord"><div class="qd2429-template-context iso-form-context"><span class="badge active">${esc(t.id||'')}</span><strong>${esc(t.title||'')}</strong><small>ISO ${esc(refs.join(', ')||clause||'—')}${sourceKind==='qd2429'?' · Biểu mẫu dùng chung với QĐ 2429':''}</small><p>${esc(t.purpose||'')}</p></div><div class="form-grid"><div class="field"><label>Trạng thái</label><select name="status">${statusOptions(r.status||'in_progress','isoforms')}</select></div><div class="field"><label>Đầu mối phụ trách</label><select name="owner_ref">${ownerOptions(r.owner_ref||'')}</select></div><div class="field"><label>Mức ưu tiên</label><select name="priority">${priorityOptions(r.priority||'normal')}</select></div><div class="field"><label>Hạn hoàn thành</label><input type="date" name="due_date" value="${esc(r.due_date||'')}"></div>${fields}<div class="field full"><label>Ghi chú nghiệp vụ</label><textarea name="description">${esc(r.description||'')}</textarea></div></div><div class="form-actions"><button type="button" class="btn" data-close>Đóng</button>${r.id?'<button type="button" class="btn" id="isoPrintRecord">In A4</button><button type="button" class="btn" id="isoPdfRecord">PDF A4</button><button type="button" class="btn" id="isoDocxRecord">DOCX A4</button>':''}<button class="btn primary" type="submit">${r.id?'Lưu thay đổi':'Tạo bản ghi'}</button></div></form>${r.id?`<section class="qd2429-record-evidence"><div class="section-title">Minh chứng đính kèm</div>${evidenceHtml(r)}</section>`:''}`}
function qualityRecordA4Html(t,r={},framework='iso',clause=''){
 const vals=r.data?.form_fields||{},fields=(t.fields||[]).length?t.fields:isoFormFields(t);
 const s=(value)=>esc(String(value??'').replace(/\r\n?/g,'\n'));
 const rows=fields.map(f=>`<tr><th scope="row">${esc(f.label||f.name)}</th><td class="iso-record-value">${s(vals[f.name]??'')}</td></tr>`).join('');
 const isoRef=(t._iso_clauses||t.clauses||[]).join(', ')||clause;
 const reference=framework==='qd2429'?`QĐ 2429/QĐ-BYT · ${esc((t.criteria_refs||[]).join(', '))}`:`TCVN ISO 15189:2025 · ${esc(isoRef)}`;
 return `<article class="iso-form-a4 iso-form-print-v2 iso-record-a4"><header class="iso-form-header"><div class="iso-form-org"><strong>BỆNH VIỆN HỮU NGHỊ ĐA KHOA NGHỆ AN – GIAI ĐOẠN 2</strong><span>KHOA XÉT NGHIỆM</span></div><div class="iso-form-control"><b>${esc(t.id||'')}</b><span>Mã bản ghi: ${esc(r.code||'—')}</span></div></header><h1>${esc(t.title||'Biểu mẫu chất lượng xét nghiệm')}</h1><div class="iso-form-source-line">${reference}</div><section class="iso-form-fields"><h3>Thông tin hồ sơ</h3><table class="data-table iso-form-print-table iso-form-field-table"><tbody><tr><th scope="row">Trạng thái hồ sơ</th><td>${esc(statusLabels[r.status]||r.status||'Chưa cập nhật')}</td></tr><tr><th scope="row">Người phụ trách</th><td>${esc(r.owner_name||r.owner_ref||'—')}</td></tr><tr><th scope="row">Thời hạn</th><td>${r.due_date?fmtDate(r.due_date):'—'}</td></tr>${rows}${r.description?`<tr><th scope="row">Ghi chú nghiệp vụ</th><td class="iso-record-value">${s(r.description)}</td></tr>`:''}</tbody></table></section><section class="form-signatures iso-form-signatures"><div>Người thực hiện<br><small>(Ký, ghi rõ họ tên)</small></div><div>Người kiểm tra<br><small>(Ký, ghi rõ họ tên)</small></div><div>Người phê duyệt<br><small>(Ký, ghi rõ họ tên)</small></div></section><footer class="iso-form-footer"><span>${esc(t.id||'')} · Khoa Xét nghiệm</span></footer></article>`;
}
function isoFormRecordA4(t,r={},clause=''){return qualityRecordA4Html(t,r,'iso',clause)}
function isoFormsHubHtml(ctx,r,records=[]){const hub=ctx.formHub||{},isoTemplates=hub.iso_templates||[],qdTemplates=hub.reused_qd2429_templates||[],clause=ctx.clause||isoClause(r);const relatedRecords=records.filter(x=>isoFormRecordMatchesClause(x,clause));const templateCards=[...isoTemplates.map(t=>({...t,_sourceKind:'iso'})),...qdTemplates.map(t=>({...t,_sourceKind:'qd2429'}))].map(t=>`<article class="iso-hub-template-card"><div><span class="code">${esc(t.id)}</span>${t._sourceKind==='qd2429'?'<span class="badge">Dùng chung 2429</span>':'<span class="badge active">ISO</span>'}</div><h4>${esc(t.title||'')}</h4><p>${esc(t.purpose||'')}</p><small>Liên quan: ${esc(isoFormTemplateClauses(t).join(', ')||clause)}</small><div class="iso-hub-card-actions"><button class="btn small" data-isoform-template="${esc(t.id)}">Xem mẫu A4</button><button class="btn primary small" data-isoform-new="${esc(t.id)}" data-source-kind="${esc(t._sourceKind)}">Tạo bản ghi</button></div></article>`).join('');const rows=relatedRecords.map(x=>`<tr data-isoform-record="${x.id}"><td><span class="code">${esc(x.code||'#'+x.id)}</span></td><td><strong>${esc(x.title)}</strong><small>${esc(x.data?.template_id||'')} · ISO ${esc((x.data?.clauses||[]).join(', '))}</small></td><td>${esc(x.owner_name||x.owner_ref||'—')}</td><td>${fmtDate(x.due_date)}</td><td><span class="badge ${esc(x.status)}">${esc(statusLabels[x.status]||x.status)}</span></td><td>${(x.evidence||[]).length}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Chưa có bản ghi biểu mẫu cho điều khoản này.</td></tr>';const reports=(hub.reports||[]).map(x=>`<button class="report-period-card" data-isoforms-report="${esc(x.id)}"><strong>${esc(x.title)}</strong><p>${esc(x.description||'')}</p><span>Tạo báo cáo A4 ›</span></button>`).join('');return `<section class="iso-hub-section"><div class="section-title">Biểu mẫu liên quan</div><div class="iso-hub-template-grid">${templateCards||'<div class="note">Chưa có biểu mẫu được ánh xạ riêng cho điều khoản này.</div>'}</div></section><section class="iso-hub-section"><div class="section-title">Bản ghi đã có</div><div class="table-card"><table class="data-table"><thead><tr><th>MÃ</th><th>BẢN GHI</th><th>PHỤ TRÁCH</th><th>HẠN</th><th>TRẠNG THÁI</th><th>MINH CHỨNG</th></tr></thead><tbody>${rows}</tbody></table></div></section><section class="iso-hub-workflow"><div><strong>1. Tạo bản ghi mới</strong><span>Chọn biểu mẫu phù hợp ở trên.</span></div><div><strong>2. Minh chứng</strong><span>Mở bản ghi để tải tệp minh chứng lên Google Drive.</span></div><div><strong>3. Báo cáo</strong><span>Tổng hợp theo điều khoản, trạng thái và hồ sơ quá hạn.</span></div></section>${reports?`<section class="iso-hub-section"><div class="section-title">Báo cáo</div><div class="report-period-grid">${reports}</div></section>`:''}`}
function isoClauseFormsReportA4(clause,ctx,records,title='Báo cáo hồ sơ và biểu mẫu ISO'){const related=records.filter(x=>isoFormRecordMatchesClause(x,clause));const overdue=related.filter(x=>x.due_date&&x.due_date<new Date().toISOString().slice(0,10)&&!['done','closed','approved'].includes(x.status));const rows=related.map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.code||'#'+x.id)}</td><td>${esc(x.title)}</td><td>${esc(x.owner_name||x.owner_ref||'—')}</td><td>${fmtDate(x.due_date)}</td><td>${esc(statusLabels[x.status]||x.status)}</td><td>${(x.evidence||[]).length}</td></tr>`).join('')||'<tr><td colspan="7">Chưa có bản ghi.</td></tr>';return `<article class="iso-form-a4 print-report"><header class="iso-form-header"><div><strong>BỆNH VIỆN HỮU NGHỊ ĐA KHOA NGHỆ AN - GIAI ĐOẠN 2</strong><span>KHOA XÉT NGHIỆM</span></div><div class="iso-form-control"><b>ISO ${esc(clause)}</b><span>Ngày lập: ${fmtDate(new Date().toISOString().slice(0,10))}</span></div></header><h1>${esc(title)}</h1><p><b>Điều khoản:</b> ISO ${esc(clause)} · <b>Tổng bản ghi:</b> ${related.length} · <b>Quá hạn:</b> ${overdue.length}</p><table class="data-table"><thead><tr><th>STT</th><th>MÃ</th><th>NỘI DUNG</th><th>PHỤ TRÁCH</th><th>HẠN</th><th>TRẠNG THÁI</th><th>MINH CHỨNG</th></tr></thead><tbody>${rows}</tbody></table><div class="form-signatures"><div>Người lập<br><small>(Ký, ghi rõ họ tên)</small></div><div>Trưởng khoa Xét nghiệm<br><small>(Ký, ghi rõ họ tên)</small></div><div>Người phê duyệt<br><small>(Ký, ghi rõ họ tên)</small></div></div></article>`}

function qualityLinksHtml(r,links){
 const rows=(links||[]).map(x=>{const mine=x.source_record_id===r.id;const id=mine?x.target_record_id:x.source_record_id;const code=mine?x.target_code:x.source_code;const title=mine?x.target_title:x.source_title;const mod=mine?x.target_module:x.source_module;return `<div class="qms-link-row"><div><span class="code">${esc(code||'#'+id)}</span><strong>${esc(title||'')}</strong><small>${esc(moduleMeta[mod]?.label||mod)} · ${esc(x.relation_label||x.relation_type)}</small></div>${canManage(r.module)?`<button class="btn small danger" data-qms-unlink="${x.id}">Xóa</button>`:''}</div>`}).join('')||'<div class="note">Chưa có liên kết QMS với bản ghi khác.</div>';
 const rel=`<form id="qmsLinkForm" class="qms-inline-form"><div class="field"><label>ID bản ghi liên quan</label><input type="number" min="1" name="target_record_id" required></div><div class="field"><label>Loại liên kết</label><select name="relation_type"><option value="related">Liên quan</option><option value="risk_from">Rủi ro liên quan</option><option value="management_review_input">Đầu vào xem xét lãnh đạo</option><option value="management_review_action">Hành động sau xem xét</option></select></div><div class="form-actions"><button class="btn">Thêm liên kết</button></div></form>`;
 return `<div class="section-title">Liên kết hồ sơ</div><div class="qms-link-list">${rows}</div>${canManage(r.module)?rel:''}`;
}
function qmsActionHtml(r){const d=r.data||{};
 if(r.module==='audits'){if(!canManage('audits'))return '';return `<div class="section-title">Ghi nhận phát hiện từ cuộc đánh giá</div><form id="auditFindingForm"><div class="form-grid"><div class="field full"><label>Phát hiện *</label><input name="title" required></div><div class="field"><label>Điều khoản ISO</label><input name="clause" value="${esc(d.clauses||'')}"></div><div class="field"><label>Phân loại</label><select name="finding_type"><option value="nonconformity">Sự không phù hợp</option><option value="major">Không phù hợp lớn</option><option value="minor">Không phù hợp nhỏ</option><option value="observation">Quan sát / cơ hội cải tiến</option></select></div><div class="field full"><label>Bằng chứng đánh giá</label><textarea name="evidence"></textarea></div><div class="field"><label>Hạn xử lý</label><input type="date" name="due_date"></div></div><div class="form-actions"><button class="btn primary">Tạo phát hiện / NC</button></div></form>`;}
 if(r.module==='nc'){if(!canManage('capa'))return '';return `<div class="section-title">Tạo hành động khắc phục</div><form id="ncCapaForm"><div class="form-grid"><div class="field"><label>Phương pháp phân tích nguyên nhân</label><select name="root_cause_method"><option value="5why">5 lần Tại sao (5 Whys)</option><option value="fishbone">Sơ đồ xương cá (Ishikawa)</option><option value="fault_tree">Cây lỗi (Fault Tree)</option><option value="other">Khác</option></select></div><div class="field"><label>Hạn hoàn thành</label><input type="date" name="due_date"></div><div class="field full"><label>Nguyên nhân gốc</label><textarea name="root_cause">${esc(d.root_cause||'')}</textarea></div><div class="field full"><label>Hành động khắc phục *</label><textarea name="corrective_action" required></textarea></div><div class="field full"><label>Tiêu chí đánh giá hiệu lực</label><textarea name="success_criteria"></textarea></div><div class="field"><label>Hạn đánh giá hiệu lực</label><input type="date" name="effectiveness_due"></div></div><div class="form-actions"><button class="btn primary">Tạo hành động khắc phục</button></div></form>`;}
 if(r.module==='capa'){const reviews=(d.effectiveness_reviews||[]).map(x=>`<div class="qms-review"><strong>${x.result==='effective'?'Đạt hiệu lực':x.result==='partial'?'Hiệu lực một phần':'Chưa hiệu lực'}</strong><span>${esc(x.date||'')} · ${esc(x.reviewer_name||x.reviewer_ref||'')}</span><p>${esc(x.criteria||'')}</p>${x.evidence_note?`<small>${esc(x.evidence_note)}</small>`:''}</div>`).join('')||'<div class="note">Chưa có lần đánh giá hiệu lực.</div>';return `<div class="section-title">Đánh giá hiệu lực hành động khắc phục</div><div class="qms-review-list">${reviews}</div><form id="capaEffectivenessForm"><div class="form-grid"><div class="field"><label>Kết luận</label><select name="result"><option value="effective">Đạt hiệu lực</option><option value="partial">Hiệu lực một phần</option><option value="not_effective">Chưa hiệu lực</option></select></div><div class="field full"><label>Tiêu chí / cách đánh giá *</label><textarea name="criteria" required>${esc(d.success_criteria||'')}</textarea></div><div class="field full"><label>Bằng chứng sau can thiệp</label><textarea name="evidence_note"></textarea></div><div class="field full"><label>Ghi chú</label><textarea name="note"></textarea></div></div><div class="form-actions"><button class="btn primary">Lưu đánh giá hiệu lực</button></div></form><div class="note qms-gate-note">Chỉ đóng hành động khắc phục khi có ít nhất một đánh giá kết luận <b>Đạt hiệu lực</b>.</div>`;}
 if(r.module==='meetings'){if(!(hasCap('approve')||canManage('iso')))return '';const pct=d.input_readiness_pct??'—';return `<div class="section-title">Chuẩn bị đầu vào xem xét của lãnh đạo</div><div class="qms-mr-readiness"><strong>${esc(pct)}${pct==='—'?'':'%'}</strong><span>Mức sẵn sàng của bản tổng hợp gần nhất</span></div><form id="mrSnapshotForm"><div class="form-grid"><div class="field"><label>Từ ngày</label><input type="date" name="from" value="${esc(d.review_period_from||'')}"></div><div class="field"><label>Đến ngày</label><input type="date" name="to" value="${esc(d.review_period_to||'')}"></div></div><div class="form-actions"><button class="btn primary">Tạo / cập nhật bản tổng hợp</button></div></form>${d.snapshot_at?`<div class="meta">Cập nhật gần nhất: ${esc(d.snapshot_at)} · ${esc(d.snapshot_by_ref||'')}</div>`:''}`}
 return '';
}
async function renderQmsTab(r){const box=$('#drawerTabBody');box.innerHTML='<div class="loading">Đang tải liên kết hồ sơ…</div>';try{const data=await api(`quality-core/record/${r.id}/links`);box.innerHTML=`${qmsActionHtml(r)}${qualityLinksHtml(r,data.links||[])}`;wireQmsTab(r)}catch(e){box.innerHTML=`<div class="note">${esc(e.message)}</div>`}}
function wireQmsTab(r){
 $('#qmsLinkForm')?.addEventListener('submit',async e=>{e.preventDefault();const j=Object.fromEntries(new FormData(e.currentTarget).entries());try{await api(`quality-core/record/${r.id}/links`,{method:'POST',json:j});toast('Đã thêm liên kết QMS');await renderQmsTab(r)}catch(err){toast(err.message,'err')}});
 $$('[data-qms-unlink]').forEach(b=>b.onclick=async()=>{if(!confirm('Xóa liên kết QMS này?'))return;try{await api(`quality-core/links/${b.dataset.qmsUnlink}`,{method:'DELETE'});toast('Đã xóa liên kết');await renderQmsTab(r)}catch(err){toast(err.message,'err')}});
 $('#auditFindingForm')?.addEventListener('submit',async e=>{e.preventDefault();const j=Object.fromEntries(new FormData(e.currentTarget).entries());try{const out=await api(`quality-core/audits/${r.id}/finding`,{method:'POST',json:j});toast(`Đã tạo ${out.code||'phát hiện'}`);await refreshDrawer(r.id)}catch(err){toast(err.message,'err')}});
 $('#ncCapaForm')?.addEventListener('submit',async e=>{e.preventDefault();const j=Object.fromEntries(new FormData(e.currentTarget).entries());try{const out=await api(`quality-core/nc/${r.id}/capa`,{method:'POST',json:j});toast(`Đã tạo ${out.code||'hành động khắc phục'}`);await refreshDrawer(r.id)}catch(err){toast(err.message,'err')}});
 $('#capaEffectivenessForm')?.addEventListener('submit',async e=>{e.preventDefault();const j=Object.fromEntries(new FormData(e.currentTarget).entries());try{await api(`quality-core/capa/${r.id}/effectiveness`,{method:'POST',json:j});toast('Đã lưu đánh giá hiệu lực');await refreshDrawer(r.id)}catch(err){toast(err.message,'err')}});
 $('#mrSnapshotForm')?.addEventListener('submit',async e=>{e.preventDefault();const j=Object.fromEntries(new FormData(e.currentTarget).entries());try{const out=await api(`quality-core/management-review/${r.id}/snapshot`,{method:'POST',json:j});toast(`Đã tổng hợp đầu vào · ${out.snapshot?.readiness_pct||0}% sẵn sàng`);await refreshDrawer(r.id)}catch(err){toast(err.message,'err')}});
}
async function renderDrawerTab(r){const box=$('#drawerTabBody');$$('[data-dtab]').forEach(b=>b.classList.toggle('active',b.dataset.dtab===state.drawerTab));if(r.module==='certprogress'&&state.drawerTab==='info'){box.innerHTML=certProgressInfoHtml(r);wireCertProgressInfo(r);return}if(r.module==='certprogress'&&state.drawerTab==='checklist'){box.innerHTML='<div class="loading">Đang tải danh mục…</div>';try{box.innerHTML=await certProgressChecklistHtml(r);wireCertProgressChecklist(r)}catch(e){box.innerHTML=`<div class="note">${esc(e.message)}</div>`}return}if((r.module==='documents'||r.module==='forms')&&['versions','workflow','distribution','reading','history'].includes(state.drawerTab)){await renderDocumentTab(r);return}if(state.drawerTab==='qms'){await renderQmsTab(r);return}if(state.drawerTab==='info'){box.innerHTML=r.module==='iso'?isoRequirementInfoHtml(r):recordInfoHtml(r.module,r);wireRecordForm(r.module,r);return}if(state.drawerTab==='assign'){box.innerHTML=assignmentHtml(r);wireAssignment(r);return}if(state.drawerTab==='progress'){box.innerHTML='<div class="loading">Đang tải tiến độ…</div>';try{box.innerHTML=await progressReportHtml(r);wireProgressReport(r)}catch(e){box.innerHTML=`<div class="note">${esc(e.message)}</div>`}return}if(state.drawerTab==='chat'){box.innerHTML=commentsHtml(r);wireComments(r);return}if(state.drawerTab==='evidence'){box.innerHTML=evidenceHtml(r);wireEvidence(r);return}if(state.drawerTab==='history'){box.innerHTML=activityHtml(r);return}if(r.module==='iso'&&['guidance','handbook','forms'].includes(state.drawerTab)){box.innerHTML='<div class="loading">Đang tải hướng dẫn…</div>';try{const ctx=await loadIsoContext(r);if(state.drawerTab==='forms'){await renderIsoFormsTab(r,ctx);return}box.innerHTML=state.drawerTab==='guidance'?isoGuidanceHtml(ctx):isoHandbookHtml(ctx)}catch(e){box.innerHTML=`<div class="note">${esc(e.message)}</div>`};return}box.innerHTML=evidenceHtml(r);wireEvidence(r)}
