function printElementA4(el){
 if(!el)return;
 const frame=document.createElement('iframe');frame.setAttribute('aria-hidden','true');frame.style.cssText='position:fixed;width:1px;height:1px;right:0;bottom:0;border:0;opacity:0;pointer-events:none';document.body.appendChild(frame);
 const doc=frame.contentDocument||frame.contentWindow.document;
 doc.open();doc.write(`<!doctype html><html lang="vi"><head><meta charset="utf-8"><title>Biểu mẫu Khoa Xét nghiệm</title><style>@page{size:A4 portrait;margin:12mm}html,body{margin:0;padding:0;color:#111;background:#fff}body{font-family:Arial,"Noto Sans",sans-serif;font-size:11pt;line-height:1.35}*{box-sizing:border-box}article{width:100%;max-width:186mm;margin:0 auto}h1{font-size:14pt;line-height:1.3;text-align:center;margin:7mm 0 3mm}h2{font-size:13pt}h3{font-size:11pt;margin:5mm 0 2mm}p,li,th,td{font-size:10pt;line-height:1.35}.iso-form-header{display:grid;grid-template-columns:minmax(0,1fr) 57mm;gap:5mm;border-bottom:1.3px solid #222;padding-bottom:3mm}.iso-form-header strong,.iso-form-header span,.iso-form-control span{display:block}.iso-form-org{font-size:9.5pt}.iso-form-org strong{font-size:10pt}.iso-form-control{text-align:right;font-size:9pt;line-height:1.5}.iso-form-source-line{text-align:center;font-size:9pt;color:#333;margin-bottom:6mm}.iso-form-print-table{width:100%;border-collapse:collapse;table-layout:fixed}.iso-form-print-table th,.iso-form-print-table td{padding:2.3mm;border:0.6px solid #666;vertical-align:top;overflow-wrap:break-word;word-break:normal;white-space:pre-wrap}.iso-form-print-table th{font-weight:700;background:#f6f6f6}.iso-form-field-table th{width:36%;text-align:left}.iso-form-field-table td{width:64%}.iso-form-field-table tr{min-height:13mm}.iso-form-empty{height:12mm}.iso-form-register-table th{font-size:9pt;word-break:normal;hyphens:auto}.iso-form-register-table td{height:11mm}.iso-form-ordinal{text-align:center}.iso-form-register-part{break-inside:avoid;page-break-inside:avoid;margin-top:3mm}.iso-form-fields table{margin-top:2mm}.iso-record-value{white-space:pre-wrap}.form-signatures{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:3mm;text-align:center;min-height:27mm;padding-top:6mm;margin-top:7mm;font-weight:700;font-size:10pt;break-inside:avoid}.form-signatures small{font-weight:400;font-size:9pt}.iso-form-footer{font-size:8.5pt;border-top:0.6px solid #999;margin-top:5mm;padding-top:2mm;text-align:right}thead{display:table-header-group}tr{break-inside:avoid;page-break-inside:avoid}button,.btn,.export-toolbar,.internal-note,.governance-note,[data-internal-audit]{display:none!important}</style></head><body>${el.outerHTML}</body></html>`);doc.close();
 const cleanup=()=>setTimeout(()=>frame.remove(),500);
 setTimeout(()=>{try{frame.contentWindow.focus();frame.contentWindow.print();frame.contentWindow.onafterprint=cleanup;setTimeout(cleanup,5000)}catch(e){frame.remove();toast('Không thể mở hộp thoại in A4.','err')}},300);
}
function wireRecordForm(module,r={}){const f=$('#recordForm');$$('[data-close]',f).forEach(b=>b.onclick=closeDrawer);f.onsubmit=async e=>{e.preventDefault();try{const data=collectForm(module,f);const saved=r.id?await api(`records/${r.id}`,{method:'PATCH',json:data}):await api('records',{method:'POST',json:data});if(saved?.status!==data.status||Number(saved?.progress)!==data.progress)throw new Error('Máy chủ chưa xác nhận trạng thái hoặc tiến độ vừa lưu.');const confirmed=await api(`records/${saved.id}?_ts=${Date.now()}`,{cache:'no-store',noDedupe:true});if(confirmed?.status!==data.status||Number(confirmed?.progress)!==data.progress)throw new Error('Trạng thái vừa lưu không còn khớp dữ liệu trên máy chủ. Vui lòng kiểm tra lại.');if(module==='docplan'){state.docplanCache=null;void renderDocumentPlan().catch(err=>toast('Không tải lại được danh sách tài liệu: '+err.message,'err'))}if(r.id){state.current=confirmed;await refreshDrawer(saved.id)}else{closeDrawer();await render()}toast(r.id?'Đã lưu và xác nhận trạng thái':'Đã tạo bản ghi');}catch(err){toast(err.message,'err')}};$('#printRecord')?.addEventListener('click',()=>printRecord(r));$('#pdfRecord')?.addEventListener('click',()=>withExportHtml(recordA4Html(r),el=>exportElementPdf(el,`${safeFileName(r.code||r.title)}.pdf`,{action:'record_export',module:r.module,record_id:r.id,title:r.title})));$('#docxRecord')?.addEventListener('click',()=>withExportHtml(recordA4Html(r),el=>exportElementDocx(el,`${safeFileName(r.code||r.title)}.docx`,r.title,{action:'record_export',module:r.module,record_id:r.id,title:r.title})))}
function assignmentHtml(r){const list=(r.assignments||[]).map(a=>`<div class="assignment"><div><strong>${esc(a.assignee_name)}</strong><div class="meta">${esc(a.assignee_role)} · ${a.assignment_role==='lead'?'Đầu mối':'Thành viên'}${a.due_date?' · Hạn '+fmtDate(a.due_date):''}</div></div>${hasCap('assign_tasks')?`<button class="btn small danger" data-unassign="${a.id}">Xóa</button>`:''}</div>`).join('')||'<div class="note">Chưa phân công thành viên. Có thể chỉ định một người làm đầu mối và thêm các thành viên phối hợp.</div>';let form='';if(hasCap('assign_tasks')&&(state.boot.assignableUsers||[]).length){form=`<div class="section-title">Thêm phân công</div><form id="assignmentForm"><div class="form-grid"><div class="field"><label>Người nhận</label><select name="assignee_ref" required><option value="">Chọn tài khoản</option>${state.boot.assignableUsers.map(u=>`<option value="${esc(u.ref)}">${esc(u.name)} — ${esc(u.roleLabel)}</option>`).join('')}</select></div><div class="field"><label>Vai trò</label><select name="assignment_role"><option value="lead">Đầu mối phụ trách</option><option value="member">Thành viên phối hợp</option></select></div><div class="field"><label>Thời hạn</label><input type="date" name="due_date" value="${esc(r.due_date||'')}"></div></div><div class="form-actions"><button class="btn primary" type="submit">Giao nhiệm vụ</button></div></form>`}return `<div class="section-title">Danh sách phân công</div><div class="assignment-list">${list}</div>${form}`}
