async function progressReportHtml(r){const rows=await api(`records/${r.id}/progress-reports`);const history=(rows||[]).map(x=>`<article class="progress-update-card"><div class="progress-update-head"><div><strong>${esc(x.user_name||'Người dùng')}</strong><span>${esc(x.created_at||'')}</span></div><div><b>${x.progress}%</b><span class="badge ${esc(x.status||'in_progress')}">${esc(statusLabels[x.status]||x.status||'Đang thực hiện')}</span></div></div>${x.work_done?`<div><small>Đã thực hiện</small><p>${esc(x.work_done)}</p></div>`:''}${x.blocker?`<div class="progress-warning"><small>Khó khăn / vướng mắc</small><p>${esc(x.blocker)}</p></div>`:''}${x.support_request?`<div class="progress-support"><small>Đề nghị hỗ trợ</small><p>${esc(x.support_request)}</p></div>`:''}${x.next_action?`<div><small>Bước tiếp theo</small><p>${esc(x.next_action)}</p></div>`:''}</article>`).join('')||'<div class="note">Chưa có cập nhật tiến độ.</div>';return `<div class="progress-report-layout"><section><div class="section-title">Cập nhật mới</div><form id="progressReportForm"><div class="form-grid"><div class="field"><label>Tiến độ hiện tại (%)</label><input type="number" min="0" max="100" name="progress" value="${esc(r.progress??0)}"></div><div class="field"><label>Trạng thái</label><select name="status"><option value="in_progress" ${r.status==='in_progress'?'selected':''}>Đang thực hiện</option><option value="review" ${r.status==='review'?'selected':''}>Chờ rà soát</option><option value="done" ${['done','closed','approved'].includes(r.status)?'selected':''}>Hoàn thành</option></select></div><div class="field full"><label>Đã thực hiện</label><textarea name="work_done" placeholder="Nội dung đã hoàn thành hoặc đã cập nhật…"></textarea></div><div class="field full"><label>Khó khăn / vướng mắc</label><textarea name="blocker" placeholder="Nêu rõ điểm đang vướng nếu có…"></textarea></div><div class="field full"><label>Đề nghị hỗ trợ</label><textarea name="support_request" placeholder="Nội dung cần Trưởng khoa hoặc đơn vị liên quan hỗ trợ…"></textarea></div><div class="field full"><label>Bước tiếp theo</label><textarea name="next_action" placeholder="Việc dự kiến thực hiện tiếp theo…"></textarea></div></div><div class="form-actions"><button class="btn primary">Lưu cập nhật</button></div></form></section><section><div class="section-title">Lịch sử cập nhật</div><div class="progress-update-list">${history}</div></section></div>`}
