function recordA4Html(r){return `<article class="card panel print-report iso-form-a4"><div class="report-head"><div class="report-brand"><img src="${esc(cfg.logoUrl||'')}" alt="Tên bệnh viện"><div><h2>${esc(moduleMeta[r.module]?.label||r.module)}</h2><div class="report-meta">Bệnh viện Hữu nghị Đa khoa Nghệ An - Giai đoạn 2 · Khoa Xét nghiệm</div></div></div><div class="report-meta">TCVN ISO 15189:2025 (ISO 15189:2022)</div></div><table class="data-table"><tbody><tr><th>Mã</th><td>${esc(r.code||'#'+r.id)}</td></tr><tr><th>Tiêu đề</th><td>${esc(r.title)}</td></tr><tr><th>Trạng thái</th><td>${esc(statusLabels[r.status]||r.status)}</td></tr><tr><th>Phụ trách</th><td>${esc(r.owner_name||'—')}</td></tr><tr><th>Mức ưu tiên</th><td>${esc(priorityLabels[r.priority]||r.priority||'—')}</td></tr><tr><th>Hạn</th><td>${fmtDate(r.due_date)}</td></tr><tr><th>Tiến độ</th><td>${esc(r.progress)}%</td></tr><tr><th>Mô tả / yêu cầu / ghi chú</th><td>${esc(r.description||'')}</td></tr></tbody></table><div class="form-signatures"><div>Người lập/Thực hiện<br><small>(Ký, ghi rõ họ tên)</small></div><div>Người rà soát<br><small>(Ký, ghi rõ họ tên)</small></div><div>Người phê duyệt<br><small>(Ký, ghi rõ họ tên)</small></div></div></article>`}
