  try{const saved=await api(current?`form-reports/${current.id}`:'form-reports',{method:current?'PUT':'POST',json:payload});current=saved;$('#erStatus').textContent=saved.offlineQueued?`Đã lưu an toàn trên máy Windows · CHƯA ĐỒNG BỘ · ${saved.updated_at}`:`Đã đồng bộ báo cáo #${saved.id}, lần sửa ${saved.revision} · ${saved.updated_at}`;['erPrint','erPdf','erDocx'].forEach(id=>$('#'+id).disabled=false);surface();toast(saved.offlineQueued?'Đã lưu cục bộ. Sẽ tự đồng bộ khi có mạng.':'Đã lưu báo cáo trên máy chủ.');}
  catch(err){toast(err.message,'err');$('#erStatus').textContent='Lưu không thành công: '+err.message;}
