function setupToolkitBrowser(){
 const search=$('#sourceSearch');if(search)search.oninput=()=>paintToolkitRows();
 $('#refreshSources')?.addEventListener('click',()=>loadToolkitFolder(state.toolkitPath?.at(-1)?.id||'',true));
 $('#openDriveLibrary')?.addEventListener('click',()=>go('drivefiles'));
 paintToolkitBreadcrumbs();
}
function paintToolkitBreadcrumbs(){
 const el=$('#sourceBreadcrumbs');if(!el)return;
 const path=state.toolkitPath||[{id:'',name:'Thư mục gốc'}];
 el.innerHTML=path.map((f,i)=>`<button type="button" class="btn small" data-library-crumb="${i}" ${i===path.length-1?'disabled':''}>${esc(f.name)}</button>`).join(' <span aria-hidden="true">›</span> ');
 $$('[data-library-crumb]',el).forEach(b=>b.onclick=()=>{const i=+b.dataset.libraryCrumb;state.toolkitPath=path.slice(0,i+1);if($('#sourceSearch'))$('#sourceSearch').value='';loadToolkitFolder(state.toolkitPath.at(-1).id)});
}
function paintToolkitRows(){
 const tbody=$('#sourceTbody');if(!tbody||state.module!=='toolkit')return;
 const q=String($('#sourceSearch')?.value||'').toLocaleLowerCase('vi-VN').trim();
 const entries=(state.toolkitEntries||[]).filter(x=>!q||[x.name,x.category,(x.clauses||[]).join(' ')].join(' ').toLocaleLowerCase('vi-VN').includes(q));
 const view=entries.slice(0,150),count=$('#sourceCount');
 if(count)count.textContent=`${entries.length} mục${entries.length>150?' · hiển thị 150 mục đầu':''}`;
 tbody.innerHTML=view.map(x=>{
  if(x.isFolder)return `<tr><td><button type="button" class="iso-library-folder" data-library-folder="${esc(x.id)}">▣ ${esc(x.name)}</button></td><td>Thư mục</td><td>—</td><td><button type="button" class="btn small" data-library-folder="${esc(x.id)}">Mở thư mục</button></td></tr>`;
  const url=x.appUrl||x.driveUrl||x.webViewLink||'';
  return `<tr><td><strong>${esc(x.name||'Tài liệu')}</strong></td><td>${esc(x.category||'Tài liệu nguồn')}</td><td>${esc((x.clauses||[]).join(', ')||'—')}</td><td>${url?`<a class="btn small" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Mở tệp</a>`:'—'}</td></tr>`;
 }).join('')||(state.toolkitFolderLoading?'<tr><td colspan="4" class="empty">Đang tải thư mục…</td></tr>':'<tr><td colspan="4" class="empty">Không có tài liệu phù hợp trong thư mục này.</td></tr>');
 $$('[data-library-folder]',tbody).forEach(b=>b.onclick=()=>{
  const id=b.dataset.libraryFolder,item=(state.toolkitEntries||[]).find(x=>x.id===id&&x.isFolder);
  if(!item)return;state.toolkitPath.push({id,name:item.name});$('#sourceSearch').value='';paintToolkitBreadcrumbs();loadToolkitFolder(id);
 });
}
async function loadToolkitFolder(folderId='',force=false){
 if(state.module!=='toolkit'||!$('#sourceTbody'))return;
 const seq=state.toolkitBrowseSeq=1+(state.toolkitBrowseSeq||0);
 state.toolkitFolderLoading=true;state.toolkitEntries=[];
 const status=$('#sourceLibraryStatus');if(status)status.textContent='Đang truy xuất thư mục. Các biểu mẫu và danh mục phía trên vẫn sử dụng bình thường.';
 paintToolkitBreadcrumbs();paintToolkitRows();
 try{
  const p=`knowledge/sources?mode=folder${folderId?'&folderId='+encodeURIComponent(folderId):''}${force?'&refresh=1':''}`;
  const data=await api(p,{timeoutMs:18000,noDedupe:true});
  if(seq!==state.toolkitBrowseSeq||state.module!=='toolkit')return;
  if(!data.connected)throw new Error(data.error||'Không truy cập được Google Drive.');
  state.toolkitEntries=data.items||[];
  if(status)status.textContent=data.truncated?'Thư mục có trên 1.000 mục; hiển thị phần đầu. Vui lòng chia nhỏ thư mục để xem đủ.':'';
 }catch(e){
  if(seq!==state.toolkitBrowseSeq||state.module!=='toolkit')return;
  if(status)status.innerHTML=`<div class="note">${esc(e.message||'Chưa tải được tài liệu từ Google Drive.')} <button class="btn small" type="button" id="retryLibraryFolder">Thử lại</button> · <button class="btn small" type="button" data-go="drivefiles">Mở Kho Google Drive</button></div>`;
  $('#retryLibraryFolder')?.addEventListener('click',()=>loadToolkitFolder(folderId));
  $('#sourceLibraryStatus [data-go]')?.addEventListener('click',()=>go('drivefiles'));
 }finally{
  if(seq===state.toolkitBrowseSeq&&state.module==='toolkit'){state.toolkitFolderLoading=false;paintToolkitRows()}
 }
}
