function teamPermissionHtml(team,u={}){const safe=(team.safeCaps||[]).filter(x=>x!=='access');const custom=u.permissionMode==='custom';const perms=u.permissions||{};return `<div class="field full"><label class="switch-line"><input type="checkbox" id="staffCustomPermissions" ${custom?'checked':''}> <strong>Tùy chỉnh quyền cho tài khoản này</strong></label><div class="staff-permission-grid">${safe.map(cap=>`<label class="staff-permission"><input type="checkbox" data-staff-cap="${esc(cap)}" ${perms[cap]!==false?'checked':''} ${custom?'':'disabled'}><span>${esc(staffCapLabels[cap]||cap)}</span></label>`).join('')}</div></div>`}
