function openTeamUserForm(team,u={}){openDrawer(u.id?'Cập nhật nhân viên':'Thêm nhân viên Khoa Xét nghiệm','team',teamUserFormHtml(team,u),{layout:'modal'});const f=$('#teamUserForm');$('[data-close]',f).onclick=closeDrawer;const custom=$('#staffCustomPermissions',f);const sync=()=>$$('[data-staff-cap]',f).forEach(c=>c.disabled=!custom.checked);custom.onchange=sync;sync();f.onsubmit=async e=>{e.preventDefault();const fd=new FormData(f);const data=Object.fromEntries(fd.entries());data.is_active=f.is_active.checked;data.permission_mode=custom.checked?'custom':'inherit';data.permissions={};$$('[data-staff-cap]',f).forEach(c=>data.permissions[c.dataset.staffCap]=c.checked);if(!data.password)delete data.password;try{if(u.id)await api(`team/users/${u.id}`,{method:'PATCH',json:data});else await api('team/users',{method:'POST',json:data});toast(u.id?'Đã cập nhật nhân viên':'Đã tạo tài khoản nhân viên');closeDrawer();await refreshBootstrapLight();await renderTeam()}catch(err){toast(err.message,'err')}}}
