async function openTeamMember(id){try{const data=await api(`team/users/${id}/workload`),u=data.user||{},rows=data.workload||[];const stats=u.stats||{};const work=rows.map(x=>`<tr ${x.canOpen?`data-record="${x.id}"`:''} class="${x.canOpen?'':'readonly-row'}"><td><strong>${esc(x.title)}</strong><div class="meta">${esc(moduleMeta[x.module]?.label||x.module)}${x.code?' · '+esc(x.code):''}</div></td><td>${x.assignment_role==='lead'?'Phụ trách chính':'Phối hợp'}</td><td><span class="badge ${esc(workloadStatusClass(x.status))}">${esc(statusLabels[x.status]||x.status)}</span></td><td><div class="progress"><span style="width:${Math.max(0,Math.min(100,x.progress||0))}%"></span></div><small>${x.progress||0}%</small></td><td>${fmtDate(x.due_date)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Chưa có công việc được phân công.</td></tr>';const buttons=state.boot.user.isWpAdmin||hasCap('manage_lab_staff')?`<div class="form-actions team-member-actions">${u.role==='lab_staff'?`<button class="btn" id="editTeamMember">Sửa tài khoản & quyền</button><button class="btn danger" id="deleteTeamMember">Xóa / ngừng tài khoản</button>`:''}</div>`:'';openDrawer(u.name||'Nhân sự Khoa Xét nghiệm','team',`<div class="team-member-detail"><div class="team-member-summary"><div class="team-avatar large">${esc((u.name||'N').charAt(0).toUpperCase())}</div><div><h3>${esc(u.name||'')}</h3><p>${esc(u.roleLabel||'')} · ${esc(u.department||'Khoa Xét nghiệm')}</p></div></div><div class="team-kpis compact"><div><small>Đang thực hiện</small><strong>${stats.active||0}</strong></div><div><small>Quá hạn</small><strong>${stats.overdue||0}</strong></div><div><small>Phụ trách chính</small><strong>${stats.lead||0}</strong></div><div><small>Tiến độ TB</small><strong>${stats.avgProgress||0}%</strong></div></div><div class="section-title">Công việc được phân công</div><div class="table-card"><table class="data-table"><thead><tr><th>CÔNG VIỆC</th><th>VAI TRÒ</th><th>TRẠNG THÁI</th><th>TIẾN ĐỘ</th><th>THỜI HẠN</th></tr></thead><tbody>${work}</tbody></table></div>${buttons}</div>`,{layout:'modal'});$$('[data-record]',$('#drawerBody')).forEach(x=>x.onclick=()=>{closeDrawer();openRecord(+x.dataset.record)});$('#editTeamMember')?.addEventListener('click',async()=>{closeDrawer();const team=await api('team');openTeamUserForm(team,u)});$('#deleteTeamMember')?.addEventListener('click',async()=>{if(!confirm(`Xóa hoặc ngừng tài khoản ${u.name}?`))return;try{const out=await api(`team/users/${u.id}`,{method:'DELETE'});toast(out.archived?'Đã ngừng tài khoản để bảo toàn lịch sử':'Đã xóa tài khoản');closeDrawer();await refreshBootstrapLight();await renderTeam()}catch(err){toast(err.message,'err')}})}catch(e){toast(e.message,'err')}}
async function renderTeam(){const data=await api('team');const totals=data.totals||{};const rows=(data.members||[]).map(u=>`<tr class="team-row ${u.isActive?'':'inactive'}" data-team-member="${u.id}"><td><div class="team-person"><span class="team-avatar">${esc((u.name||'N').charAt(0).toUpperCase())}</span><div><strong>${esc(u.name)}</strong><small>${esc(u.roleLabel||'')}${u.isActive?'':' · Ngừng hoạt động'}</small></div></div></td><td>${u.stats.active||0}</td><td><strong class="${u.stats.overdue?'text-danger':''}">${u.stats.overdue||0}</strong></td><td>${u.stats.due7||0}</td><td>${u.stats.lead||0}</td><td><div class="team-progress-cell"><div class="progress"><span style="width:${Math.max(0,Math.min(100,u.stats.avgProgress||0))}%"></span></div><b>${u.stats.avgProgress||0}%</b></div></td><td>${u.stats.supportRequests||0}</td><td>${u.stats.lastUpdate?esc(u.stats.lastUpdate):'—'}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">Chưa có tài khoản nhân sự Khoa Xét nghiệm.</td></tr>';$('#content').innerHTML=`<section class="card module-hero team-hero"><div><span class="eyebrow">KHOA XÉT NGHIỆM</span><h2>Nhân sự & phân công công việc</h2><p>Theo dõi người phụ trách, người phối hợp, thời hạn, tiến độ và các nội dung cần hỗ trợ.</p></div>${data.canManage?'<button class="btn primary" id="addTeamMember">＋ Thêm nhân viên</button>':''}</section><section class="team-kpis"><div class="card"><small>Nhân viên</small><strong>${totals.staff||0}</strong><span>Tài khoản Khoa Xét nghiệm</span></div><div class="card"><small>Đang thực hiện</small><strong>${totals.activeTasks||0}</strong><span>Công việc chưa hoàn tất</span></div><div class="card danger"><small>Quá hạn</small><strong>${totals.overdue||0}</strong><span>Cần ưu tiên xử lý</span></div><div class="card warning"><small>Sắp đến hạn</small><strong>${totals.due7||0}</strong><span>Trong 7 ngày</span></div><div class="card support"><small>Đề nghị hỗ trợ</small><strong>${totals.supportRequests||0}</strong><span>Từ cập nhật tiến độ</span></div></section><section class="card panel"><div class="panel-head"><div><h3>Khối lượng công việc theo nhân sự</h3><div class="panel-sub">Bấm vào tên nhân viên để xem danh sách công việc và tiến độ chi tiết.</div></div><button class="btn small" data-go="tasks">Mở danh sách công việc</button></div><div class="table-card"><table class="data-table team-table"><thead><tr><th>NHÂN SỰ</th><th>ĐANG LÀM</th><th>QUÁ HẠN</th><th>7 NGÀY</th><th>PHỤ TRÁCH CHÍNH</th><th>TIẾN ĐỘ TB</th><th>CẦN HỖ TRỢ</th><th>CẬP NHẬT GẦN NHẤT</th></tr></thead><tbody>${rows}</tbody></table></div></section>`;$('#addTeamMember')?.addEventListener('click',()=>openTeamUserForm(data));$$('[data-team-member]').forEach(x=>x.onclick=()=>openTeamMember(+x.dataset.teamMember));$$('[data-go]').forEach(x=>x.onclick=()=>go(x.dataset.go))}

const competencyItemTypeLabels={role:'Năng lực chung',process:'Quá trình',test:'Xét nghiệm/phương pháp',equipment:'Thiết bị',system:'Hệ thống thông tin',quality:'Kiểm soát chất lượng',authorization:'Hoạt động cần ủy quyền'};
const competencyStatusLabels={competent:'Đạt năng lực',assessment_due:'Đến hạn đánh giá',expired:'Hết hạn ủy quyền',not_competent:'Chưa đạt',in_training:'Đang đào tạo'};
function competencyStatusClass(s){return s==='competent'?'done':s==='expired'||s==='not_competent'?'critical':s==='assessment_due'?'warning':'in_progress'}
function competencyItemFormHtml(item={}){return `<form id="competencyItemForm"><div class="form-grid"><div class="field"><label>Mã năng lực *</label><input name="code" required value="${esc(item.code||'')}"></div><div class="field"><label>Nhóm năng lực</label><select name="item_type">${Object.entries(competencyItemTypeLabels).map(([k,v])=>`<option value="${k}" ${item.item_type===k?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div class="field full"><label>Tên năng lực *</label><input name="title" required value="${esc(item.title||'')}"></div><div class="field"><label>Điều khoản ISO liên quan</label><input name="iso_clause" value="${esc(item.iso_clause||'')}"></div><div class="field"><label>Chu kỳ đánh giá (tháng)</label><input type="number" min="1" max="60" name="assessment_frequency_months" value="${esc(item.assessment_frequency_months||12)}"></div><div class="field"><label>Thời hạn ủy quyền (tháng)</label><input type="number" min="1" max="60" name="authorization_valid_months" value="${esc(item.authorization_valid_months||12)}"></div><div class="field full"><label>Mô tả năng lực</label><textarea name="description">${esc(item.description||'')}</textarea></div><div class="field full"><label>Đào tạo cần hoàn thành</label><textarea name="required_training">${esc(item.required_training||'')}</textarea></div><div class="field full"><label><input style="width:auto" type="checkbox" name="is_active" ${item.id?(item.is_active?'checked':''):'checked'}> Đang sử dụng</label></div></div><div class="form-actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">${item.id?'Lưu thay đổi':'Tạo tiêu chí năng lực'}</button></div></form>`}
function openCompetencyItemForm(data,item={}){openDrawer(item.id?'Cập nhật tiêu chí năng lực':'Thêm tiêu chí năng lực','competency',competencyItemFormHtml(item),{layout:'modal'});const f=$('#competencyItemForm');$('[data-close]',f).onclick=closeDrawer;f.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f).entries());d.is_active=f.is_active.checked;try{if(item.id)await api(`competency/items/${item.id}`,{method:'PATCH',json:d});else await api('competency/items',{method:'POST',json:d});toast(item.id?'Đã cập nhật tiêu chí năng lực':'Đã thêm tiêu chí năng lực');closeDrawer();await renderCompetency()}catch(err){toast(err.message,'err')}}}
function competencyAssignFormHtml(data,memberRef=''){return `<form id="competencyAssignForm"><div class="form-grid"><div class="field"><label>Nhân viên *</label><select name="user_ref" required><option value="">Chọn nhân viên</option>${(data.members||[]).filter(x=>x.isActive).map(x=>`<option value="${esc(x.ref)}" ${memberRef===x.ref?'selected':''}>${esc(x.name)} — ${esc(x.roleLabel)}</option>`).join('')}</select></div><div class="field"><label>Năng lực *</label><select name="competency_id" required><option value="">Chọn nội dung</option>${(data.items||[]).filter(x=>x.is_active).map(x=>`<option value="${x.id}">${esc(x.code)} · ${esc(x.title)}</option>`).join('')}</select></div><div class="field"><label>Mức yêu cầu</label><input name="required_level" value="Đạt yêu cầu thực hành độc lập"></div><div class="field"><label>Hạn hoàn thành</label><input type="date" name="due_date"></div><div class="field full"><label>Ghi chú</label><textarea name="notes"></textarea></div></div><div class="form-actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">Phân công năng lực</button></div></form>`}
function openCompetencyAssign(data,memberRef=''){openDrawer('Phân công năng lực','competency',competencyAssignFormHtml(data,memberRef),{layout:'modal'});const f=$('#competencyAssignForm');$('[data-close]',f).onclick=closeDrawer;f.onsubmit=async e=>{e.preventDefault();try{await api('competency/assignments',{method:'POST',json:Object.fromEntries(new FormData(f).entries())});toast('Đã phân công năng lực');closeDrawer();await renderCompetency()}catch(err){toast(err.message,'err')}}}
function competencyAssessmentFormHtml(a,data){return `<form id="competencyAssessmentForm"><div class="competency-form-context"><strong>${esc(a.code)} · ${esc(a.title)}</strong><span>${esc(a.user_name||'')}</span></div><div class="form-grid"><div class="field"><label>Ngày đánh giá</label><input type="date" name="assessed_at" value="${new Date().toISOString().slice(0,10)}"></div><div class="field"><label>Phương pháp đánh giá</label><select name="method">${Object.entries(data.assessmentMethods||{}).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('')}</select></div><div class="field"><label>Kết quả *</label><select name="result" required><option value="competent">Đạt năng lực</option><option value="needs_training">Cần đào tạo bổ sung</option><option value="not_competent">Chưa đạt năng lực</option></select></div><div class="field"><label>Điểm (nếu áp dụng)</label><input type="number" min="0" max="100" name="score"></div><div class="field"><label>Đánh giá lại vào</label><input type="date" name="next_due"></div><div class="field"><label>Liên kết bằng chứng</label><input name="evidence_url" placeholder="Google Drive / hồ sơ liên quan"></div><div class="field full"><label>Nhận xét</label><textarea name="notes"></textarea></div></div><div class="form-actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">Lưu đánh giá</button></div></form>`}
function competencyAuthorizationFormHtml(a){const auth=a.authorization||{};return `<form id="competencyAuthorizationForm"><div class="competency-form-context"><strong>${esc(a.code)} · ${esc(a.title)}</strong><span>Chỉ cấp ủy quyền khi đánh giá năng lực đạt và còn hiệu lực.</span></div><div class="form-grid"><div class="field full"><label>Phạm vi được ủy quyền</label><textarea name="scope">${esc(auth.scope||a.title||'')}</textarea></div><div class="field"><label>Hiệu lực từ</label><input type="date" name="valid_from" value="${new Date().toISOString().slice(0,10)}"></div><div class="field"><label>Hiệu lực đến</label><input type="date" name="valid_until"></div><div class="field full"><label>Ghi chú</label><textarea name="notes"></textarea></div></div><div class="form-actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary" name="action" value="grant">Cấp / gia hạn ủy quyền</button>${auth.effective_status==='active'?'<button class="btn warning" name="action" value="suspend">Tạm dừng</button><button class="btn danger" name="action" value="revoke">Thu hồi</button>':''}</div></form>`}
function competencyTrainingFormHtml(a){return `<form id="competencyTrainingForm"><div class="competency-form-context"><strong>${esc(a.code)} · ${esc(a.title)}</strong>${a.required_training?`<span>Đào tạo gợi ý: ${esc(a.required_training)}</span>`:''}</div><div class="form-grid"><div class="field full"><label>Nội dung đào tạo *</label><input name="title" required value="${esc(a.required_training||'')}"></div><div class="field"><label>Đơn vị/giảng viên</label><input name="provider"></div><div class="field"><label>Hạn hoàn thành</label><input type="date" name="required_by"></div><div class="field"><label>Trạng thái</label><select name="status"><option value="required">Cần hoàn thành</option><option value="in_progress">Đang học/đào tạo</option><option value="completed">Đã hoàn thành</option></select></div><div class="field"><label>Ngày hoàn thành</label><input type="date" name="completed_at"></div><div class="field full"><label>Liên kết chứng nhận/hồ sơ</label><input name="evidence_url"></div><div class="field full"><label>Ghi chú</label><textarea name="notes"></textarea></div></div><div class="form-actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">Lưu đào tạo</button></div></form>`}
function competencyAssignmentHtml(a,canManage){const as=a.assessment,au=a.authorization,tr=a.training||[];const alerts=[];if(a.alerts?.assessmentDue)alerts.push('<span class="competency-alert danger">Đến hạn đánh giá</span>');else if(a.alerts?.assessmentSoon)alerts.push('<span class="competency-alert warning">Sắp đến hạn đánh giá</span>');if(a.alerts?.authorizationExpired)alerts.push('<span class="competency-alert danger">Ủy quyền hết hạn</span>');else if(a.alerts?.authorizationSoon)alerts.push('<span class="competency-alert warning">Ủy quyền sắp hết hạn</span>');if(a.alerts?.trainingDue)alerts.push('<span class="competency-alert warning">Đào tạo quá hạn</span>');return `<article class="competency-assignment-card"><div class="competency-assignment-head"><div><span class="code">${esc(a.code)}</span><h4>${esc(a.title)}</h4><small>${esc(competencyItemTypeLabels[a.item_type]||a.item_type)} · ISO ${esc(a.iso_clause||'—')}</small></div><span class="badge ${competencyStatusClass(a.matrix_status)}">${esc(competencyStatusLabels[a.matrix_status]||a.matrix_status)}</span></div>${alerts.length?`<div class="competency-alerts">${alerts.join('')}</div>`:''}<div class="competency-assignment-grid"><div><small>Đánh giá gần nhất</small><strong>${as?fmtDate(as.assessed_at):'Chưa đánh giá'}</strong><span>${as?esc(as.result==='competent'?'Đạt':as.result==='needs_training'?'Cần đào tạo':'Chưa đạt'):'—'}${as?.next_due?' · Đánh giá lại '+fmtDate(as.next_due):''}</span></div><div><small>Ủy quyền</small><strong>${au?esc(au.effective_status==='active'?'Đang hiệu lực':au.effective_status==='expired'?'Hết hạn':au.status==='suspended'?'Tạm dừng':'Đã thu hồi'):'Chưa cấp'}</strong><span>${au?.valid_until?'Đến '+fmtDate(au.valid_until):'—'}</span></div><div><small>Đào tạo</small><strong>${tr.filter(x=>x.status==='completed').length}/${tr.length||0} hoàn thành</strong><span>${esc(a.required_training||'Chưa quy định')}</span></div></div>${canManage?`<div class="competency-actions"><button class="btn small" data-comp-assess="${a.id}">Đánh giá</button><button class="btn small" data-comp-auth="${a.id}">Ủy quyền</button><button class="btn small" data-comp-training="${a.id}">Đào tạo</button><button class="btn small danger" data-comp-remove="${a.id}">Bỏ phân công</button></div>`:''}</article>`}
function openCompetencyMember(data,ref){const row=(data.matrix||[]).find(x=>x.member?.ref===ref);if(!row)return;const m=row.member,s=row.summary||{},cards=(row.assignments||[]).map(x=>competencyAssignmentHtml(x,data.canManage)).join('')||'<div class="note">Chưa được phân công nội dung năng lực.</div>';openDrawer(m.name,'competency',`<div class="competency-member"><div class="team-member-summary"><div class="team-avatar large">${esc((m.name||'N').charAt(0).toUpperCase())}</div><div><h3>${esc(m.name)}</h3><p>${esc(m.roleLabel||'')} · ${m.isActive?'Đang hoạt động':'Ngừng hoạt động'}</p></div>${data.canManage?'<button class="btn primary small" id="assignCompetencyMember">＋ Phân công năng lực</button>':''}</div><div class="competency-member-kpis"><div><small>Nội dung cần đáp ứng</small><strong>${s.total||0}</strong></div><div><small>Đạt năng lực</small><strong>${s.competent||0}</strong></div><div><small>Tỷ lệ đạt</small><strong>${s.competencyPct||0}%</strong></div><div><small>Đến hạn đánh giá</small><strong>${s.assessmentDue||0}</strong></div><div><small>Cảnh báo ủy quyền</small><strong>${s.authorizationAlerts||0}</strong></div></div><div class="competency-assignment-list">${cards}</div></div>`,{layout:'modal'});$('#assignCompetencyMember')?.addEventListener('click',()=>openCompetencyAssign(data,ref));$$('[data-comp-assess]').forEach(b=>b.onclick=()=>{const a=row.assignments.find(x=>x.id===+b.dataset.compAssess);openDrawer('Đánh giá năng lực','competency',competencyAssessmentFormHtml({...a,user_name:m.name},data),{layout:'modal'});const f=$('#competencyAssessmentForm');$('[data-close]',f).onclick=closeDrawer;f.onsubmit=async e=>{e.preventDefault();try{await api(`competency/assignments/${a.id}/assessment`,{method:'POST',json:Object.fromEntries(new FormData(f).entries())});toast('Đã lưu đánh giá năng lực');closeDrawer();await renderCompetency()}catch(err){toast(err.message,'err')}}});$$('[data-comp-auth]').forEach(b=>b.onclick=()=>{const a=row.assignments.find(x=>x.id===+b.dataset.compAuth);openDrawer('Phạm vi ủy quyền','competency',competencyAuthorizationFormHtml(a),{layout:'modal'});const f=$('#competencyAuthorizationForm');$('[data-close]',f).onclick=closeDrawer;f.addEventListener('submit',async e=>{e.preventDefault();const submit=e.submitter;const d=Object.fromEntries(new FormData(f).entries());d.action=submit?.value||'grant';try{await api(`competency/assignments/${a.id}/authorization`,{method:'POST',json:d});toast(d.action==='grant'?'Đã cập nhật ủy quyền':d.action==='suspend'?'Đã tạm dừng ủy quyền':'Đã thu hồi ủy quyền');closeDrawer();await renderCompetency()}catch(err){toast(err.message,'err')}})});$$('[data-comp-training]').forEach(b=>b.onclick=()=>{const a=row.assignments.find(x=>x.id===+b.dataset.compTraining);openDrawer('Đào tạo bắt buộc','competency',competencyTrainingFormHtml(a),{layout:'modal'});const f=$('#competencyTrainingForm');$('[data-close]',f).onclick=closeDrawer;f.onsubmit=async e=>{e.preventDefault();try{await api(`competency/assignments/${a.id}/training`,{method:'POST',json:Object.fromEntries(new FormData(f).entries())});toast('Đã cập nhật đào tạo');closeDrawer();await renderCompetency()}catch(err){toast(err.message,'err')}}});$$('[data-comp-remove]').forEach(b=>b.onclick=async()=>{if(!confirm('Bỏ nội dung năng lực này khỏi nhân viên?'))return;try{await api(`competency/assignments/${b.dataset.compRemove}`,{method:'DELETE'});toast('Đã bỏ phân công năng lực');closeDrawer();await renderCompetency()}catch(err){toast(err.message,'err')}})}
async function renderCompetency(){const data=await api('competency/overview'),sum=data.summary||{};const matrix=(data.matrix||[]).map(x=>`<tr data-comp-member="${esc(x.member.ref)}"><td><div class="team-person"><span class="team-avatar">${esc((x.member.name||'N').charAt(0).toUpperCase())}</span><div><strong>${esc(x.member.name)}</strong><small>${esc(x.member.roleLabel||'')}${x.member.isActive?'':' · Ngừng hoạt động'}</small></div></div></td><td>${x.summary.total||0}</td><td><div class="team-progress-cell"><div class="progress"><span style="width:${Math.max(0,Math.min(100,x.summary.competencyPct||0))}%"></span></div><b>${x.summary.competencyPct||0}%</b></div></td><td><strong class="${x.summary.assessmentDue?'text-danger':''}">${x.summary.assessmentDue||0}</strong></td><td><strong class="${x.summary.authorizationAlerts?'text-warning':''}">${x.summary.authorizationAlerts||0}</strong></td><td>${x.summary.trainingDue||0}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Chưa có nhân sự Khoa Xét nghiệm.</td></tr>';const catalog=(data.items||[]).map(i=>`<tr data-comp-item="${i.id}"><td><span class="code">${esc(i.code)}</span></td><td><strong>${esc(i.title)}</strong><div class="meta">${esc(i.description||'')}</div></td><td>${esc(competencyItemTypeLabels[i.item_type]||i.item_type)}</td><td>${esc(i.iso_clause||'—')}</td><td>${i.assessment_frequency_months} tháng</td><td>${i.authorization_valid_months} tháng</td><td>${i.is_active?'<span class="badge active">Đang dùng</span>':'<span class="badge closed">Ngừng dùng</span>'}</td></tr>`).join('');$('#content').innerHTML=`<section class="card module-hero competency-hero"><div><span class="eyebrow">ISO 15189 · NHÂN SỰ</span><h2>Năng lực & ủy quyền</h2><p>Theo dõi yêu cầu năng lực, đánh giá định kỳ, đào tạo bắt buộc và phạm vi được phép thực hiện của từng nhân viên.</p></div>${data.canManage?'<div class="hero-actions"><button class="btn" id="newCompetencyItem">＋ Tiêu chí năng lực</button><button class="btn primary" id="assignCompetency">＋ Phân công</button></div>':''}</section><section class="competency-kpis"><div class="card"><small>Phân công năng lực</small><strong>${sum.assignments||0}</strong><span>Đang theo dõi</span></div><div class="card good"><small>Đạt năng lực</small><strong>${sum.competencyPct||0}%</strong><span>${sum.competent||0}/${sum.assignments||0} nội dung</span></div><div class="card warning"><small>Đến hạn đánh giá</small><strong>${sum.assessmentDue||0}</strong><span>Cần đánh giá/đánh giá lại</span></div><div class="card warning"><small>Ủy quyền sắp hết hạn</small><strong>${sum.authorizationExpiring||0}</strong><span>Trong 30 ngày</span></div><div class="card danger"><small>Ủy quyền hết hạn</small><strong>${sum.authorizationExpired||0}</strong><span>Không nên thực hiện độc lập</span></div></section><section class="card panel"><div class="panel-head"><div><h3>Ma trận năng lực nhân viên</h3><div class="panel-sub">Bấm vào từng nhân viên để xem chi tiết đánh giá, đào tạo và ủy quyền.</div></div></div><div class="table-card"><table class="data-table competency-matrix"><thead><tr><th>NHÂN SỰ</th><th>NỘI DUNG</th><th>TỶ LỆ ĐẠT</th><th>ĐẾN HẠN ĐÁNH GIÁ</th><th>CẢNH BÁO ỦY QUYỀN</th><th>ĐÀO TẠO QUÁ HẠN</th></tr></thead><tbody>${matrix}</tbody></table></div></section><section class="card panel"><div class="panel-head"><div><h3>Danh mục năng lực</h3><div class="panel-sub">Chu kỳ đánh giá và thời hạn ủy quyền là thông số nội bộ, có thể điều chỉnh theo quy trình của Khoa Xét nghiệm.</div></div></div><div class="table-card"><table class="data-table"><thead><tr><th>MÃ</th><th>NỘI DUNG</th><th>NHÓM</th><th>ISO</th><th>ĐÁNH GIÁ</th><th>ỦY QUYỀN</th><th>TRẠNG THÁI</th></tr></thead><tbody>${catalog}</tbody></table></div></section>`;$('#newCompetencyItem')?.addEventListener('click',()=>openCompetencyItemForm(data));$('#assignCompetency')?.addEventListener('click',()=>openCompetencyAssign(data));$$('[data-comp-member]').forEach(r=>r.onclick=()=>openCompetencyMember(data,r.dataset.compMember));if(data.canManage)$$('[data-comp-item]').forEach(r=>r.onclick=()=>{const item=(data.items||[]).find(x=>x.id===+r.dataset.compItem);if(item)openCompetencyItemForm(data,item)})}

async function renderImplementation(){const data=await api('knowledge/implementation');if(state.module!=='implementation')return;const plan=data.plan||{};const ps=plan.progress_summary||{};const isoMilestoneCards=(plan.accreditation_milestones||[]).map((m,i)=>`<article class="cert-kpi"><small>${String(i+1).padStart(2,'0')} · ${esc(m.title)}</small><strong style="font-size:1rem">${fmtDate(m.start_date)} – ${fmtDate(m.end_date)}</strong></article>`).join('');const wizard=(plan.wizard||[]).map(x=>`<div class="wizard-step"><b>${x.step}</b><div><strong>${esc(x.title)}</strong><small>${esc(x.deliverable||'')}</small></div></div>`).join('');const tasksByCode=Object.fromEntries((data.tasks||[]).map(t=>[t.code,t]));const cards=(plan.consultant_plan||[]).map((x,i)=>{const code=`ISO-PLAN-${String(i+1).padStart(2,'0')}`,t=tasksByCode[code];const status=t?.status||x.status||'review';const statusText=t?(statusLabels[t.status]||t.status):(x.status==='done'?'Đã hoàn thành':x.status==='in_progress'?'Đang thực hiện':x.status==='open'?'Chưa hoàn thành':'Đang xem xét');const titleLine=String(x.content||'').split(String.fromCharCode(10))[0]||`Đầu việc ${i+1}`;return `<article class="plan-card"><div class="plan-head"><span class="code">${code}</span><span class="badge ${esc(status)}">${esc(statusText)}</span></div><h4>${esc(titleLine)}</h4><p>${esc(x.content||'')}</p><div class="plan-meta"><span><strong>Thực hiện:</strong> ${esc((x.assignees||[]).join(', ')||'—')}</span><span><strong>Giám sát:</strong> ${esc(x.supervisor||'—')}</span><span><strong>Thời hạn theo kế hoạch:</strong> ${fmtDate(x.due_date)}</span><span><strong>Hạn nộp tư vấn:</strong> ${fmtDate(x.consultant_due)}</span></div>${t?`<button class="btn small" data-record="${t.id}">Mở công việc · ${t.progress||0}%</button>`:''}</article>`}).join('');const summary=summaryCardsHtml(ps.summary_cards||[],'implementation-overview-cards');const progressRows=progressGroupRows(ps.current_groups||[]);const actionList=(ps.actions||[]).map(x=>`<li>${esc(x)}</li>`).join('');const difficultyList=(ps.difficulties||[]).map(x=>`<li>${esc(x)}</li>`).join('');const checklist=(plan.implementation_checklist||[]).map(x=>{const due=x.due_date||'';const overdue=due&&new Date(due+'T23:59:59')<new Date()&&!['done','completed','closed'].includes(x.status);const st=x.status_label||({not_started:'Chưa bắt đầu',in_progress:'Đang thực hiện',review:'Chờ rà soát',done:'Hoàn thành',blocked:'Đang vướng'}[x.status]||x.status||'Chưa bắt đầu');return `<tr class="${overdue?'row-overdue':''}"><td><b>${esc(x.seq)}</b></td><td><span class="priority-chip ${esc(String(x.priority||'').toLowerCase())}">${esc(({P0:'Cao',P1:'Trung bình',P2:'Theo kế hoạch'})[x.priority]||x.priority||'')}</span></td><td>${esc(x.phase||'')}</td><td><strong>${esc(x.task||'')}</strong><small class="source-path">ISO ${esc(x.clauses||'—')}</small></td><td>${esc(x.responsible||'—')}</td><td>${esc(x.accountable||'—')}</td><td>${esc(x.consulted_informed||'—')}</td><td><strong>${fmtDate(due)}</strong>${overdue?'<small class="text-danger">Quá mốc đề xuất</small>':''}</td><td><span class="badge ${esc(x.status||'new')}">${esc(st)}</span></td><td>${esc(x.dependencies||'—')}</td><td>${esc(x.evidence||'—')}</td><td>${esc(x.acceptance_criteria||'—')}</td><td>${esc(x.note||'')}</td></tr>`}).join('');const raci=(plan.responsibility_matrix||[]).map(x=>`<tr><td><strong>${esc(x.workstream||'')}</strong></td><td>${esc(x.responsible||'')}</td><td>${esc(x.accountable||'')}</td><td>${esc(x.consulted||'')}</td><td>${esc(x.informed||'')}</td><td>${esc(x.cadence||'')}</td></tr>`).join('');$('#content').innerHTML=`<div class="module-clarity mc-implementation"><section class="mc-intro"><div><span class="mc-eyebrow">KẾ HOẠCH TRIỂN KHAI</span><h2>${esc(plan.title||'Triển khai TCVN ISO 15189:2025')}</h2><p>Theo dõi công việc theo giai đoạn, đầu mối phụ trách và mốc kế hoạch.</p></div><div class="mc-project-state"><strong>${data.project?'Đã lập kế hoạch triển khai':'Chưa lập kế hoạch triển khai'}</strong><span>${data.tasks?.length||0}/${(plan.consultant_plan||[]).length} công việc đang được theo dõi</span></div></section>${isoMilestoneCards?`<section class="cert-kpi-grid" aria-label="Năm mốc kế hoạch ISO 15189">${isoMilestoneCards}</section>`:''}${plan.planning_note?`<details class="mc-source-note"><summary>Phạm vi và cơ sở kế hoạch</summary><p>${esc(plan.planning_note)}</p></details>`:''}<section class="mc-panel"><div class="mc-section-head"><div><h3>Công việc triển khai</h3><p>Xem người phụ trách, thời hạn và hồ sơ cần hoàn thành. Các mốc kế hoạch cần được đối chiếu với lịch đã phê duyệt.</p></div><div class="mc-intro-actions"><button class="btn small" id="printImplChecklist">In A4</button><button class="btn small" id="pdfImplChecklist">PDF A4</button><button class="btn small" id="docxImplChecklist">DOCX A4</button></div></div><div class="mc-plan-filters"><div class="mc-search"><label for="implLocalSearch">Tìm công việc</label><input id="implLocalSearch" type="search" placeholder="Tên công việc, đầu mối hoặc điều khoản…"></div><div><label for="implPhaseFilter">Giai đoạn</label><select id="implPhaseFilter"><option value="">Tất cả giai đoạn</option>${[...new Set((plan.implementation_checklist||[]).map(x=>x.phase).filter(Boolean))].map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}</select></div><div><label for="implPriorityFilter">Ưu tiên</label><select id="implPriorityFilter"><option value="">Tất cả ưu tiên</option><option value="P0">Ưu tiên cao</option><option value="P1">Ưu tiên trung bình</option><option value="P2">Theo kế hoạch</option></select></div><div><label for="implStatusFilter">Trạng thái</label><select id="implStatusFilter"><option value="">Tất cả trạng thái</option><option value="past_due">Quá mốc đề xuất</option>${[...new Set((plan.implementation_checklist||[]).map(x=>x.status||'not_started'))].map(v=>`<option value="${esc(v)}">${esc(implementationStateLabel({status:v}))}</option>`).join('')}</select></div></div><div class="mc-plan-legend">Ưu tiên cao · An toàn và yêu cầu bắt buộc <span>Ưu tiên trung bình · Cần hoàn thành trước đánh giá</span><span>Theo kế hoạch · Công việc tiếp nối</span></div><p id="implResultCount" class="mc-result-count" aria-live="polite"></p><div id="implWorkList" class="mc-work-list"></div><details class="mc-full-table"><summary>Xem bảng chi tiết · ${plan.implementation_checklist?.length||0} công việc · Bảng kế hoạch chi tiết</summary><p class="mc-result-count">Tệp tải xuống gồm toàn bộ công việc, kể cả những mục không hiển thị do đang lọc.</p><div class="table-card wide-table" id="implementationChecklistExport"><table class="data-table"><thead><tr><th>STT</th><th>ƯU TIÊN</th><th>GIAI ĐOẠN</th><th>CÔNG VIỆC / ĐIỀU KHOẢN</th><th>TRỰC TIẾP THỰC HIỆN</th><th>CHỊU TRÁCH NHIỆM CUỐI CÙNG</th><th>PHỐI HỢP / ĐƯỢC THÔNG TIN</th><th>HẠN</th><th>TRẠNG THÁI</th><th>PHỤ THUỘC</th><th>BẰNG CHỨNG HOÀN THÀNH</th><th>TIÊU CHÍ HOÀN THÀNH</th><th>GHI CHÚ</th></tr></thead><tbody>${checklist}</tbody></table></div></details></section>${summary?`<details class="mc-panel mc-secondary"><summary>Khối lượng tài liệu đang triển khai <small>Ngày báo cáo ${fmtDate(ps.report_date||'')}</small></summary><div class="mc-secondary-body">${summary}</div></details>`:''}<details class="mc-panel mc-secondary"><summary>Trình tự triển khai <small>${plan.wizard?.length||0} bước và đầu ra</small></summary><div class="mc-secondary-body"><div class="wizard-grid">${wizard}</div></div></details><details class="mc-panel mc-secondary"><summary>Phân công trách nhiệm <small>Thực hiện · Chịu trách nhiệm · Tham vấn · Thông tin</small></summary><div class="mc-secondary-body"><div class="table-card" id="raciExport"><table class="data-table"><thead><tr><th>NHÓM CÔNG VIỆC</th><th>TRỰC TIẾP THỰC HIỆN</th><th>CHỊU TRÁCH NHIỆM</th><th>THAM VẤN</th><th>ĐƯỢC THÔNG TIN</th><th>NHỊP THEO DÕI</th></tr></thead><tbody>${raci}</tbody></table></div></div></details>${progressRows?`<details class="mc-panel mc-secondary"><summary>Nhóm tài liệu đang theo dõi thực tế</summary><div class="mc-secondary-body"><div class="table-card"><table class="data-table"><thead><tr><th>NHÓM TÀI LIỆU</th><th>NGÀY GIAO</th><th>HẠN HOÀN THÀNH</th><th>TRẠNG THÁI</th><th>RÀ SOÁT</th><th>GHI CHÚ</th></tr></thead><tbody>${progressRows}</tbody></table></div></div></details>`:''}<section class="mc-panel"><div class="mc-section-head"><div><h3>Đầu việc nguồn / tư vấn</h3><p>Phân công và thời hạn nguồn được giữ để đối chiếu tiến độ thực tế.</p></div>${data.canSeed?'<button class="btn primary small" id="seedPlan">Khởi tạo/cập nhật dự án & công việc</button>':''}</div><details class="mc-source-tasks"><summary>Xem ${plan.consultant_plan?.length||0} đầu việc đang được theo dõi</summary><div class="plan-grid">${cards}</div></details></section><section class="implementation-notes-grid">${difficultyList?`<div class="mc-panel"><h3>Khó khăn, vướng mắc</h3><ul class="bulleted-list">${difficultyList}</ul></div>`:''}${actionList?`<div class="mc-panel"><h3>Hướng xử lý và kiểm soát tiến độ</h3><ul class="bulleted-list">${actionList}</ul></div>`:''}</section></div>`;$('#seedPlan')?.addEventListener('click',async()=>{try{const r=await api('knowledge/implementation/seed',{method:'POST'});toast(`Đã đồng bộ kế hoạch · thêm ${r.tasksCreated||0} công việc`);await refreshBootstrapLight();await renderImplementation()}catch(err){toast(err.message,'err')}});$$('[data-record]').forEach(x=>x.onclick=()=>openRecord(+x.dataset.record));$('#printImplChecklist')?.addEventListener('click',()=>{auditUiEvent('print_a4',{module:'implementation',title:'Bảng kiểm triển khai ISO'});printElementA4($('#implementationChecklistExport'))});$('#pdfImplChecklist')?.addEventListener('click',()=>exportElementPdf($('#implementationChecklistExport'),'Ke-hoach-trien-khai-ISO-15189.pdf',{action:'report_export',module:'implementation',title:'Bảng kiểm triển khai ISO'}));$('#docxImplChecklist')?.addEventListener('click',()=>exportElementDocx($('#implementationChecklistExport'),'Ke-hoach-trien-khai-ISO-15189.docx','Kế hoạch triển khai TCVN ISO 15189:2025',{action:'report_export',module:'implementation',title:'Bảng kiểm triển khai ISO'}));const drawWork=()=>{const q=clarityText($('#implLocalSearch').value.trim()),phase=$('#implPhaseFilter').value,priority=$('#implPriorityFilter').value,status=$('#implStatusFilter').value;const rows=(plan.implementation_checklist||[]).filter(x=>(!phase||x.phase===phase)&&(!priority||x.priority===priority)&&(!status||(status==='past_due'?implementationPastDue(x):(x.status||'not_started')===status))&&clarityText([x.task,x.responsible,x.accountable,x.clauses].join(' ')).includes(q));$('#implWorkList').innerHTML=rows.map(clarityImplementationItem).join('')||'<div class="mc-empty">Không có công việc phù hợp. Hãy điều chỉnh bộ lọc.</div>';$('#implResultCount').textContent=`${rows.length}/${plan.implementation_checklist?.length||0} công việc · Mốc kế hoạch đề xuất`};$('#implLocalSearch').addEventListener('input',drawWork);['implPhaseFilter','implPriorityFilter','implStatusFilter'].forEach(id=>$('#'+id).addEventListener('change',drawWork));drawWork()}
