function openBulkImport(initialKind='equipment'){
 const options=initialKind==='equipment'?[['equipment','Trang thiết bị']]:[['methods','Phương pháp xét nghiệm'],['iqc','Kế hoạch nội kiểm'],['eqa','Chương trình ngoại kiểm']];
 const html=`<form id="nahBulkImportForm" class="bulk-import-form"><p>Nhập dữ liệu từ bảng Excel theo mẫu của Khoa Xét nghiệm. Mỗi lượt chỉ nhập một nhóm dữ liệu; hệ thống không tự phê duyệt hồ sơ.</p><div class="form-grid"><div class="field"><label>Nhóm dữ liệu</label><select name="kind">${options.map(([k,t])=>`<option value="${k}">${esc(t)}</option>`).join('')}</select></div><div class="field"><label>Tệp Excel hoặc CSV (.xlsx, .csv)</label><input type="file" name="file" accept=".xlsx,.csv" required></div></div><p><a href="${esc(cfg.importTemplateUrl||'#')}" target="_blank" rel="noopener" download>Tải mẫu Excel ISO 15189</a> · <a id="nahCsvTemplate" href="#" download>CSV dự phòng</a> · Điền từ hàng 2, giữ nguyên tên các cột.</p><p class="note">Nhập lần lượt: thiết bị → phương pháp xét nghiệm → kế hoạch nội kiểm → chương trình ngoại kiểm. Những mục đã có sẽ được bỏ qua, không cập nhật đè. Để nhập hóa chất, lô, tồn kho và kết quả IQC/EQA từng lần, dùng chức năng Nhập dữ liệu chuẩn hóa. <button type="button" class="btn small" id="openExtendedImports">Mở nhập dữ liệu chuẩn hóa</button></p><div class="form-actions"><button type="button" class="btn primary" id="nahBulkPreview">Kiểm tra tệp</button><button type="button" class="btn" id="nahBulkApply" disabled>Xác nhận nhập</button></div><div id="nahBulkResults" class="note" role="status" aria-live="polite">Chưa chọn tệp.</div></form>`;
 openDrawer('Nhập danh mục từ Excel',initialKind==='equipment'?'resources':'methodquality',html,{layout:'modal'});
 $('#openExtendedImports')?.addEventListener('click',()=>openStandardDataImport().catch(e=>toast(e.message,'err')));const f=$('#nahBulkImportForm'),output=$('#nahBulkResults'),preview=$('#nahBulkPreview'),apply=$('#nahBulkApply');let checked=false;const csvLink=$('#nahCsvTemplate');const updateCsvLink=()=>{csvLink.href=(cfg.csvTemplateBaseUrl||'')+f.elements.kind.value+'.csv';csvLink.download='NAH-Mau-Nhap-'+f.elements.kind.value+'.csv';};updateCsvLink();f.elements.kind.addEventListener('change',updateCsvLink);
 const reset=()=>{checked=false;apply.disabled=true;output.textContent='Chọn Kiểm tra tệp để xem dữ liệu trước khi lưu.'};
 f.elements.kind.addEventListener('change',reset);f.elements.file.addEventListener('change',reset);
 async function upload(mode){const file=f.elements.file.files?.[0];if(!file){output.textContent='Vui lòng chọn tệp trước khi tiếp tục.';return;}
  if(file.size>4*1024*1024){output.textContent='Tệp vượt 4 MB. Hãy chia nhỏ dữ liệu.';return;}
  const body=new FormData();body.append('file',file,file.name);body.append('kind',f.elements.kind.value);body.append('mode',mode);
  preview.disabled=true;apply.disabled=true;output.textContent=mode==='apply'?'Đang lưu dữ liệu...':'Đang kiểm tra mã, ngày tháng và bản ghi trùng...';
  try{const r=await api('bulk-import',{method:'POST',body,timeoutMs:90000});const messages=[`Tổng số: ${r.total||0} dòng · Có thể tạo: ${r.willCreate||0} · Bỏ qua trùng: ${r.willSkip||0}`];
   if(r.errors?.length)messages.push('Cần sửa:\n'+r.errors.join('\n'));
   if(r.warnings?.length)messages.push('Lưu ý:\n'+r.warnings.join('\n'));
   if(mode==='apply'){messages.unshift(`Đã nhập ${r.imported||0} mục. Những mục mới cần được kiểm tra/phê duyệt theo quy trình.`);checked=false;}
   else checked=!!r.ok&&r.willCreate>0;
   output.textContent=messages.join('\n\n');output.style.whiteSpace='pre-wrap';
   apply.disabled=!checked;
   if(mode==='apply'){toast(`Đã nhập ${r.imported||0} mục`);const current=state.module;closeDrawer();if(current==='resources')await renderResources();else if(current==='methodquality')await renderMethodQuality();}
  }catch(err){checked=false;apply.disabled=true;output.textContent='Không thể xử lý tệp: '+err.message;}
  finally{preview.disabled=false;}
 }
 preview.onclick=()=>upload('preview');apply.onclick=()=>{if(checked)upload('apply');};
}
const resourceEquipmentStatusLabels={planned:'Kế hoạch',received:'Đã tiếp nhận',active:'Đang sử dụng',out_of_service:'Ngừng sử dụng',quarantine:'Cách ly',retired:'Ngừng khai thác'};
const resourceAcceptanceLabels={pending:'Chờ nghiệm thu',accepted:'Đạt',rejected:'Không đạt'};
const reagentTypeLabels={reagent:'Thuốc thử',calibrator:'Chất hiệu chuẩn',control:'Vật liệu kiểm soát',consumable:'Vật tư tiêu hao'};
const reagentLotStatusLabels={active:'Đang sử dụng',quarantine:'Cách ly',expired:'Hết hạn',depleted:'Đã dùng hết',recalled:'Thu hồi',disposed:'Đã hủy'};
function resourceBadge(label,kind=''){return `<span class="resource-badge ${esc(kind)}">${esc(label)}</span>`}
function openEquipmentForm(data,e={}){const manage=data.canManage; if(!manage)return; const html=`<form id="equipmentForm"><div class="form-grid"><div class="field"><label>Mã thiết bị *</label><input name="code" required value="${esc(e.code||'')}"></div><div class="field"><label>Tên thiết bị *</label><input name="name" required value="${esc(e.name||'')}"></div><div class="field"><label>Hãng sản xuất</label><input name="manufacturer" value="${esc(e.manufacturer||'')}"></div><div class="field"><label>Kiểu máy (model)</label><input name="model" value="${esc(e.model||'')}"></div><div class="field"><label>Số sê-ri</label><input name="serial_number" value="${esc(e.serial_number||'')}"></div><div class="field"><label>Nhà cung cấp</label><input name="supplier" value="${esc(e.supplier||'')}"></div><div class="field"><label>Vị trí</label><input name="location" value="${esc(e.location||'')}"></div><div class="field"><label>Tình trạng</label><select name="status">${Object.entries(resourceEquipmentStatusLabels).map(([k,v])=>`<option value="${k}" ${(e.status||'active')===k?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div class="field"><label>Nghiệm thu</label><select name="acceptance_status">${Object.entries(resourceAcceptanceLabels).map(([k,v])=>`<option value="${k}" ${(e.acceptance_status||'pending')===k?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div class="field"><label>Ngày tiếp nhận</label><input type="date" name="received_date" value="${esc(e.received_date||'')}"></div><div class="field"><label>Ngày đưa vào sử dụng</label><input type="date" name="in_service_date" value="${esc(e.in_service_date||'')}"></div><div class="field"><label>Hạn hiệu chuẩn kế tiếp</label><input type="date" name="next_calibration_date" value="${esc(e.next_calibration_date||'')}"></div><div class="field"><label>Chu kỳ hiệu chuẩn (tháng)</label><input type="number" min="0" name="calibration_interval_months" value="${esc(e.calibration_interval_months||'')}"></div><div class="field"><label>Hạn bảo trì kế tiếp</label><input type="date" name="next_maintenance_date" value="${esc(e.next_maintenance_date||'')}"></div><div class="field"><label>Chu kỳ bảo trì (tháng)</label><input type="number" min="0" name="maintenance_interval_months" value="${esc(e.maintenance_interval_months||'')}"></div><div class="field"><label>Phiên bản phần mềm</label><input name="software_version" value="${esc(e.software_version||'')}"></div><div class="field"><label>Phiên bản phần mềm nhúng (firmware)</label><input name="firmware_version" value="${esc(e.firmware_version||'')}"></div><div class="field full"><label>Liên kết hướng dẫn của nhà sản xuất</label><input name="manufacturer_manual_url" value="${esc(e.manufacturer_manual_url||'')}"></div><div class="field full"><label>Ghi chú</label><textarea name="notes">${esc(e.notes||'')}</textarea></div><div class="field full"><label><input style="width:auto" type="checkbox" name="calibration_required" ${e.id?(e.calibration_required?'checked':''):'checked'}> Thiết bị cần theo dõi hiệu chuẩn</label></div></div><div class="form-actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">${e.id?'Lưu thiết bị':'Thêm thiết bị'}</button></div></form>`;openDrawer(e.id?'Cập nhật thiết bị':'Thêm thiết bị','resources',html,{layout:'modal'});const f=$('#equipmentForm');$('[data-close]',f).onclick=closeDrawer;f.onsubmit=async ev=>{ev.preventDefault();const p=Object.fromEntries(new FormData(f).entries());p.calibration_required=f.calibration_required.checked;try{if(e.id)await api(`resources/equipment/${e.id}`,{method:'PATCH',json:p});else await api('resources/equipment',{method:'POST',json:p});toast(e.id?'Đã cập nhật thiết bị':'Đã thêm thiết bị');closeDrawer();await renderResources()}catch(err){toast(err.message,'err')}}}
function equipmentEventForm(e){return `<form id="equipmentEventForm"><div class="form-grid"><div class="field"><label>Hoạt động</label><select name="event_type"><option value="acceptance">Nghiệm thu</option><option value="calibration">Hiệu chuẩn</option><option value="maintenance">Bảo trì</option><option value="verification">Kiểm tra xác nhận</option><option value="repair">Sửa chữa</option><option value="incident">Sự cố</option><option value="recall">Thông báo thu hồi</option><option value="decommission">Ngừng khai thác</option></select></div><div class="field"><label>Ngày thực hiện</label><input type="date" name="event_date" value="${new Date().toISOString().slice(0,10)}"></div><div class="field"><label>Kết quả</label><select name="result"><option value="passed">Đạt</option><option value="accepted">Chấp nhận</option><option value="failed">Không đạt</option><option value="rejected">Không chấp nhận</option><option value="completed">Hoàn thành</option></select></div><div class="field"><label>Hạn tiếp theo</label><input type="date" name="next_due"></div><div class="field"><label>Đơn vị thực hiện</label><input name="provider"></div><div class="field"><label>Số chứng nhận / phiếu</label><input name="reference_no"></div><div class="field full"><label>Liên kết chứng nhận / bằng chứng</label><input name="evidence_url"></div><div class="field full"><label>Ghi chú</label><textarea name="notes"></textarea></div></div><div class="form-actions"><button class="btn primary">Lưu hoạt động</button></div></form>`}
function openEquipmentDetail(data,e){const events=(e.events||[]).map(x=>`<div class="resource-timeline-item"><span class="resource-dot"></span><div><strong>${esc({acceptance:'Nghiệm thu',calibration:'Hiệu chuẩn',maintenance:'Bảo trì',repair:'Sửa chữa',incident:'Sự cố',recall:'Thu hồi',verification:'Kiểm tra xác nhận',decommission:'Ngừng khai thác'}[x.event_type]||x.event_type)}</strong><small>${fmtDate(x.event_date)}${x.provider?' · '+esc(x.provider):''}${x.next_due?' · Hạn tiếp theo '+fmtDate(x.next_due):''}</small>${x.notes?`<p>${esc(x.notes)}</p>`:''}</div></div>`).join('')||'<div class="note">Chưa có hoạt động được ghi nhận.</div>';const operators=(e.operators||[]).map(o=>`<div class="assignment"><div><strong>${esc(o.name)}</strong><div class="meta">${o.operator_role==='supervisor'?'Giám sát':'Vận hành'}${o.valid_until?' · Hiệu lực đến '+fmtDate(o.valid_until):''}</div></div>${data.canManage?`<button class="btn small danger" data-remove-operator="${o.id}">Bỏ</button>`:''}</div>`).join('')||'<div class="note">Chưa gắn nhân sự được ủy quyền với thiết bị này.</div>';const authOpts=(data.competencyAuthorizations||[]).map(a=>`<option value="${a.assignment_id}|${a.authorization_id}|${esc(a.user_ref)}">${esc(a.name)} · ${esc(a.code)}${a.valid_until?' · đến '+fmtDate(a.valid_until):''}</option>`).join('');const html=`<div class="resource-detail"><div class="resource-profile"><div><span class="code">${esc(e.code)}</span><h3>${esc(e.name)}</h3><p>${esc([e.manufacturer,e.model,e.serial_number].filter(Boolean).join(' · '))}</p></div><div class="resource-profile-status">${resourceBadge(resourceEquipmentStatusLabels[e.status]||e.status,e.status)}${resourceBadge(resourceAcceptanceLabels[e.acceptance_status]||e.acceptance_status,e.acceptance_status)}</div></div><div class="resource-info-grid"><div><small>Vị trí</small><strong>${esc(e.location||'—')}</strong></div><div><small>Hiệu chuẩn kế tiếp</small><strong>${fmtDate(e.next_calibration_date)}</strong></div><div><small>Bảo trì kế tiếp</small><strong>${fmtDate(e.next_maintenance_date)}</strong></div><div><small>Nhà cung cấp</small><strong>${esc(e.supplier||'—')}</strong></div></div>${data.canManage?`<div class="form-actions resource-top-actions"><button class="btn" id="editEquipment">Sửa hồ sơ thiết bị</button></div>`:''}<section><h4>Nhân sự được ủy quyền</h4><div class="assignment-list">${operators}</div>${data.canManage&&authOpts?`<form id="operatorForm" class="inline-resource-form"><select name="authorization" required><option value="">Chọn nhân viên có ủy quyền thiết bị</option>${authOpts}</select><select name="operator_role"><option value="operator">Vận hành</option><option value="supervisor">Giám sát</option></select><button class="btn primary small">Phân công</button></form>`:''}</section><section><h4>Lịch sử thiết bị</h4><div class="resource-timeline">${events}</div></section>${data.canManage?`<section><h4>Ghi nhận hoạt động</h4>${equipmentEventForm(e)}</section>`:''}</div>`;openDrawer(e.name,'resources',html,{layout:'modal'});$('#editEquipment')?.addEventListener('click',()=>openEquipmentForm(data,e));$('#equipmentEventForm')?.addEventListener('submit',async ev=>{ev.preventDefault();try{await api(`resources/equipment/${e.id}/events`,{method:'POST',json:Object.fromEntries(new FormData(ev.currentTarget).entries())});toast('Đã lưu hoạt động thiết bị');closeDrawer();await renderResources()}catch(err){toast(err.message,'err')}});$('#operatorForm')?.addEventListener('submit',async ev=>{ev.preventDefault();const f=new FormData(ev.currentTarget),parts=String(f.get('authorization')||'').split('|');if(parts.length<3)return;try{await api(`resources/equipment/${e.id}/operators`,{method:'POST',json:{competency_assignment_id:+parts[0],authorization_id:+parts[1],user_ref:parts.slice(2).join('|'),operator_role:f.get('operator_role')}});toast('Đã gắn nhân sự được ủy quyền');closeDrawer();await renderResources()}catch(err){toast(err.message,'err')}});$$('[data-remove-operator]').forEach(b=>b.onclick=async()=>{if(!confirm('Bỏ phân công vận hành thiết bị này?'))return;try{await api(`resources/equipment/${e.id}/operators/${b.dataset.removeOperator}`,{method:'DELETE'});toast('Đã bỏ phân công');closeDrawer();await renderResources()}catch(err){toast(err.message,'err')}})}
function openReagentForm(data,r={}){if(!data.canManage)return;const html=`<form id="reagentForm"><div class="form-grid"><div class="field"><label>Mã *</label><input name="code" required value="${esc(r.code||'')}"></div><div class="field"><label>Tên thuốc thử / vật tư *</label><input name="name" required value="${esc(r.name||'')}"></div><div class="field"><label>Nhóm</label><select name="item_type">${Object.entries(reagentTypeLabels).map(([k,v])=>`<option value="${k}" ${(r.item_type||'reagent')===k?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div class="field"><label>Mã danh mục / tham chiếu</label><input name="catalog_no" value="${esc(r.catalog_no||'')}"></div><div class="field"><label>Hãng sản xuất</label><input name="manufacturer" value="${esc(r.manufacturer||'')}"></div><div class="field"><label>Nhà cung cấp</label><input name="supplier" value="${esc(r.supplier||'')}"></div><div class="field"><label>Điều kiện bảo quản</label><input name="storage_condition" value="${esc(r.storage_condition||'')}"></div><div class="field"><label>Đơn vị tính</label><input name="unit" value="${esc(r.unit||'')}"></div><div class="field"><label>Mức tồn tối thiểu</label><input type="number" step="0.001" min="0" name="min_stock" value="${esc(r.min_stock||0)}"></div><div class="field full"><label>Ghi chú</label><textarea name="notes">${esc(r.notes||'')}</textarea></div><div class="field full"><label><input style="width:auto" type="checkbox" name="is_active" ${r.id?(r.is_active?'checked':''):'checked'}> Đang sử dụng trong danh mục</label></div></div><div class="form-actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">${r.id?'Lưu thay đổi':'Thêm vào danh mục'}</button></div></form>`;openDrawer(r.id?'Cập nhật thuốc thử / vật tư':'Thêm thuốc thử / vật tư','resources',html,{layout:'modal'});const f=$('#reagentForm');$('[data-close]',f).onclick=closeDrawer;f.onsubmit=async ev=>{ev.preventDefault();const p=Object.fromEntries(new FormData(f).entries());p.is_active=f.is_active.checked;try{if(r.id)await api(`resources/reagents/${r.id}`,{method:'PATCH',json:p});else await api('resources/reagents',{method:'POST',json:p});toast(r.id?'Đã cập nhật danh mục':'Đã thêm thuốc thử/vật tư');closeDrawer();await renderResources()}catch(err){toast(err.message,'err')}}}
function openLotForm(data,r){const html=`<form id="lotForm"><div class="form-grid"><div class="field"><label>Số lô *</label><input name="lot_no" required></div><div class="field"><label>Ngày tiếp nhận</label><input type="date" name="received_date" value="${new Date().toISOString().slice(0,10)}"></div><div class="field"><label>Hạn dùng</label><input type="date" name="expiry_date"></div><div class="field"><label>Số lượng tiếp nhận</label><input type="number" step="0.001" min="0" name="qty_received" value="0"></div><div class="field"><label>Vị trí bảo quản</label><input name="location"></div><div class="field"><label>Liên kết chứng nhận / chứng thư phân tích (CoA)</label><input name="certificate_url"></div><div class="field full"><label>Ghi chú</label><textarea name="notes"></textarea></div></div><div class="form-actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">Tiếp nhận lô</button></div></form>`;openDrawer(`Tiếp nhận lô · ${r.name}`,'resources',html,{layout:'modal'});const f=$('#lotForm');$('[data-close]',f).onclick=closeDrawer;f.onsubmit=async ev=>{ev.preventDefault();try{await api(`resources/reagents/${r.id}/lots`,{method:'POST',json:Object.fromEntries(new FormData(f).entries())});toast('Đã tiếp nhận lô');closeDrawer();await renderResources()}catch(err){toast(err.message,'err')}}}
function openLotDetail(data,r,l){const tx=(l.transactions||[]).map(x=>`<div class="resource-timeline-item"><span class="resource-dot"></span><div><strong>${esc({receive:'Nhập kho',use:'Xuất sử dụng',adjust:'Điều chỉnh',dispose:'Hủy',transfer:'Chuyển kho'}[x.txn_type]||x.txn_type)} · ${x.quantity_change>0?'+':''}${esc(x.quantity_change)}</strong><small>${fmtDate(x.occurred_at)} · ${esc(x.actor_name||'')}</small>${x.notes?`<p>${esc(x.notes)}</p>`:''}</div></div>`).join('')||'<div class="note">Chưa có biến động tồn kho.</div>';const events=(l.events||[]).map(x=>`<div class="resource-timeline-item"><span class="resource-dot"></span><div><strong>${esc({acceptance:'Nghiệm thu lô',incident:'Sự cố',recall:'Thu hồi',temperature_excursion:'Sai lệch nhiệt độ',verification:'Kiểm tra xác nhận'}[x.event_type]||x.event_type)}</strong><small>${fmtDate(x.event_date)}</small>${x.notes?`<p>${esc(x.notes)}</p>`:''}</div></div>`).join('');const html=`<div class="resource-detail"><div class="resource-profile"><div><span class="code">Lô ${esc(l.lot_no)}</span><h3>${esc(r.name)}</h3><p>${esc(reagentTypeLabels[r.item_type]||r.item_type)} · ${esc(r.manufacturer||'')}</p></div><div class="resource-profile-status">${resourceBadge(resourceAcceptanceLabels[l.acceptance_status]||l.acceptance_status,l.acceptance_status)}${resourceBadge(reagentLotStatusLabels[l.status]||l.status,l.status)}</div></div><div class="resource-info-grid"><div><small>Tồn hiện tại</small><strong>${esc(l.qty_current)} ${esc(r.unit||'')}</strong></div><div><small>Hạn dùng</small><strong>${fmtDate(l.expiry_date)}</strong></div><div><small>Ngày mở</small><strong>${fmtDate(l.opened_date)}</strong></div><div><small>Hạn sau mở</small><strong>${fmtDate(l.open_expiry_date)}</strong></div></div>${data.canManage?`<section><h4>Nghiệm thu và trạng thái lô</h4><form id="lotUpdateForm"><div class="form-grid"><div class="field"><label>Nghiệm thu</label><select name="acceptance_status"><option value="pending" ${l.acceptance_status==='pending'?'selected':''}>Chờ nghiệm thu</option><option value="accepted" ${l.acceptance_status==='accepted'?'selected':''}>Đạt</option><option value="rejected" ${l.acceptance_status==='rejected'?'selected':''}>Không đạt</option></select></div><div class="field"><label>Trạng thái</label><select name="status">${Object.entries(reagentLotStatusLabels).map(([k,v])=>`<option value="${k}" ${l.status===k?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div class="field"><label>Ngày mở</label><input type="date" name="opened_date" value="${esc(l.opened_date||'')}"></div><div class="field"><label>Hạn sau mở</label><input type="date" name="open_expiry_date" value="${esc(l.open_expiry_date||'')}"></div></div><div class="form-actions"><button class="btn primary small">Lưu trạng thái lô</button></div></form></section><section><h4>Nhập / xuất tồn kho</h4><form id="inventoryTxnForm" class="inline-resource-form"><select name="txn_type"><option value="use">Xuất sử dụng</option><option value="receive">Nhập bổ sung</option><option value="dispose">Hủy</option><option value="transfer">Chuyển kho</option><option value="adjust">Điều chỉnh tăng</option></select><input type="number" step="0.001" min="0.001" name="quantity" placeholder="Số lượng" required><input name="reference_no" placeholder="Phiếu / tham chiếu"><button class="btn primary small">Lưu</button></form></section>`:''}<section><h4>Lịch sử tồn kho</h4><div class="resource-timeline">${tx}</div></section>${events?`<section><h4>Sự kiện liên quan</h4><div class="resource-timeline">${events}</div></section>`:''}${data.canManage?`<section><h4>Sự cố / thu hồi / sai lệch bảo quản</h4><form id="reagentEventForm" class="inline-resource-form"><select name="event_type"><option value="acceptance">Nghiệm thu</option><option value="verification">Kiểm tra xác nhận</option><option value="temperature_excursion">Sai lệch nhiệt độ</option><option value="incident">Sự cố</option><option value="recall">Thu hồi</option></select><input type="date" name="event_date" value="${new Date().toISOString().slice(0,10)}"><input name="notes" placeholder="Mô tả"><button class="btn primary small">Ghi nhận</button></form></section>`:''}</div>`;openDrawer(`${r.name} · Lô ${l.lot_no}`,'resources',html,{layout:'modal'});$('#lotUpdateForm')?.addEventListener('submit',async ev=>{ev.preventDefault();try{await api(`resources/lots/${l.id}`,{method:'PATCH',json:Object.fromEntries(new FormData(ev.currentTarget).entries())});toast('Đã cập nhật lô');closeDrawer();await renderResources()}catch(err){toast(err.message,'err')}});$('#inventoryTxnForm')?.addEventListener('submit',async ev=>{ev.preventDefault();try{await api(`resources/lots/${l.id}/transactions`,{method:'POST',json:Object.fromEntries(new FormData(ev.currentTarget).entries())});toast('Đã cập nhật tồn kho');closeDrawer();await renderResources()}catch(err){toast(err.message,'err')}});$('#reagentEventForm')?.addEventListener('submit',async ev=>{ev.preventDefault();try{await api(`resources/lots/${l.id}/events`,{method:'POST',json:Object.fromEntries(new FormData(ev.currentTarget).entries())});toast('Đã ghi nhận sự kiện');closeDrawer();await renderResources()}catch(err){toast(err.message,'err')}})}
function openReagentDetail(data,r){const lots=(r.lots||[]).map(l=>`<tr data-resource-lot="${l.id}"><td><strong>${esc(l.lot_no)}</strong></td><td>${fmtDate(l.received_date)}</td><td>${fmtDate(l.expiry_date)}</td><td>${resourceBadge(resourceAcceptanceLabels[l.acceptance_status]||l.acceptance_status,l.acceptance_status)}</td><td>${esc(l.qty_current)} ${esc(r.unit||'')}</td><td>${resourceBadge(reagentLotStatusLabels[l.status]||l.status,l.status)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Chưa có lô.</td></tr>';const html=`<div class="resource-detail"><div class="resource-profile"><div><span class="code">${esc(r.code)}</span><h3>${esc(r.name)}</h3><p>${esc(reagentTypeLabels[r.item_type]||r.item_type)} · ${esc(r.manufacturer||'—')} · ${esc(r.catalog_no||'')}</p></div><div class="resource-stock ${r.below_min?'low':''}"><strong>${esc(r.stock)} ${esc(r.unit||'')}</strong><span>Tồn hiện tại${r.min_stock>0?' · tối thiểu '+esc(r.min_stock):''}</span></div></div><div class="resource-info-grid"><div><small>Bảo quản</small><strong>${esc(r.storage_condition||'—')}</strong></div><div><small>Nhà cung cấp</small><strong>${esc(r.supplier||'—')}</strong></div><div><small>Số lô đang theo dõi</small><strong>${r.lots?.length||0}</strong></div><div><small>Trạng thái tồn</small><strong>${r.below_min?'Dưới mức tối thiểu':'Đủ mức theo dõi'}</strong></div></div>${data.canManage?`<div class="form-actions resource-top-actions"><button class="btn" id="editReagent">Sửa danh mục</button><button class="btn primary" id="newLot">＋ Tiếp nhận lô</button></div>`:''}<section><h4>Các lô</h4><div class="table-card"><table class="data-table"><thead><tr><th>LÔ</th><th>TIẾP NHẬN</th><th>HẠN DÙNG</th><th>NGHIỆM THU</th><th>TỒN</th><th>TRẠNG THÁI</th></tr></thead><tbody>${lots}</tbody></table></div></section></div>`;openDrawer(r.name,'resources',html,{layout:'modal'});$('#editReagent')?.addEventListener('click',()=>openReagentForm(data,r));$('#newLot')?.addEventListener('click',()=>openLotForm(data,r));$$('[data-resource-lot]').forEach(x=>x.onclick=()=>{const lot=(r.lots||[]).find(l=>l.id===+x.dataset.resourceLot);if(lot)openLotDetail(data,r,lot)})}

const mqMethodStatus={planned:'Chuẩn bị',verification:'Đang xác nhận',validation:'Đang thẩm định',active:'Đang áp dụng',suspended:'Tạm dừng',retired:'Ngừng sử dụng'};
const mqStudyType={verification:'Kiểm tra xác nhận',validation:'Xác nhận giá trị sử dụng',mu:'Độ không đảm bảo đo',method_comparison:'So sánh phương pháp'};
const mqConclusion={pending:'Chờ kết luận',pass:'Đạt',conditional:'Đạt có điều kiện',fail:'Không đạt'};
const mqIqcStatus={in_control:'Trong kiểm soát',warning:'Cảnh báo',out_of_control:'Ngoài kiểm soát'};
const mqEqaStatus={pending:'Chờ kết quả',acceptable:'Chấp nhận',questionable:'Cần xem xét',unacceptable:'Không chấp nhận'};
function mqBadge(label,status){return `<span class="mq-badge ${esc(status||'')}">${esc(label||'')}</span>`}
function mqMethodForm(data,m={}){const eq=(data.resources?.equipment||[]).map(x=>`<option value="${x.id}" ${+m.equipment_id===+x.id?'selected':''}>${esc(x.code)} · ${esc(x.name)}</option>`).join('');const rg=(data.resources?.reagents||[]).map(x=>`<option value="${x.id}" ${+m.reagent_id===+x.id?'selected':''}>${esc(x.code)} · ${esc(x.name)}</option>`).join('');return `<form id="mqMethodForm"><div class="form-grid"><div class="field"><label>Mã phương pháp *</label><input name="code" required value="${esc(m.code||'')}"></div><div class="field"><label>Tên phương pháp / xét nghiệm *</label><input name="name" required value="${esc(m.name||'')}"></div><div class="field"><label>Lĩnh vực</label><input name="discipline" value="${esc(m.discipline||'')}" placeholder="Sinh hóa, Huyết học, Vi sinh..."></div><div class="field"><label>Chất phân tích</label><input name="analyte" value="${esc(m.analyte||'')}"></div><div class="field"><label>Loại mẫu</label><input name="specimen" value="${esc(m.specimen||'')}"></div><div class="field"><label>Nguyên lý</label><input name="method_principle" value="${esc(m.method_principle||'')}"></div><div class="field"><label>Nguồn phương pháp</label><select name="method_origin"><option value="manufacturer" ${m.method_origin==='manufacturer'?'selected':''}>Theo nhà sản xuất / phương pháp công bố</option><option value="modified" ${m.method_origin==='modified'?'selected':''}>Đã sửa đổi</option><option value="in_house" ${m.method_origin==='in_house'?'selected':''}>Phát triển nội bộ</option></select></div><div class="field"><label>Trạng thái</label><select name="status">${Object.entries(mqMethodStatus).map(([k,v])=>`<option value="${k}" ${(m.status||'planned')===k?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div class="field"><label>Thiết bị</label><select name="equipment_id"><option value="">Chưa gắn</option>${eq}</select></div><div class="field"><label>Thuốc thử chính</label><select name="reagent_id"><option value="">Chưa gắn</option>${rg}</select></div><div class="field"><label>Rà soát lại</label><input type="date" name="next_review_date" value="${esc(m.next_review_date||'')}"></div><div class="field full"><label>Mục đích sử dụng</label><textarea name="intended_use">${esc(m.intended_use||'')}</textarea></div><div class="field full mq-check-grid"><label><input type="checkbox" name="verification_required" ${m.id?(m.verification_required?'checked':''):'checked'}> Cần xác nhận</label><label><input type="checkbox" name="validation_required" ${m.validation_required?'checked':''}> Cần thẩm định</label><label><input type="checkbox" name="mu_required" ${m.id?(m.mu_required?'checked':''):'checked'}> Cần đánh giá độ không đảm bảo đo</label><label><input type="checkbox" name="reference_interval_required" ${m.id?(m.reference_interval_required?'checked':''):'checked'}> Cần khoảng tham chiếu / giới hạn quyết định</label></div><div class="field full"><label>Ghi chú</label><textarea name="notes">${esc(m.notes||'')}</textarea></div></div><div class="form-actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">${m.id?'Lưu thay đổi':'Thêm phương pháp'}</button></div></form>`}
function openMqMethodForm(data,m={}){if(!data.canManage)return;openDrawer(m.id?'Cập nhật phương pháp':'Thêm phương pháp','methodquality',mqMethodForm(data,m),{layout:'modal'});const f=$('#mqMethodForm');$('[data-close]',f).onclick=closeDrawer;f.onsubmit=async e=>{e.preventDefault();const p=Object.fromEntries(new FormData(f).entries());for(const k of ['verification_required','validation_required','mu_required','reference_interval_required'])p[k]=!!f.elements[k].checked;try{if(m.id)await api(`method-quality/methods/${m.id}`,{method:'PATCH',json:p});else await api('method-quality/methods',{method:'POST',json:p});toast(m.id?'Đã cập nhật phương pháp':'Đã thêm phương pháp');closeDrawer();await renderMethodQuality()}catch(err){toast(err.message,'err')}}}
function mqStudyForm(m){return `<form id="mqStudyForm"><div class="form-grid"><div class="field"><label>Loại đánh giá</label><select name="study_type">${Object.entries(mqStudyType).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('')}</select></div><div class="field"><label>Thông số / nội dung</label><input name="parameter_name" placeholder="Độ lặp lại, độ chệch, độ không đảm bảo đo..."></div><div class="field"><label>Ngày thực hiện</label><input type="date" name="performed_at" value="${new Date().toISOString().slice(0,10)}"></div><div class="field"><label>Kết luận</label><select name="conclusion">${Object.entries(mqConclusion).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('')}</select></div><div class="field full"><label>Kế hoạch / cách thực hiện</label><textarea name="protocol_summary"></textarea></div><div class="field full"><label>Tiêu chí chấp nhận</label><textarea name="acceptance_criteria"></textarea></div><div class="field full"><label>Kết quả</label><textarea name="result_summary"></textarea></div><div class="field full"><label>Liên kết bằng chứng</label><input name="evidence_url"></div></div><div class="form-actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">Lưu đánh giá</button></div></form>`}
function openMqStudyForm(m){openDrawer(`Đánh giá phương pháp · ${m.code}`,'methodquality',mqStudyForm(m),{layout:'modal'});const f=$('#mqStudyForm');$('[data-close]',f).onclick=closeDrawer;f.onsubmit=async e=>{e.preventDefault();try{await api(`method-quality/methods/${m.id}/studies`,{method:'POST',json:Object.fromEntries(new FormData(f).entries())});toast('Đã lưu đánh giá phương pháp');closeDrawer();await renderMethodQuality()}catch(err){toast(err.message,'err')}}}
function mqReferenceForm(m){return `<form id="mqReferenceForm"><div class="form-grid"><div class="field"><label>Quần thể áp dụng</label><input name="population_label" required placeholder="Người trưởng thành"></div><div class="field"><label>Giới</label><select name="sex"><option value="all">Tất cả</option><option value="female">Nữ</option><option value="male">Nam</option></select></div><div class="field"><label>Tuổi từ</label><input type="number" step="0.1" name="age_from"></div><div class="field"><label>Tuổi đến</label><input type="number" step="0.1" name="age_to"></div><div class="field"><label>Cận dưới</label><input name="lower_limit"></div><div class="field"><label>Cận trên</label><input name="upper_limit"></div><div class="field"><label>Đơn vị</label><input name="unit"></div><div class="field"><label>Trạng thái xác minh</label><select name="verification_status"><option value="pending">Chờ xác minh</option><option value="accepted">Đã chấp nhận</option><option value="rejected">Không chấp nhận</option></select></div><div class="field full"><label>Giới hạn quyết định lâm sàng (nếu có)</label><textarea name="decision_limit"></textarea></div><div class="field full"><label>Tài liệu tham khảo</label><textarea name="source_reference"></textarea></div><div class="field full"><label>Ghi chú</label><textarea name="notes"></textarea></div></div><div class="form-actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">Lưu khoảng tham chiếu</button></div></form>`}
function openMqReferenceForm(m){openDrawer(`Khoảng tham chiếu · ${m.code}`,'methodquality',mqReferenceForm(m),{layout:'modal'});const f=$('#mqReferenceForm');$('[data-close]',f).onclick=closeDrawer;f.onsubmit=async e=>{e.preventDefault();try{await api(`method-quality/methods/${m.id}/reference-intervals`,{method:'POST',json:Object.fromEntries(new FormData(f).entries())});toast('Đã lưu khoảng tham chiếu');closeDrawer();await renderMethodQuality()}catch(err){toast(err.message,'err')}}}
function mqIqcPlanForm(m){return `<form id="mqIqcPlanForm"><div class="form-grid"><div class="field"><label>Tên kế hoạch nội kiểm *</label><input name="name" required placeholder="Nội kiểm mức 1"></div><div class="field"><label>Vật liệu kiểm soát</label><input name="material_name"></div><div class="field"><label>Lô</label><input name="lot_no"></div><div class="field"><label>Mức</label><input name="level_name" placeholder="Mức 1 / Mức 2"></div><div class="field"><label>Giá trị trung bình mục tiêu</label><input type="number" step="any" name="target_mean"></div><div class="field"><label>Độ lệch chuẩn mục tiêu</label><input type="number" step="any" name="target_sd"></div><div class="field"><label>Đơn vị</label><input name="unit"></div><div class="field"><label>Tần suất</label><input name="frequency_text" placeholder="Mỗi ca / mỗi ngày / theo rủi ro..."></div><div class="field full"><label>Quy tắc kiểm soát áp dụng</label><input name="control_rules" placeholder="Ghi theo quy trình nội kiểm đã phê duyệt"></div><div class="field"><label>Hiệu lực từ</label><input type="date" name="valid_from"></div><div class="field"><label>Hiệu lực đến</label><input type="date" name="valid_until"></div></div><div class="form-actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">Tạo kế hoạch nội kiểm</button></div></form>`}
function openMqIqcPlanForm(m){openDrawer(`Kế hoạch nội kiểm · ${m.code}`,'methodquality',mqIqcPlanForm(m),{layout:'modal'});const f=$('#mqIqcPlanForm');$('[data-close]',f).onclick=closeDrawer;f.onsubmit=async e=>{e.preventDefault();try{await api(`method-quality/methods/${m.id}/iqc-plans`,{method:'POST',json:Object.fromEntries(new FormData(f).entries())});toast('Đã tạo kế hoạch nội kiểm');closeDrawer();await renderMethodQuality()}catch(err){toast(err.message,'err')}}}
function mqIqcRunForm(plan){return `<form id="mqIqcRunForm"><div class="form-grid"><div class="field"><label>Thời điểm</label><input type="datetime-local" name="run_at" value="${new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16)}"></div><div class="field"><label>Kết quả kiểm soát</label><input type="number" step="any" name="numeric_value" required></div><div class="field"><label>Đánh giá theo quy tắc đã phê duyệt</label><select name="status"><option value="in_control">Trong kiểm soát</option><option value="warning">Cảnh báo</option><option value="out_of_control">Ngoài kiểm soát</option></select></div><div class="field"><label>Quy tắc / dấu hiệu</label><input name="rule_flags" placeholder="Ví dụ: quy tắc theo quy trình nội kiểm"></div><div class="field full"><label>Hành động ngay (nếu có)</label><textarea name="action_taken"></textarea></div></div><div class="mq-info neutral"><strong>Trung bình ${esc(plan.target_mean??'—')} · Độ lệch chuẩn ${esc(plan.target_sd??'—')} ${esc(plan.unit||'')}</strong><span>${esc(plan.control_rules||'Áp dụng quy tắc kiểm soát theo quy trình nội kiểm hiện hành.')}</span></div><div class="form-actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">Lưu kết quả nội kiểm</button></div></form>`}
function openMqIqcRunForm(plan){openDrawer(`Ghi nội kiểm · ${plan.name}`,'methodquality',mqIqcRunForm(plan),{layout:'modal'});const f=$('#mqIqcRunForm');$('[data-close]',f).onclick=closeDrawer;f.onsubmit=async e=>{e.preventDefault();try{await api(`method-quality/iqc-plans/${plan.id}/runs`,{method:'POST',json:Object.fromEntries(new FormData(f).entries())});toast('Đã lưu kết quả nội kiểm');closeDrawer();await renderMethodQuality()}catch(err){toast(err.message,'err')}}}
function mqEqaProgramForm(m){return `<form id="mqEqaProgramForm"><div class="form-grid"><div class="field"><label>Đơn vị ngoại kiểm *</label><input name="provider" required></div><div class="field"><label>Chương trình *</label><input name="program_name" required></div><div class="field"><label>Chất phân tích</label><input name="analyte" value="${esc(m.analyte||'')}"></div><div class="field"><label>Chu kỳ</label><input name="cycle_frequency" placeholder="Hàng tháng / quý..."></div><div class="field full"><label>Ghi chú</label><textarea name="notes"></textarea></div></div><div class="form-actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">Thêm chương trình</button></div></form>`}
function openMqEqaProgramForm(m){openDrawer(`Chương trình ngoại kiểm · ${m.code}`,'methodquality',mqEqaProgramForm(m),{layout:'modal'});const f=$('#mqEqaProgramForm');$('[data-close]',f).onclick=closeDrawer;f.onsubmit=async e=>{e.preventDefault();try{await api(`method-quality/methods/${m.id}/eqa-programs`,{method:'POST',json:Object.fromEntries(new FormData(f).entries())});toast('Đã thêm chương trình ngoại kiểm');closeDrawer();await renderMethodQuality()}catch(err){toast(err.message,'err')}}}
function mqEqaEventForm(program){return `<form id="mqEqaEventForm"><div class="form-grid"><div class="field"><label>Mã đợt</label><input name="event_code"></div><div class="field"><label>Ngày</label><input type="date" name="event_date" value="${new Date().toISOString().slice(0,10)}"></div><div class="field"><label>Giá trị ấn định</label><input type="number" step="any" name="assigned_value"></div><div class="field"><label>Kết quả báo cáo</label><input type="number" step="any" name="reported_value"></div><div class="field"><label>Đơn vị</label><input name="unit"></div><div class="field"><label>Điểm z (nếu có)</label><input type="number" step="any" name="z_score"></div><div class="field"><label>Đánh giá</label><select name="status">${Object.entries(mqEqaStatus).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('')}</select></div><div class="field"><label>Điểm / nhận xét của chương trình</label><input name="score_text"></div><div class="field full"><label>Điều tra</label><textarea name="investigation"></textarea></div><div class="field full"><label>Hành động</label><textarea name="corrective_action"></textarea></div><div class="field full"><label>Liên kết bằng chứng</label><input name="evidence_url"></div></div><div class="form-actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">Lưu kết quả ngoại kiểm</button></div></form>`}
function openMqEqaEventForm(program){openDrawer(`Kết quả ngoại kiểm · ${program.program_name}`,'methodquality',mqEqaEventForm(program),{layout:'modal'});const f=$('#mqEqaEventForm');$('[data-close]',f).onclick=closeDrawer;f.onsubmit=async e=>{e.preventDefault();try{await api(`method-quality/eqa-programs/${program.id}/events`,{method:'POST',json:Object.fromEntries(new FormData(f).entries())});toast('Đã lưu kết quả ngoại kiểm');closeDrawer();await renderMethodQuality()}catch(err){toast(err.message,'err')}}}
function iqcChartSvg(plan){const runs=(plan.runs||[]).filter(x=>x.z_score!==null&&x.z_score!==''&&Number.isFinite(+x.z_score)).slice(0,24).reverse();if(!runs.length)return '<div class="mq-empty-chart">Chưa có dữ liệu đủ để vẽ biểu đồ.</div>';const W=760,H=230,pad=36;const y=z=>pad+(3.5-Math.max(-3.5,Math.min(3.5,+z)))*(H-2*pad)/7;const x=i=>pad+(runs.length===1?0:(i*(W-2*pad)/(runs.length-1)));const lines=[3,2,1,0,-1,-2,-3].map(z=>`<line x1="${pad}" x2="${W-pad}" y1="${y(z)}" y2="${y(z)}" class="mq-lj-line z${Math.abs(z)}"/><text x="6" y="${y(z)+4}" class="mq-lj-label">${z>0?'+':''}${z} độ lệch chuẩn</text>`).join('');const pts=runs.map((r,i)=>`<circle cx="${x(i)}" cy="${y(+r.z_score)}" r="5" class="mq-lj-point ${esc(r.status)}"><title>${esc(r.run_at)} · z=${esc(r.z_score)}</title></circle>`).join('');const path=runs.map((r,i)=>(i?'L':'M')+x(i)+','+y(+r.z_score)).join(' ');return `<svg class="mq-lj" viewBox="0 0 ${W} ${H}" role="img" aria-label="Biểu đồ nội kiểm theo điểm z">${lines}<path d="${path}" class="mq-lj-path"/>${pts}</svg>`}
function mqMethodDetail(data,m){const studies=(m.studies||[]).map(s=>`<tr><td>${esc(mqStudyType[s.study_type]||s.study_type)}</td><td>${esc(s.parameter_name||'—')}</td><td>${fmtDate(s.performed_at)}</td><td>${mqBadge(mqConclusion[s.conclusion]||s.conclusion,s.conclusion)}</td><td>${esc(s.acceptance_criteria||'—')}</td></tr>`).join('');const refs=(m.reference_intervals||[]).map(r=>`<tr><td>${esc(r.population_label)}</td><td>${esc([r.lower_limit,r.upper_limit].filter(Boolean).join(' – ')||r.decision_limit||'—')} ${esc(r.unit||'')}</td><td>${mqBadge(r.verification_status==='accepted'?'Đã chấp nhận':r.verification_status==='rejected'?'Không chấp nhận':'Chờ xác minh',r.verification_status)}</td><td>${esc(r.source_reference||'—')}</td></tr>`).join('');const plans=(m.iqc_plans||[]).map(p=>`<article class="mq-iqc-plan"><div class="mq-plan-head"><div><strong>${esc(p.name)}</strong><small>${esc(p.level_name||'')} ${p.lot_no?'· Lô '+esc(p.lot_no):''}</small></div>${data.canRecord?`<button class="btn primary small" data-mq-iqc-run="${p.id}">＋ Ghi nội kiểm</button>`:''}</div>${iqcChartSvg(p)}<div class="mq-plan-meta"><span>Trung bình <b>${esc(p.target_mean??'—')}</b></span><span>Độ lệch chuẩn <b>${esc(p.target_sd??'—')}</b></span><span>${esc(p.frequency_text||'Chưa ghi tần suất')}</span><span>${esc(p.control_rules||'Chưa ghi quy tắc')}</span></div></article>`).join('')||'<div class="note">Chưa có kế hoạch nội kiểm.</div>';const eqa=(m.eqa_programs||[]).map(p=>`<article class="mq-eqa-card"><div><strong>${esc(p.provider)} · ${esc(p.program_name)}</strong><small>${esc(p.cycle_frequency||'')}</small></div>${data.canManage?`<button class="btn small" data-mq-eqa-event="${p.id}">Ghi kết quả</button>`:''}<div class="mq-eqa-events">${(p.events||[]).slice(0,5).map(e=>`<span>${fmtDate(e.event_date)} · ${mqBadge(mqEqaStatus[e.status]||e.status,e.status)} ${e.z_score!==null&&e.z_score!==''?'· z='+esc(e.z_score):''}</span>`).join('')||'<span>Chưa có kết quả.</span>'}</div></article>`).join('')||'<div class="note">Chưa có chương trình ngoại kiểm.</div>';const devs=(m.deviations||[]).map(d=>`<article class="mq-deviation ${esc(d.severity)}"><div><strong>${esc(d.description)}</strong><small>${fmtDate(d.detected_at)} · ${esc(d.source_type)}</small></div><div>${mqBadge(d.status==='resolved'?'Đã đóng':'Đang xử lý',d.status)}${d.patient_results_held?' '+mqBadge('Đang giữ kết quả','out_of_control'):''}</div>${d.impact_review?`<p><b>Đánh giá ảnh hưởng:</b> ${esc(d.impact_review)}</p>`:''}${d.linked_nc_record_id?`<button class="btn small" data-record="${d.linked_nc_record_id}">Mở hồ sơ không phù hợp</button>`:(data.canManage?`<button class="btn small" data-mq-create-nc="${d.id}">Tạo hồ sơ không phù hợp</button>`:'')}</article>`).join('')||'<div class="note">Chưa có sai lệch chất lượng.</div>';const html=`<div class="mq-method-profile"><div><span class="code">${esc(m.code)}</span><h3>${esc(m.name)}</h3><p>${esc([m.discipline,m.analyte,m.specimen].filter(Boolean).join(' · '))}</p></div><div>${mqBadge(mqMethodStatus[m.status]||m.status,m.status)}</div></div><div class="mq-info-grid"><div><small>Thiết bị</small><strong>${esc(m.equipment_name||'—')}</strong></div><div><small>Thuốc thử chính</small><strong>${esc(m.reagent_name||'—')}</strong></div><div><small>Nguồn phương pháp</small><strong>${esc(m.method_origin||'—')}</strong></div><div><small>Rà soát lại</small><strong>${fmtDate(m.next_review_date)}</strong></div></div>${data.canManage?`<div class="form-actions mq-method-actions"><button class="btn" id="mqEditMethod">Sửa hồ sơ</button><button class="btn" id="mqAddStudy">＋ Xác nhận / thẩm định / độ không đảm bảo đo</button><button class="btn" id="mqAddReference">＋ Khoảng tham chiếu</button><button class="btn" id="mqAddIqcPlan">＋ Kế hoạch nội kiểm</button><button class="btn" id="mqAddEqa">＋ Chương trình ngoại kiểm</button></div>`:''}<section><h4>Xác nhận, thẩm định, độ không đảm bảo đo & so sánh phương pháp</h4><div class="table-card"><table class="data-table"><thead><tr><th>LOẠI</th><th>THÔNG SỐ</th><th>NGÀY</th><th>KẾT LUẬN</th><th>TIÊU CHÍ CHẤP NHẬN</th></tr></thead><tbody>${studies||'<tr><td colspan="5" class="empty">Chưa có đánh giá.</td></tr>'}</tbody></table></div></section><section><h4>Khoảng tham chiếu & giới hạn quyết định</h4><div class="table-card"><table class="data-table"><thead><tr><th>QUẦN THỂ</th><th>GIÁ TRỊ</th><th>TRẠNG THÁI</th><th>NGUỒN</th></tr></thead><tbody>${refs||'<tr><td colspan="4" class="empty">Chưa có hồ sơ.</td></tr>'}</tbody></table></div></section><section><h4>Nội kiểm</h4><div class="mq-iqc-list">${plans}</div></section><section><h4>Ngoại kiểm</h4><div class="mq-eqa-list">${eqa}</div></section><section><h4>Sai lệch chất lượng</h4><div class="mq-deviation-list">${devs}</div></section>`;openDrawer(`${m.code} · ${m.name}`,'methodquality',html,{layout:'modal'});$('#mqEditMethod')?.addEventListener('click',()=>openMqMethodForm(data,m));$('#mqAddStudy')?.addEventListener('click',()=>openMqStudyForm(m));$('#mqAddReference')?.addEventListener('click',()=>openMqReferenceForm(m));$('#mqAddIqcPlan')?.addEventListener('click',()=>openMqIqcPlanForm(m));$('#mqAddEqa')?.addEventListener('click',()=>openMqEqaProgramForm(m));$$('[data-mq-iqc-run]').forEach(b=>{const p=m.iqc_plans.find(x=>+x.id===+b.dataset.mqIqcRun);b.onclick=()=>p&&openMqIqcRunForm(p)});$$('[data-mq-eqa-event]').forEach(b=>{const p=m.eqa_programs.find(x=>+x.id===+b.dataset.mqEqaEvent);b.onclick=()=>p&&openMqEqaEventForm(p)});$$('[data-mq-create-nc]').forEach(b=>b.onclick=async()=>{try{await api(`method-quality/deviations/${b.dataset.mqCreateNc}/create-nc`,{method:'POST'});toast('Đã tạo hồ sơ sự không phù hợp');closeDrawer();await renderMethodQuality()}catch(err){toast(err.message,'err')}});$$('[data-record]').forEach(b=>b.onclick=()=>openRecord(+b.dataset.record))}
async function renderMethodQuality(){const data=await api('method-quality/overview'),s=data.summary||{};state.mqTab=state.mqTab||'methods';const tabs=[['methods','Phương pháp'],['studies','Xác nhận & thẩm định'],['iqc','Nội kiểm'],['eqa','Ngoại kiểm'],['deviations','Sai lệch']];const tabHtml=tabs.map(([k,v])=>`<button class="tab ${state.mqTab===k?'active':''}" data-mq-tab="${k}">${esc(v)}</button>`).join('');let body='';if(state.mqTab==='methods'){body=`<section class="card panel"><div class="panel-head"><div><h3>Danh mục phương pháp xét nghiệm</h3><div class="panel-sub">Liên kết phương pháp với thiết bị, thuốc thử, quy trình kỹ thuật và hồ sơ chất lượng.</div></div>${data.canManage?'<button class="btn primary small" id="mqNewMethod">＋ Thêm phương pháp</button>':''}</div><div class="table-card"><table class="data-table"><thead><tr><th>MÃ</th><th>PHƯƠNG PHÁP</th><th>LĨNH VỰC</th><th>THIẾT BỊ</th><th>TRẠNG THÁI</th><th>XÁC NHẬN</th><th>ĐỘ KHÔNG ĐẢM BẢO ĐO</th><th>NỘI KIỂM</th></tr></thead><tbody>${(data.methods||[]).map(m=>{const v=(m.studies||[]).some(x=>x.study_type==='verification'&&x.conclusion==='pass');const mu=(m.studies||[]).some(x=>x.study_type==='mu'&&x.conclusion==='pass');return `<tr data-mq-method="${m.id}"><td><span class="code">${esc(m.code)}</span></td><td><strong>${esc(m.name)}</strong><div class="meta">${esc([m.analyte,m.specimen].filter(Boolean).join(' · '))}</div></td><td>${esc(m.discipline||'—')}</td><td>${esc(m.equipment_name||'—')}</td><td>${mqBadge(mqMethodStatus[m.status]||m.status,m.status)}</td><td>${m.verification_required?mqBadge(v?'Đạt':'Chưa đạt',v?'pass':'pending'):mqBadge('Không yêu cầu','neutral')}</td><td>${m.mu_required?mqBadge(mu?'Đã có':'Chưa có',mu?'pass':'pending'):mqBadge('Không yêu cầu','neutral')}</td><td>${(m.iqc_plans||[]).length}</td></tr>`}).join('')||'<tr><td colspan="8" class="empty">Chưa có phương pháp.</td></tr>'}</tbody></table></div></section>`}else if(state.mqTab==='studies'){const rows=[];(data.methods||[]).forEach(m=>(m.studies||[]).forEach(x=>rows.push({m,x})));body=`<section class="card panel"><div class="panel-head"><div><h3>Xác nhận, thẩm định, độ không đảm bảo đo & khoảng tham chiếu</h3><div class="panel-sub">Theo dõi tiêu chí chấp nhận, kết quả và kết luận theo từng phương pháp.</div></div></div><div class="mq-study-grid">${rows.map(({m,x})=>`<button class="mq-study-card ${esc(x.conclusion)}" data-mq-method="${m.id}"><span>${esc(m.code)}</span><strong>${esc(mqStudyType[x.study_type]||x.study_type)} · ${esc(x.parameter_name||m.name)}</strong><small>${fmtDate(x.performed_at)}</small>${mqBadge(mqConclusion[x.conclusion]||x.conclusion,x.conclusion)}</button>`).join('')||'<div class="card empty">Chưa có đánh giá phương pháp.</div>'}</div></section>`}else if(state.mqTab==='iqc'){const plans=[];(data.methods||[]).forEach(m=>(m.iqc_plans||[]).forEach(p=>plans.push({m,p})));body=`<section class="mq-iqc-board">${plans.map(({m,p})=>`<article class="card mq-iqc-board-card"><div class="mq-plan-head"><div><span class="code">${esc(m.code)}</span><strong>${esc(m.name)} · ${esc(p.name)}</strong><small>${esc(p.level_name||'')} ${p.lot_no?'· Lô '+esc(p.lot_no):''}</small></div>${data.canRecord?`<button class="btn primary small" data-mq-iqc-run="${p.id}" data-mq-mid="${m.id}">＋ Ghi nội kiểm</button>`:''}</div>${iqcChartSvg(p)}<div class="mq-plan-meta"><span>Trung bình <b>${esc(p.target_mean??'—')}</b></span><span>Độ lệch chuẩn <b>${esc(p.target_sd??'—')}</b></span><span>${esc(p.control_rules||'Quy tắc theo quy trình')}</span></div></article>`).join('')||'<div class="card empty">Chưa có kế hoạch nội kiểm.</div>'}</section>`}else if(state.mqTab==='eqa'){const rows=[];(data.methods||[]).forEach(m=>(m.eqa_programs||[]).forEach(p=>rows.push({m,p})));body=`<section class="mq-eqa-board">${rows.map(({m,p})=>`<article class="card mq-eqa-card"><div><span class="code">${esc(m.code)}</span><strong>${esc(p.provider)} · ${esc(p.program_name)}</strong><small>${esc(m.name)} · ${esc(p.cycle_frequency||'')}</small></div>${data.canManage?`<button class="btn small" data-mq-eqa-event="${p.id}" data-mq-mid="${m.id}">Ghi kết quả</button>`:''}<div class="mq-eqa-events">${(p.events||[]).slice(0,6).map(e=>`<span>${fmtDate(e.event_date)} · ${mqBadge(mqEqaStatus[e.status]||e.status,e.status)} ${e.z_score!==null&&e.z_score!==''?'· z='+esc(e.z_score):''}</span>`).join('')||'<span>Chưa có kết quả.</span>'}</div></article>`).join('')||'<div class="card empty">Chưa có chương trình ngoại kiểm.</div>'}</section>`}else{const rows=[];(data.methods||[]).forEach(m=>(m.deviations||[]).forEach(d=>rows.push({m,d})));body=`<section class="card panel"><div class="panel-head"><div><h3>Sai lệch chất lượng</h3><div class="panel-sub">Nội kiểm/ngoại kiểm/phương pháp không đạt, đánh giá ảnh hưởng và liên kết hồ sơ sự không phù hợp.</div></div></div><div class="mq-deviation-list">${rows.map(({m,d})=>`<article class="mq-deviation ${esc(d.severity)}"><div><span class="code">${esc(m.code)}</span><strong>${esc(d.description)}</strong><small>${fmtDate(d.detected_at)} · ${esc(m.name)}</small></div><div>${mqBadge(d.status==='resolved'?'Đã đóng':'Đang xử lý',d.status)}${d.patient_results_held?' '+mqBadge('Giữ kết quả','out_of_control'):''}</div>${d.linked_nc_record_id?`<button class="btn small" data-record="${d.linked_nc_record_id}">Mở hồ sơ</button>`:(data.canManage?`<button class="btn small" data-mq-create-nc="${d.id}">Tạo hồ sơ</button>`:'')}</article>`).join('')||'<div class="note">Chưa có sai lệch.</div>'}</div></section>`}$('#content').innerHTML=`<section class="card module-hero mq-hero"><div><span class="eyebrow">ISO 15189 · 7.3</span><h2>Chất lượng phương pháp xét nghiệm</h2><p>Quản lý kiểm tra xác nhận, xác nhận giá trị sử dụng, độ không đảm bảo đo, khoảng tham chiếu, kiểm soát chất lượng và xử lý sai lệch.</p></div></section><section class="mq-kpis"><div class="card"><small>Phương pháp</small><strong>${s.methods||0}</strong><span>${s.activeMethods||0} đang áp dụng</span></div><div class="card warning"><small>Kiểm tra xác nhận còn thiếu</small><strong>${s.verificationPending||0}</strong><span>Cần hoàn thiện</span></div><div class="card warning"><small>Độ không đảm bảo đo còn thiếu</small><strong>${s.muPending||0}</strong><span>Cần đánh giá</span></div><div class="card danger"><small>Kiểm soát nội bộ ngoài giới hạn</small><strong>${s.iqcOut||0}</strong><span>Chưa xử lý xong</span></div><div class="card danger"><small>Đánh giá bên ngoài không chấp nhận</small><strong>${s.eqaUnacceptable||0}</strong><span>Cần điều tra</span></div><div class="card warning"><small>Sai lệch mở</small><strong>${s.openDeviations||0}</strong><span>Cần theo dõi</span></div></section>${data.canManage?'<div class="resource-import-tools"><button class="btn small" id="nahImportMethodQuality">Nhập danh mục từ Excel</button></div>':''}<div class="tabs mq-tabs">${tabHtml}</div>${body}`;$$('[data-mq-tab]').forEach(b=>b.onclick=()=>{state.mqTab=b.dataset.mqTab;renderMethodQuality()});$('#mqNewMethod')?.addEventListener('click',()=>openMqMethodForm(data));$('#nahImportMethodQuality')?.addEventListener('click',()=>openBulkImport('methods'));$$('[data-mq-method]').forEach(b=>{const m=(data.methods||[]).find(x=>+x.id===+b.dataset.mqMethod);b.onclick=()=>m&&mqMethodDetail(data,m)});$$('[data-mq-iqc-run]').forEach(b=>{const m=(data.methods||[]).find(x=>+x.id===+b.dataset.mqMid);const p=m?.iqc_plans?.find(x=>+x.id===+b.dataset.mqIqcRun);b.onclick=()=>p&&openMqIqcRunForm(p)});$$('[data-mq-eqa-event]').forEach(b=>{const m=(data.methods||[]).find(x=>+x.id===+b.dataset.mqMid);const p=m?.eqa_programs?.find(x=>+x.id===+b.dataset.mqEqaEvent);b.onclick=()=>p&&openMqEqaEventForm(p)});$$('[data-mq-create-nc]').forEach(b=>b.onclick=async()=>{try{await api(`method-quality/deviations/${b.dataset.mqCreateNc}/create-nc`,{method:'POST'});toast('Đã tạo hồ sơ sự không phù hợp');await renderMethodQuality()}catch(err){toast(err.message,'err')}});$$('[data-record]').forEach(b=>b.onclick=()=>openRecord(+b.dataset.record))}
async function renderResources(){const data=await api('resources/overview'),s=data.summary||{};state.resourceTab=state.resourceTab||'equipment';const tabs=[['equipment','Thiết bị'],['due','Hiệu chuẩn & bảo trì'],['inventory','Hóa chất & vật tư'],['lots','Lô & tồn kho'],['operators','Nhân sự được ủy quyền']];const tabHtml=tabs.map(([k,v])=>`<button class="tab ${state.resourceTab===k?'active':''}" data-resource-tab="${k}">${esc(v)}</button>`).join('');let body='';if(state.resourceTab==='equipment'){body=`<section class="card panel"><div class="panel-head"><div><h3>Danh mục thiết bị</h3><div class="panel-sub">Hồ sơ vòng đời từ tiếp nhận, nghiệm thu, sử dụng, hiệu chuẩn, bảo trì đến ngừng khai thác.</div></div>${data.canManage?'<button class="btn small" id="nahImportEquipment">Nhập từ Excel</button><button class="btn primary small" id="newEquipment">＋ Thêm thiết bị</button>':''}</div><div class="table-card"><table class="data-table"><thead><tr><th>MÃ</th><th>THIẾT BỊ</th><th>VỊ TRÍ</th><th>TRẠNG THÁI</th><th>HIỆU CHUẨN</th><th>BẢO TRÌ</th><th>NHÂN SỰ</th></tr></thead><tbody>${(data.equipment||[]).map(e=>`<tr data-resource-equipment="${e.id}"><td><span class="code">${esc(e.code)}</span></td><td><strong>${esc(e.name)}</strong><div class="meta">${esc([e.manufacturer,e.model,e.serial_number].filter(Boolean).join(' · '))}</div></td><td>${esc(e.location||'—')}</td><td>${resourceBadge(resourceEquipmentStatusLabels[e.status]||e.status,e.status)}</td><td>${fmtDate(e.next_calibration_date)}</td><td>${fmtDate(e.next_maintenance_date)}</td><td>${e.operators?.length||0}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">Chưa có thiết bị.</td></tr>'}</tbody></table></div></section>`}else if(state.resourceTab==='due'){const due=(data.equipment||[]).filter(e=>e.next_calibration_date||e.next_maintenance_date||['out_of_service','quarantine'].includes(e.status)).sort((a,b)=>String(a.next_calibration_date||a.next_maintenance_date||'9999').localeCompare(String(b.next_calibration_date||b.next_maintenance_date||'9999')));body=`<section class="resource-alert-grid">${due.map(e=>`<button class="card resource-alert-card ${['out_of_service','quarantine'].includes(e.status)?'danger':''}" data-resource-equipment="${e.id}"><span class="code">${esc(e.code)}</span><strong>${esc(e.name)}</strong><small>Hiệu chuẩn: ${fmtDate(e.next_calibration_date)} · Bảo trì: ${fmtDate(e.next_maintenance_date)}</small><em>${esc(resourceEquipmentStatusLabels[e.status]||e.status)}</em></button>`).join('')||'<div class="card empty">Chưa có mốc cần theo dõi.</div>'}</section>`}else if(state.resourceTab==='inventory'){body=`<section class="card panel"><div class="panel-head"><div><h3>Danh mục hóa chất & vật tư</h3><div class="panel-sub">Theo dõi lô, hạn dùng, điều kiện bảo quản và mức tồn tối thiểu.</div></div>${data.canManage?'<button class="btn primary small" id="newReagent">＋ Thêm danh mục</button>':''}</div><div class="table-card"><table class="data-table"><thead><tr><th>MÃ</th><th>TÊN</th><th>NHÓM</th><th>BẢO QUẢN</th><th>TỒN</th><th>MỨC TỐI THIỂU</th><th>CẢNH BÁO</th></tr></thead><tbody>${(data.reagents||[]).map(r=>`<tr data-resource-reagent="${r.id}"><td><span class="code">${esc(r.code)}</span></td><td><strong>${esc(r.name)}</strong><div class="meta">${esc(r.manufacturer||'')} ${r.catalog_no?'· '+esc(r.catalog_no):''}</div></td><td>${esc(reagentTypeLabels[r.item_type]||r.item_type)}</td><td>${esc(r.storage_condition||'—')}</td><td><strong>${esc(r.stock)} ${esc(r.unit||'')}</strong></td><td>${esc(r.min_stock)} ${esc(r.unit||'')}</td><td>${r.below_min?resourceBadge('Tồn thấp','warning'):resourceBadge('Đủ','accepted')}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">Chưa có danh mục hóa chất/vật tư.</td></tr>'}</tbody></table></div></section>`}else if(state.resourceTab==='lots'){const rows=[];(data.reagents||[]).forEach(r=>(r.lots||[]).forEach(l=>rows.push({r,l})));rows.sort((a,b)=>String(a.l.expiry_date||'9999').localeCompare(String(b.l.expiry_date||'9999')));body=`<section class="card panel"><div class="panel-head"><div><h3>Lô & tồn kho</h3><div class="panel-sub">Ưu tiên lô gần hết hạn, chưa nghiệm thu, bị cách ly hoặc thu hồi.</div></div></div><div class="table-card"><table class="data-table"><thead><tr><th>TÊN</th><th>LÔ</th><th>HẠN DÙNG</th><th>NGHIỆM THU</th><th>TỒN</th><th>TRẠNG THÁI</th></tr></thead><tbody>${rows.map(x=>`<tr data-resource-lot-global="${x.r.id}|${x.l.id}"><td><strong>${esc(x.r.name)}</strong></td><td>${esc(x.l.lot_no)}</td><td>${fmtDate(x.l.expiry_date)}</td><td>${resourceBadge(resourceAcceptanceLabels[x.l.acceptance_status]||x.l.acceptance_status,x.l.acceptance_status)}</td><td>${esc(x.l.qty_current)} ${esc(x.r.unit||'')}</td><td>${resourceBadge(reagentLotStatusLabels[x.l.status]||x.l.status,x.l.status)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Chưa có lô.</td></tr>'}</tbody></table></div></section>`}else{const rows=[];(data.equipment||[]).forEach(e=>(e.operators||[]).forEach(o=>rows.push({e,o})));body=`<section class="card panel"><div class="panel-head"><div><h3>Nhân sự được ủy quyền theo thiết bị</h3><div class="panel-sub">Chỉ hiển thị các liên kết được tạo từ ủy quyền năng lực thiết bị còn hiệu lực.</div></div><button class="btn small" data-go="competency">Mở ma trận năng lực</button></div><div class="table-card"><table class="data-table"><thead><tr><th>NHÂN SỰ</th><th>THIẾT BỊ</th><th>VAI TRÒ</th><th>HIỆU LỰC ĐẾN</th><th>TRẠNG THÁI</th></tr></thead><tbody>${rows.map(x=>`<tr data-resource-equipment="${x.e.id}"><td><strong>${esc(x.o.name)}</strong></td><td>${esc(x.e.code)} · ${esc(x.e.name)}</td><td>${x.o.operator_role==='supervisor'?'Giám sát':'Vận hành'}</td><td>${fmtDate(x.o.valid_until)}</td><td>${resourceBadge(x.o.status==='active'?'Đang hiệu lực':'Không hiệu lực',x.o.status)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Chưa gắn ủy quyền với thiết bị.</td></tr>'}</tbody></table></div></section>`}$('#content').innerHTML=`<section class="card module-hero resource-hero"><div><span class="eyebrow">ISO 15189 · NGUỒN LỰC</span><h2>Thiết bị, hóa chất & vật tư</h2><p>Quản lý vòng đời thiết bị, hiệu chuẩn, bảo trì, nhân sự được ủy quyền, lô thuốc thử và tồn kho.</p></div></section><section class="resource-kpis"><div class="card"><small>Thiết bị</small><strong>${s.equipment||0}</strong><span>Đang quản lý</span></div><div class="card warning"><small>Hiệu chuẩn ≤30 ngày</small><strong>${s.calDue||0}</strong><span>Cần theo dõi</span></div><div class="card warning"><small>Bảo trì ≤30 ngày</small><strong>${s.maintDue||0}</strong><span>Cần theo dõi</span></div><div class="card danger"><small>Ngừng / cách ly</small><strong>${s.out||0}</strong><span>Không vận hành</span></div><div class="card warning"><small>Lô sắp hết hạn</small><strong>${s.expiring||0}</strong><span>Trong 30 ngày</span></div><div class="card danger"><small>Tồn dưới mức tối thiểu</small><strong>${s.below||0}</strong><span>Cần bổ sung</span></div></section><div class="resource-tabs tabs">${tabHtml}</div>${body}`;$$('[data-resource-tab]').forEach(b=>b.onclick=()=>{state.resourceTab=b.dataset.resourceTab;renderResources()});$('#newEquipment')?.addEventListener('click',()=>openEquipmentForm(data));$('#nahImportEquipment')?.addEventListener('click',()=>openBulkImport('equipment'));$('#newReagent')?.addEventListener('click',()=>openReagentForm(data));$$('[data-resource-equipment]').forEach(x=>x.onclick=()=>{const e=(data.equipment||[]).find(v=>v.id===+x.dataset.resourceEquipment);if(e)openEquipmentDetail(data,e)});$$('[data-resource-reagent]').forEach(x=>x.onclick=()=>{const r=(data.reagents||[]).find(v=>v.id===+x.dataset.resourceReagent);if(r)openReagentDetail(data,r)});$$('[data-resource-lot-global]').forEach(x=>x.onclick=()=>{const [rid,lid]=x.dataset.resourceLotGlobal.split('|').map(Number),r=(data.reagents||[]).find(v=>v.id===rid),l=r?.lots?.find(v=>v.id===lid);if(r&&l)openLotDetail(data,r,l)});$$('[data-go]').forEach(x=>x.onclick=()=>go(x.dataset.go))}

let nahChatTimer=null;let nahActiveRoom=0;
// A successful POST is the authoritative acknowledgement. A GET already in flight
// before that POST must never hide the message on the sending device.
let nahChatLoadSequence=0;let nahChatPolling=false;
const nahChatAcknowledged=new Map();
const nahChatMembers=new Map(),nahChatReadMarked=new Map(),nahChatSelectedMentions=new Map();
let nahChatMentionMatches=[];let nahChatMentionSelection=0;
function chatHighlightedBody(m){
 const text=String(m.body||''),roomId=Number(m.room_id)||nahActiveRoom;
 const mentioned=new Set((m.mentions||[]).map(String));
 const names=(nahChatMembers.get(roomId)||[]).filter(u=>mentioned.has(String(u.ref))).map(u=>'@'+u.name).sort((a,b)=>b.length-a.length);
 if(!names.length)return esc(text);
 const re=new RegExp('('+names.map(x=>x.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')(?![\\p{L}\\p{N}_])','gu');
 return text.split(re).map(part=>names.includes(part)?`<strong class="chat-mention">${esc(part)}</strong>`:esc(part)).join('');
}
function chatMentionSuggestions(input,roomId){
 const box=$('#chatMentionSuggestions');if(!box)return;
 const before=input.value.slice(0,input.selectionStart||0),match=before.match(/(^|\s)@([^\s@]*)$/u);
 if(!match){box.hidden=true;nahChatMentionMatches=[];return;}
 const q=(match[2]||'').toLocaleLowerCase('vi-VN');
 const users=nahChatMembers.get(roomId)||[];
 nahChatMentionMatches=users.filter(u=>String(u.ref)!==String(state.boot?.user?.ref)&&(!q||u.name.toLocaleLowerCase('vi-VN').includes(q))).slice(0,8);
 if(!nahChatMentionMatches.length){box.hidden=true;return;}
 nahChatMentionSelection=0;
 box.innerHTML=nahChatMentionMatches.map((u,i)=>`<button type="button" role="option" class="chat-mention-option" data-mention-index="${i}" aria-selected="${i===0}">@${esc(u.name)}${u.username?`<small> · ${esc(u.username)}</small>`:''}</button>`).join('');
 box.hidden=false;
 [...box.querySelectorAll('[data-mention-index]')].forEach(b=>b.onmousedown=e=>{e.preventDefault();chatInsertMention(input,roomId,Number(b.dataset.mentionIndex))});
}
function chatInsertMention(input,roomId,i){
 const u=nahChatMentionMatches[i];if(!u)return;
 const caret=input.selectionStart||0,before=input.value.slice(0,caret),match=before.match(/(^|\s)@([^\s@]*)$/u);
 if(!match)return;
 const start=caret-match[0].length+(match[1]?match[1].length:0);
 input.value=input.value.slice(0,start)+'@'+u.name+' '+input.value.slice(caret);
 const next=start+u.name.length+2;input.setSelectionRange(next,next);input.focus();
 const chosen=nahChatSelectedMentions.get(roomId)||new Map();chosen.set(String(u.ref),u.name);nahChatSelectedMentions.set(roomId,chosen);
 $('#chatMentionSuggestions').hidden=true;nahChatMentionMatches=[];
}
function wireChatMentions(input){
 if(!input)return;
 input.addEventListener('input',()=>chatMentionSuggestions(input,nahActiveRoom));
 input.addEventListener('click',()=>chatMentionSuggestions(input,nahActiveRoom));
 input.addEventListener('keydown',e=>{const box=$('#chatMentionSuggestions');if(!box||box.hidden||!nahChatMentionMatches.length)return;
  if(e.key==='Escape'){e.preventDefault();box.hidden=true;return}
  if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();nahChatMentionSelection=(nahChatMentionSelection+(e.key==='ArrowDown'?1:-1)+nahChatMentionMatches.length)%nahChatMentionMatches.length;[...box.querySelectorAll('[data-mention-index]')].forEach((b,i)=>b.setAttribute('aria-selected',String(i===nahChatMentionSelection)));return}
  if(e.key==='Enter'||e.key==='Tab'){e.preventDefault();chatInsertMention(input,nahActiveRoom,nahChatMentionSelection)}
 });
 input.addEventListener('blur',()=>{setTimeout(()=>{const box=$('#chatMentionSuggestions');if(box)box.hidden=true},150)});
}
async function chatMarkRead(roomId,messages){
 if(state.module!=='discussions'||nahActiveRoom!==roomId||document.hidden||!state.boot)return;
 const last=Math.max(0,...(messages||[]).map(m=>Number(m.id)||0));if(!last)return;
 const key=String(state.boot.user.ref)+':'+roomId,previous=nahChatReadMarked.get(key)||0;if(last<=previous)return;
 try{const result=await api(`chat/rooms/${roomId}/read`,{method:'POST',json:{last_id:last}});
  nahChatReadMarked.set(key,Math.max(last,previous));
  if(result?.notifications&&state.boot?.user){state.boot.notifications=result.notifications;updateNotifBadge()}
  const roomBtn=$(`[data-chat-room="${roomId}"]`);if(roomBtn){const badge=roomBtn.querySelector('.chat-room-unread');if(badge){badge.remove();}roomBtn.setAttribute('aria-label','Nhóm đã đọc');}
 }catch(_e){}
}

function chatMessageHtml(m){return `<article class="chat-bubble" data-chat-message-id="${Number(m.id)||0}"><div><strong>${esc(m.sender_name)}</strong><time>${esc(m.created_at)}</time></div><p>${chatHighlightedBody(m)}</p></article>`}
function chatRememberAcknowledged(roomId,message){
 if(!message||!(Number(message.id)>0))return;
 const known=nahChatAcknowledged.get(roomId)||[];
 if(!known.some(m=>Number(m.id)===Number(message.id)))known.push(message);
 nahChatAcknowledged.set(roomId,known.slice(-30));
}
function chatMergeAcknowledged(roomId,serverRows){
 const rows=Array.isArray(serverRows)?serverRows:[];
 const ids=new Set(rows.map(m=>Number(m.id)));
 const confirmed=nahChatAcknowledged.get(roomId)||[];
 nahChatAcknowledged.set(roomId,confirmed.filter(m=>!ids.has(Number(m.id))));
 // Keep locally acknowledged server writes visible until the GET list catches up.
 return [...rows,...confirmed.filter(m=>!ids.has(Number(m.id)))].sort((a,b)=>Number(a.id)-Number(b.id));
}
function chatRenderMessages(roomId,rows,forceScroll){
 const pane=$('#chatMessageList');
 if(!pane||!pane.isConnected||state.module!=='discussions'||nahActiveRoom!==roomId)return;
 const messages=chatMergeAcknowledged(roomId,rows);
 const wasNearBottom=pane.scrollTop+pane.clientHeight+50>=pane.scrollHeight;
 const signature=messages.map(m=>m.id).join(',');
 if(!forceScroll&&pane.dataset.messageIds===signature)return;
 pane.innerHTML=messages.map(chatMessageHtml).join('')||'<div class="empty">Chưa có tin nhắn trong nhóm.</div>';
 pane.dataset.messageIds=signature;
 if(forceScroll||wasNearBottom)pane.scrollTop=pane.scrollHeight;
 if(!document.hidden)void chatMarkRead(roomId,messages);
}
function chatShowSentMessage(roomId,message){
 chatRememberAcknowledged(roomId,message);
 ++nahChatLoadSequence; // Ignore any earlier poll response.
 const pane=$('#chatMessageList');
 if(!pane||!pane.isConnected||nahActiveRoom!==roomId||state.module!=='discussions')return;
 const duplicate=[...pane.querySelectorAll('[data-chat-message-id]')].some(n=>Number(n.dataset.chatMessageId)===Number(message.id));
 if(!duplicate){pane.querySelector('.empty')?.remove();pane.insertAdjacentHTML('beforeend',chatMessageHtml(message));}
 pane.scrollTop=pane.scrollHeight;
 pane.dataset.messageIds=[...pane.querySelectorAll('[data-chat-message-id]')].map(n=>n.dataset.chatMessageId).join(',');
}

async function renderDiscussions(){
 if(nativeClientKind()==='desktop'&&navigator.onLine===false){
  $('#content').innerHTML='<section class="card panel"><h3>Trao đổi nhóm cần kết nối mạng</h3><p>Tin nhắn và lịch sử nhóm được lưu trên máy chủ chung. Kết nối Internet hoặc mạng LAN có đường truy cập máy chủ, sau đó mở lại Trao đổi.</p><button class="btn primary" id="chatOnlineRetry">Thử kết nối lại</button></section>';
  $('#chatOnlineRetry').onclick=()=>renderDiscussions().catch(e=>toast(e.message,'err'));
  return;
 }
 if(nahChatTimer){clearInterval(nahChatTimer);nahChatTimer=null;}
 const [rooms,users,olderResult]=await Promise.all([api('chat/rooms'),api('chat/participants'),api('discussions').catch(()=>[])]);const older=Array.isArray(olderResult)?olderResult:[];
 const memberList=users||[];const canChat=hasCap('comment')||state.boot?.user?.isWpAdmin;
 $('#content').innerHTML=`<section class="chat-workspace"><aside class="chat-sidebar"><div class="chat-heading"><strong>Nhóm trao đổi</strong>${canChat?'<button class="btn small" id="chatCreateRoom">Tạo nhóm</button>':''}</div><div class="chat-room-list" id="chatRoomList">${rooms.map(x=>`<button class="chat-room ${x.id===nahActiveRoom?'active':''}" data-chat-room="${x.id}"><span class="chat-room-head"><strong>${esc(x.title)}</strong>${x.unread_count?`<b class="chat-room-unread">${x.unread_count>99?'99+':x.unread_count}</b>`:''}</span><small>${x.member_count} thành viên · ${esc(x.updated_at)}</small></button>`).join('')||'<p class="note">Chưa có nhóm trao đổi.</p>'}</div><details class="chat-record-discussions"><summary>Trao đổi theo hồ sơ · ${older.length}</summary>${older.slice(0,40).map(x=>`<button class="chat-record-link" data-record="${x.record_id}"><strong>${esc(x.record_title)}</strong><small>${esc(x.user_name)} · ${esc(x.comment)}</small></button>`).join('')}</details></aside><section class="chat-conversation"><header id="chatConversationTitle">Chọn nhóm để trao đổi</header><div id="chatMessageList" class="chat-messages" role="log" aria-live="polite"><div class="empty">Lịch sử trao đổi sẽ xuất hiện tại đây.</div></div><form id="chatCompose"><div class="chat-compose-editor"><div class="chat-mention-suggestions" id="chatMentionSuggestions" role="listbox" aria-label="Đề cập thành viên" hidden></div><textarea name="body" maxlength="4000" rows="2" placeholder="Nhập tin nhắn, dùng @ để đề cập thành viên…" ${canChat?'':'disabled'} required></textarea></div><button class="btn primary" ${canChat?'':'disabled'}>Gửi tin nhắn</button></form><div class="chat-delivery-status" id="chatDeliveryStatus" role="status" aria-live="polite"></div></section></section>`;
 $$('[data-chat-room]').forEach(b=>b.onclick=()=>activateChatRoom(+b.dataset.chatRoom,rooms));
 $$('[data-record]').forEach(b=>b.onclick=()=>openRecord(+b.dataset.record));
 $('#chatCreateRoom')?.addEventListener('click',()=>{openDrawer('Tạo nhóm trao đổi','discussions',`<form id="chatNewGroup"><div class="field"><label>Tên nhóm</label><input name="title" required maxlength="190" placeholder="Ví dụ: Nhóm ISO Khoa Xét nghiệm"></div><div class="section-title">Thành viên</div><div class="er-share-options">${memberList.map(u=>`<label><input type="checkbox" data-chat-member="${esc(u.ref)}"> ${esc(u.name)}</label>`).join('')}</div><div class="form-actions"><button class="btn primary">Tạo nhóm</button></div></form>`,{layout:'modal'});const form=$('#chatNewGroup');form.onsubmit=async e=>{e.preventDefault();try{const result=await api('chat/rooms',{method:'POST',json:{title:form.elements.title.value,members:[...form.querySelectorAll('[data-chat-member]:checked')].map(x=>x.dataset.chatMember)}});closeDrawer();nahActiveRoom=result.id;await renderDiscussions()}catch(err){toast(err.message,'err')}}});
  const f=$('#chatCompose');wireChatMentions(f.elements.body);f.onsubmit=async e=>{
   e.preventDefault();const body=f.elements.body.value.trim(),roomId=nahActiveRoom;
   if(!body||!roomId)return;
   const button=f.querySelector('button'),input=f.elements.body,status=$('#chatDeliveryStatus');
   const mentions=[...(nahChatSelectedMentions.get(roomId)||new Map())].filter(([ref,name])=>body.includes('@'+name)).map(([ref])=>ref);
   button.disabled=true;input.readOnly=true;if(status)status.textContent='Đang gửi tin nhắn…';
   try{
    const saved=await api(`chat/rooms/${roomId}/messages`,{method:'POST',json:{body,mentions}});
    if(!saved||!saved.id||Number(saved.room_id)!==roomId)throw new Error('Máy chủ chưa xác nhận tin nhắn. Vui lòng tải lại lịch sử để kiểm tra trước khi gửi lại.');
    chatShowSentMessage(roomId,saved); // Render the 201 acknowledgement immediately, not a stale GET.
    if(f.isConnected)f.reset();nahChatSelectedMentions.delete(roomId);
    if(status?.isConnected)status.textContent='Đã gửi và lưu trên máy chủ';
    // A fresh read reconciles other devices without delaying the sent message.
    void loadChatMessages(roomId,false).catch(()=>{});
   }catch(err){if(status?.isConnected)status.textContent='Gửi chưa được xác nhận. Nội dung vẫn còn trong ô nhập.';toast(err.message,'err')}
   finally{if(f.isConnected){button.disabled=false;input.readOnly=false}}
  };
 if(rooms.length){if(!rooms.some(r=>r.id===nahActiveRoom))nahActiveRoom=rooms[0].id;await activateChatRoom(nahActiveRoom,rooms)}else nahActiveRoom=0;
 nahChatTimer=setInterval(()=>{if(state.module!=='discussions'){clearInterval(nahChatTimer);nahChatTimer=null;return;}if(nahActiveRoom&&!nahChatPolling){nahChatPolling=true;void loadChatMessages(nahActiveRoom,false).catch(()=>{}).finally(()=>{nahChatPolling=false});}},8000);
}
async function activateChatRoom(id,rooms){
 nahActiveRoom=id;++nahChatLoadSequence;
 $$('[data-chat-room]').forEach(b=>b.classList.toggle('active',+b.dataset.chatRoom===id));
 const room=rooms.find(x=>x.id===id),pane=$('#chatMessageList');
 $('#chatConversationTitle').textContent=room?room.title:'Nhóm trao đổi';
 const suggestionBox=$('#chatMentionSuggestions');if(suggestionBox)suggestionBox.hidden=true;
 // Only members of the active room can be suggested or mentioned.
 nahChatMembers.set(id,[]);
 try{const members=await api(`chat/rooms/${id}/members?_=${Date.now()}`,{cache:'no-store',noDedupe:true});if(nahActiveRoom===id)nahChatMembers.set(id,Array.isArray(members)?members:[])}catch(_e){}
 if(nahActiveRoom!==id)return;
 if(pane){pane.innerHTML='<div class="empty">Đang tải tin nhắn…</div>';delete pane.dataset.messageIds;}
 const status=$('#chatDeliveryStatus');if(status)status.textContent='';
 await loadChatMessages(id,true);
}
async function loadChatMessages(id,scroll){
 const pane=$('#chatMessageList');if(!pane||state.module!=='discussions'||nahActiveRoom!==id)return;
 const seq=++nahChatLoadSequence;
 // Defeat intermediary/WebView2 caches and bypass shared in-flight GET deduplication.
 const rows=await api(`chat/rooms/${id}/messages?_=${Date.now()}`,{cache:'no-store',noDedupe:true,timeoutMs:15000});
 if(seq!==nahChatLoadSequence||nahActiveRoom!==id||!pane.isConnected||pane!==$('#chatMessageList'))return;
 chatRenderMessages(id,rows,scroll);
}

async function renderNotifications(){
 const [rows,counts]=await Promise.all([api('notifications'),api(`notifications/summary?_=${Date.now()}`,{cache:'no-store',noDedupe:true})]);
 if(state.boot){state.boot.notifications=counts;updateNotifBadge()}
 const n=Array.isArray(rows)?rows:[];
 const cards=[['chat','Tin nhắn chưa đọc','discussions'],['overdue','Công việc quá hạn','tasks'],['assignments','Nhiệm vụ mới được giao','tasks'],['other','Thông báo khác',null]];
 const summary=cards.map(([key,label,dest])=>`<button class="notification-summary-item" ${dest?`data-notif-nav="${dest}"`:'data-other-notices="1"'}><strong data-notification-count="${key}">${Number(counts[key])||0}</strong><span>${label}</span>${key==='chat'&&counts.mentions?`<small>${counts.mentions} tin nhắc đến bạn</small>`:''}</button>`).join('');
 const html=n.map(x=>{const roomId=x.type==='chat_mention'?Number(String(x.dedupe_key||'').split(':')[1])||0:0;
 return `<div class="notification ${x.is_read?'':'unread'}" data-notif="${x.id}"><div class="notif-main"><strong>${esc(x.title)}</strong><div class="meta">${esc(x.created_at)}</div><p>${esc(x.body||'')}</p></div><div class="notification-actions">${roomId?`<button class="btn small" data-notif-chat="${roomId}">Mở nhóm</button>`:''}${x.record_id?`<button class="btn small" data-open-record="${x.record_id}">Mở</button>`:''}${!x.is_read?`<button class="btn small" data-mark="${x.id}">Đã đọc</button>`:''}</div></div>`}).join('')||'<div class="card empty">Không có thông báo.</div>';
 $('#content').innerHTML=`<div class="toolbar"><div><strong>Thông báo của tôi</strong><div class="panel-sub"><span data-notification-count="unread">${Number(counts.unread)||0}</span> mục cần chú ý · Tin nhắn được đánh dấu đã đọc khi mở nhóm</div></div><button class="btn small" id="readAll">Đánh dấu các thông báo đã đọc</button></div><section class="notification-summary" aria-label="Tổng hợp thông báo">${summary}</section><div class="notification-list">${html}</div>`;
 $$('[data-notif-nav]').forEach(b=>b.onclick=()=>go(b.dataset.notifNav));
 $('[data-other-notices]')?.addEventListener('click',()=>$('.notification-list')?.scrollIntoView({behavior:'smooth',block:'start'}));
 $$('[data-notif-chat]').forEach(b=>b.onclick=()=>{nahActiveRoom=Number(b.dataset.notifChat);go('discussions')});
 $$('[data-open-record]').forEach(b=>b.onclick=e=>{e.stopPropagation();openRecord(+b.dataset.openRecord)});
 $$('[data-mark]').forEach(b=>b.onclick=async e=>{e.stopPropagation();try{await api(`notifications/${b.dataset.mark}/read`,{method:'POST'});await refreshBootstrapLight();await renderNotifications()}catch(err){toast(err.message,'err')}});
 $('#readAll')?.addEventListener('click',async()=>{try{await api('notifications/read-all',{method:'POST'});await refreshBootstrapLight();await renderNotifications()}catch(e){toast(e.message,'err')}});
}
